SELECT 'moj-all-verified-judgments-review-002-chunk-149' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"da505033-dc00-57fa-a00a-48b73fafea4e","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مسروق -سرقة مبلغ مالي من منزل -إدانة يف احلق العام - مترجم -بينة غير موصلة -اليمن على نفي الدعوى حق للمدعي وله عدم قبولها -احلكم برد الدعوى -استحقاق املدعي ليمن املدعى عليه على نفي الدعوى متى طلبها.","document_number":"34355584","case_number":"33561481","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/10","year":"1434","subject":"رد مسروق -سرقة مبلغ مالي من منزل -إدانة يف احلق العام - مترجم -بينة غير موصلة -اليمن على نفي الدعوى حق للمدعي وله عدم قبولها -احلكم برد الدعوى -استحقاق املدعي ليمن املدعى عليه على نفي الدعوى متى طلبها.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/11/10 :‬هـ‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪34355584 :‬‬\n                           ‫َر ْق ُم الدعوى‪33561481:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 35122590‬تاريخه‪1435/1/22:‬هـ‬\n\n\n       ‫رد مســروق ‪ -‬ســرقة مبلــغ مالــي مــن منــزل ‪ -‬إدانــة يف احلــق العــام ‪-‬‬\n       ‫مترجــم ‪ -‬بينــة غيــر موصلــة ‪ -‬اليمــن علــى نفــي الدعوى حــق للمدعي‬\n       ‫ولــه عــدم قبولهــا ‪ -‬احلكــم بــرد الدعــوى ‪ -‬اســتحقاق املدعــي ليمــن‬\n                             ‫املدعــى عليــه علــى نفــي الدعــوى متــى طلبهــا‪.‬‬\n\n\n\n\n       ‫‪ -1‬قــول النبــي صلــى اهلل عليــه وســلم‪ ( :‬لــو يعطــى النــاس بدعواهــم‬\n       ‫الدعــى نــاس دمــاء رجــال وأموالهــم ولكــن اليمــن علــى املدعــى عليــه)‬\n                                                                      ‫متفــق عليــه‪.‬‬\n       ‫‪ -2‬قــول النبــي صلــى اهلل عليــه وســلم‪( :‬البينــة علــى املدعــي واليمــن‬\n                                                 ‫علــى مــن أنكــر) رواه البيهقــي ‪.‬‬\n\n\n\n\n       ‫ادعــى املدعــي بــأن املدعــى عليهــا قامــت بســرقة مبلــغ مالــي مــن شــنطة‬\n       ‫كانــت يف منزلــه َّإبــان عملهــا لديــه كخادمــة منزليــة؛ وطلــب إلزامهــا‬\n       ‫بــرد املبلــغ املســروق ‪ -‬أنكــرت املدعــى عليهــا دعــوى املدعــي جتاههــا‬\n       ‫ســوى العثــور علــى جــزء مــن املبلــغ يف غرفتهــا ‪ -‬قــدم املدعــي بينــات‬\n       ‫غيــر موصلــة ولــم يقبــل ميــن املدعــى عليهــا علــى نفــي دعــواه‪ -‬مــن املقــرر‬\n       ‫شــرعا أن البينــة علــى املدعــي واليمــن علــى املدعــى عليــه ‪ -‬فقــد قضــت‬\n\n‫‪209‬‬\n\f‫احملكمــة بصــرف النظــر عــن طلــب املدعــي وأفهمتــه بــأن لــه ميــن‬\n‫املدعــى عليهــا متــى طلبهــا ‪ -‬قنعــت املدعــى عليهــا باحلكــم وعــارض‬\n ‫عليــه املدعــي ‪ -‬قــررت محكمــة االســتئناف املوافقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالطائــف برقــم ‪ 33561481‬وتاريــخ ‪ 1433/09/04‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 331640237‬وتاريــخ ‪ 1433/09/03‬ه ـ ففــي يــوم‬\n‫األحــد املوافــق ‪ 1433/11/14‬ه ـ افتتحــت اجللســة الســاعة ‪12 : 00‬‬\n‫وفيهــا حضــر ســعودي اجلنســية‪ ......./‬مبوجــب ســجله املدنــي رقــم‪....../‬‬\n‫وحضــرت حلضــوره‪ ......../‬إندونيســية اجلنســية مبوجــب اجلــواز رقــم‪......./‬‬\n‫واملعــرف بهــا مــن قبــل مشــرفة التفتيــش علــى النســاء باحملكمــة ثــم‬\n‫ادعــى األول قائــا يف دعــواه إن املدعــى عليهــا كانــت تعمــل لــدي‬\n‫كخادمــة منزليــة ثــم إنه يف صباح يوم األربعاء املوافق ‪1433/01/19‬هـ‬\n‫كنــت نائمــا حيــث عملــت عمليــة جراحيــة وكان لــدي شــنطة وفيهــا‬\n‫مبلــغ وقــدره مائــة وخمســة عشــر ألــف ريــال وجــوازات ســفر وثــاث‬\n‫جــواالت نــوع ‪ ...‬وعلبــة فيهــا ذهــب وملــا عــادت زوجتــي بعــد الظهــر لــم‬\n‫جتــد الشــنطة فقمنــا بالبحــث يف البيــت ثــم وجدنــا الشــنطة علــى ســطح‬\n‫البيــت وهــي مكســورة وقــد ألقــي مــا فيهــا مــن جــوازات ســفر وجــوالت‬\n‫وذهــب بجوارهــا وأمــا املبلــغ املالــي فلــم يعثــر عليه وبعد أن بلغنا الشــرطة‬\n‫أرشــدت املدعــى عليهــا إلــى قطعــة إســمنتية ( بلــك ) وجــد حتتهــا مبلــغ‬\n‫وقــدره ســبعة عشــر ألــف وأربعمائــة وســتة عشــر ريــاال كمــا مت تفتيــش‬\n                                                                                     ‫‪210‬‬\n\f      ‫غرفــة املدعــى عليهــا وعثــر فيهــا علــى مبلــغ وقــدره ثالثــون ألــف ريــال‬\n      ‫وقــد صــدر يف احلــق العــام قــرار مــن احملكمــة اجلزئيــة بالطائــف برقــم‬\n      ‫‪ 33286491‬يف تاريــخ ‪1433/06/08‬ه ـ ويتضمــن إثبــات إدانــة املدعــى‬\n      ‫عليهــا بســرقة مبلــغ مالــي مــن حــرز وهــذا القــرار مصــدق مــن محكمــة‬\n      ‫االســتئناف وبقــي لديهــا مبلــغ وقــدره ســتة وثمانــون ألــف وخمســمائة‬\n      ‫وثالثــة وثمانــون ريــاال أطلــب احلكــم عليهــا بدفعــه لــي هــذه دعــواي‬\n      ‫ونظــرا ألن املدعــى عليهــا ال تتقــن العربيــة وألنــه ال يوجــد مترجــم‬\n      ‫باحملكمــة جــرى رفــع اجللســة وتأجيلهــا ويف جلســة اخــرى يف يــوم األحــد‬\n      ‫املوافــق‪ 1434/01/11‬ه ـ حضــر املدعــي وأمــا املدعــى عليهــا فلم حتضر‬\n      ‫ونظــرا لكــون املدعــى عليهــا ســجينه بالســجن العــام بالطائــف فلــم تيــم‬\n      ‫احضارهــا مــن قبــل الســجن لــذا فقــد قــررت الكتابــة للســجن إلحضــار‬\n      ‫املدعــى عليهــا ويف جلســة أخــرى يف يــوم األحــد املوافــق‪ 1434/02/10‬هـ‬\n      ‫حضــر املدعــي وحضــرت حلضــوره املدعــى عليهــا واملعــرف بهــا مــن قبــل‬\n      ‫مفتشــة النســاء باحملكمــة وحضــر أيضــا بصفتــه مترجــم احملكمــة ثــم‬\n      ‫جــرى عــرض دعــوى املدعــي علــى املدعــى عليهــا بواســطة املترجــم‬\n      ‫فأجابــت قائلــة مــا ذكــره املدعــي يف دعــواه كلــه غيــر صحيــح جملــة‬\n      ‫وتفصيــا ماعــدا أننــي وضعــت مبلــغ وقــدره ثالثــن ألــف ريــال وأنــه‬\n      ‫وجــده املدعــي فــإن ذلــك صحيــح هكــذا أجــاب ثــم جــرى ســؤال املدعــي‬\n      ‫هــل لديــك بينــة علــى أن املدعــى عليهــا قــد ســرقت املبلــغ املذكــور يف‬\n      ‫الدعــوى فقــال ليــس لــدي بينــة ســوى مــا جــاء يف قــرار احملكمــة اجلزئيــة‬\n      ‫املشــار إلــي رقمــه وتاريخــه يف دعــواي ونظــرا النتهــاء وقــت اجللســة جــرى‬\n      ‫رفعهــا وتأجيلهــا ويف جلســة أخــرى يف يــوم األحــد املوافــق‪1434/03/08‬‬\n      ‫ه ـ حضــر املدعــي وأمــا املدعــى عليهــا فهــي ســجينة ولــم حتضــر مــن قبــل‬\n\n\n‫‪211‬‬\n\f‫الســجن وقــد ســبق أن ذكــر املدعــي بــأن بينتــه هــو مــا جــاء يف القــرار‬\n‫الصــادر مــن احملكمــة اجلزئيــة وباالطــاع علــى املعاملــة وجــد ضمــن‬\n‫طياتهــا القــرار رقــم ‪ 33286491‬يف ‪1433/6/8‬ه ـ والصــادر مــن‬\n‫احملكمــة اجلزائيــة بالطائــف واملصــدق مــن محكمــة االســتئناف‬\n‫مبنطقــة مكــة املكرمــة مبوجــب القــرار رقــم ‪ 33286491‬يف تاريــخ‬\n‫‪1433/6/8‬ه ـ واملتضمــن مــا نــص احلاجــة منــه (مــا ذكــره املدعــي العــام‬\n‫مــن أننــي قمــت بســرقة مبلــغ مالــي عائــد لكفيلــي ولــم أقــم بكســر‬\n‫األبــواب وإمنــا وجــدت الشــنطة يف الغرفــة فقمــت بأخــذ الشــنطة مــن‬\n‫دوالب كفيلــي فصحيــح ومــا مــا ذكــره املدعــي العــام مــن مقــدار املبلــغ‬\n‫فأنــا ال أعلــم عنــه بالتحديــد هكــذا أجابــت وبطلــب البينــة مــن املدعــي‬\n‫العــام علــى مقــدار املبلــغ املدعــى بــه قــال بينتــي اعترافهــا املصــدق شــرعا‬\n‫لفــه (‪ )4‬ص (‪ )15‬واملتضمــن أنــه أثنــاء غيــاب أصحــاب املنــزل عــن‬\n‫منزلهــم قمــت بفتــح الــدوالب اخلــاص باملالبــس التابعــة لهــم واســتيالئي‬\n‫علــى شــنطة بنيــة اللــون وكذلــك كيــس بالســتيكي يوجــد بــه مبلــغ‬\n‫مــن املــال والتوجــه بــه إلــى أعلــى ســطح املنــزل ثــم قمــت بفتــح الشــنطة‬\n‫وأخــذ جميــع املبلــغ املالــي الــذي كان بداخــل الشــنطة والكيــس ثــم‬\n‫قمــت بتجزئتــه إلــى جزأيــن أحــد اجلزأيــن قمــت بوضعــه فــوق الســطح‬\n‫حتــت أحــد القطــع اإلســمنتية والقســم اآلخــر قمــت بوضعــه بداخــل‬\n‫ســيفون دورة امليــاه اخلاصــة بــي وكان هــذا العمــل مبفــردي ولــم يكــن‬\n‫معــي أي شــخص آخــر ولــم أجــد فيــه مــا ينــص علــى مقــدار املبلــغ يف‬\n‫اعترافهــا وبســؤال املدعــي العــام هــل لديــك زيــادة بينــة أجــاب قائــا‬\n‫اكتفــى مبــا يف أوراق املعاملــة مــن بينــات ولــم أجــد فيهــا مــا يعضــد‬\n‫دعــواه يف إثبــات مقــدار املبلــغ فضــا أن بعضهــا ممــا ذكــره املبلــغ‬\n\n\n                                                                                        ‫‪212‬‬\n\f      ‫وزوجتــه ومــا ذكــراه دعــوى حتتــاج إلــى بينــة وبنــاء علــى مــا تقــدم مــن‬\n      ‫الدعــوى واإلجابــة وحيــث صادقــت املدعــى عليهــا علــى ســرقة مبلــغ‬\n      ‫مالــي ونظــرا لكــون مــا أقدمــت عليــه املدعــى عليهــا يعــد عمــا محرمــا‬\n      ‫وفعــل قبيــح وجــرأة يف الباطــل واعتــداء علــى أمــوال النــاس بغيــر حــق‬\n      ‫ولقولــه صلــى اهلل عليــه وســلم (ال يحــل مــال امــرئ مســلم إال بطيــب نفس‬\n      ‫منــه) لهــذا كلــه فقــد ثبــت لــدي إدانــة املدعــى عليهــا بســرقة مبلــغ مالــي‬\n      ‫مــن دون حرز)أ‪.‬ه ـ ثــم أضــاف املدعــي أن املدعــى عليهــا لهــا إقــرار‬\n      ‫مصــدق شــرعا علــى اللفــة رقم ‪ 4‬ص ‪ 15‬ضمــن طيات املعاملة وباالطالع‬\n      ‫عليــه وجــد يتضمــن مــا نصــه (أقــر أنــا املدعــوة‪ /‬إندونيســية اجلنســية‬\n      ‫مبوجــب اجلــواز رقــم وإقامــة رقــم أقــر لــدى جهــة التحقيــق بداخــل شــعبة‬\n      ‫الســجن العــام وأنــا بكامــل قــواي العقليــة املعتبــرة شــرعا ال مجبــره وال‬\n      ‫مكرهــه مــن أحــد أقــر بأننــي قمــت بدخــول غرفــة زوجــة كفيلــي يف‬\n      ‫يــوم األربعــاء املوافــق ‪1433/1/19‬ه ـ وأثنــاء غيابهــم عــن املنــزل قمــت‬\n      ‫بفتــح الــدوالب اخلــاص باملالبــس التابعــة لهــم واســتيالئي علــى شــنطة‬\n      ‫بنيــة اللــون وكذلــك كيــس بالســتيكي يوجــد بــه مبلــغ مــن املــال‬\n      ‫والتوجــه بــه إلــى أعلــى ســطح املنــزل ثــم قمــت بفتــح هــذه الشــنطة‬\n      ‫والكيــس ثــم قمــت بتجزئتــه إلــى جزأيــن أحــد هــذه اجلزأيــن قمــت‬\n      ‫بوضعــه فــوق الســطح حتــت أحــد القطــع اإلســمنتية (بلــك) واجلــزء اآلخــر‬\n      ‫قمــت بوضعــه يف كيــس بالســتيكي ووضعتــه بداخــل ســيفون دورة‬\n      ‫امليــاه يف الــدور األســفل مــن منــزل كفيلــي وقمــت بإلقــاء الشــنطة فــوق‬\n      ‫ســطح غرفــة الــدرج و كان هــذا العمــل قمــت بــه مبفــردي ولــم يكــن‬\n      ‫معــي أي شــخص آخــر وكنــت أحــاول التهــرب والتخلــص ممــا نســب إلــي‬\n      ‫مــن تهمــه إال أننــي لــم أســتطع ذلــك وعلــى هــذا أســجل إقــرار واعتــرايف‬\n\n\n‫‪213‬‬\n\f‫وعلــى ذلــك أوقــع) وحتــى حتضــر املدعــى عليهــا لعــرض ذلــك عليهــا‬\n‫جــرى رفــع اجللســة وتأجيلهــا ويف جلســة أخــرى يف يــوم األحــد املوافــق‬\n‫‪ 1434/04/14‬ه ـ حضــر املدعــي وحضــرت حلضــوره املدعــى عليهــا‬\n‫وحضــر مترجــم احملكمــة ‪ ...‬ثــم جــرى ســؤال املدعــي هــل لديــك زيــادة‬\n‫بينــة فقــال ليــس لــدي زيــادة بينــة هكــذا قــرر ونظــرا ألن مترجــم‬\n‫احملكمــة احلاضــر ال يتقــن اللغــة اإلندونيســية جــرى رفــع اجللســة‬\n‫إلحضــار مترجــم آخــر ويف جلســة أخــرى يف يــوم األربعــاء املوافــق‬\n‫‪ 1434/05/22‬ه ـ حضــر املدعــي واملدعــى عليهــا واملعــرف بهــا مــن قبلــه‬\n‫ولــم يحضــر املترجــم وقــد جــرت مهاتفــة قســم اخلبــراء باحملكمــة‬\n‫وأفــادوا بأنــه تعــذر حضــوره لهــذا اليــوم ويرغبــون يف حتديــد موعــد آخــر‬\n‫للجلســة ليتســنى لهــم إحضــاره وقــد قــرر املدعــي قائــا لقــد راجعــت‬\n‫قســم النزهــة وطلبــت منهــم تزويــدي بإثباتــات تتعلــق بالقضيــة فأفادنــي‬\n‫مديــر قســم شــرطة النزهــة بــأن إثباتــات القضيــة جميعهــا مرفقــة‬\n‫باملعاملــة وأهــم إثبــات مــدون يف دفاتــر التحقيــق هكــذا قــال ثــم أضــاف‬\n‫أطلــب مــن فضيلتكــم االطــاع عليهــا هكــذا قــرر وحتــى يحصــل ذلــك‬\n‫ويتــم حضــور املترجــم جــرى رفــع اجللســة وتأجيلهــا ويف جلســة أخــرى يف‬\n‫يــوم األحــد املوافــق ‪1434/07/02‬ه ـ حضــر املدعــي وحضــرت حلضــوره‬\n‫املدعــى عليهــا واملعــرف بهــا مــن قبلــه وقــد ســبق وأن رفعــت اجللســة لطلب‬\n‫مترجــم وطلــب املعاملــة األساســية لالطــاع علــى البيانــات التــي يطلــب‬\n‫املدعــي االطــاع عليهــا عليــه فقــد جــرى بعــث أوراق املعاملــة وباالطــاع‬\n‫عليهــا وســؤال املدعــي عــن بينتــه فيهــا قــال بينتــي هــي‪ :‬أوالً‪ :‬إقرارهــا‬\n‫املصــدق شــرعاً‪ .‬ثاني ـاُ‪ :‬محضــر تفتيــش غرفــة املدعــى عليهــا حيــث‬\n‫تضمــن العثــور علــى مبلــغ ثالثــن ألــف ريــال‪ .‬ثالثـاً‪ :‬محضــر داللتهــا علــى‬\n\n\n                                                                                     ‫‪214‬‬\n\f      ‫مــكان تخبيــة بقيــة املبلــغ‪ .‬هكــذا قــرر‪ .‬وباالطــاع علــى أوراق املعاملــة‬\n      ‫وجــد علــى اللفــة رقــم(‪ )4‬إقــرار مصــدق شــرع ًا مــن احملكمــة اجلزئيــة‬\n      ‫بالطائــف ونصه(أقــر أنــا املدعــوة‪ ......./‬إندونيســية اجلنســية مبوجــب‬\n      ‫اإلقامــة رقــم‪ ....../‬أقــر لــدى جهــة التحقيــق بداخــل شــعبة الســجن العــام‬\n      ‫وأنــا بكامــل قــواي العقليــة املعتبــرة شــرع ًا ال مجبــرة وال مكرهــه مــن‬\n      ‫أحــد أقــر بأننــي قمــت بدخــول غرفــة زوجــة كفيلــي يف يــوم األربعــاء‬\n      ‫املوافــق ‪1433/1/19‬ه ـ وأثنــاء غيابهــم عــن املنــزل قمــت بفتــح الــدوالب‬\n      ‫اخلــاص باملالبــس التابعــة لهــم واســتيالئي علــى شــنطة بنيــة اللــون‬\n      ‫وكذلــك كيــس بالســتيكي يوجــد بــه مبلــغ مــن املــال والتوجــه بــه إلــى‬\n      ‫أعلــى ســطح املنــزل ثــم قمــت بفتــح هــذه الشــنطة وهــذا الكيــس وأخــذ‬\n      ‫جميــع املبلــغ املالــي الــذي كان يوجــد داخــل الشــنطة والكيــس ثــم‬\n      ‫قمــت بتجزئتــه إلــى جزأيــن أحــد هــذه اجلزأيــن قمــت بوضعــه فــوق‬\n      ‫الســطح حتــت أحــد القطــع اإلســمنتية (بلــك) واجلــزء اآلخر قمــت بوضعه‬\n      ‫يف كيــس بالســتيكي ووضعتــه بداخــل ســيفون دورة امليــاه اخلاصــة بــي‬\n      ‫يف الــدور األســفل مــن منــزل كفيلــي وقمــت بإلقــاء الشــنطة فــوق ســطح‬\n      ‫غرفــة الــدرج وهــذا العمــل قمــت بــه مبفــردي ولــم يكــن معــي أي شــخص‬\n      ‫آخــر وكنــت أحــاول التهــرب والتخلــص ممــا نســب إلــي مــن تهمــة إال‬\n      ‫إننــي لــم أســتطع ذلــك وعلــى هــذا أســجل إقــراري واعتــرايف وعلــى ذلــك‬\n      ‫أوقــع)‪ .‬ونظــر ًا النتهــاء وقــت اجللســة جــرى رفعهــا وتأجيلهــا ويف جلســة‬\n      ‫أخــرى يف يــوم الثالثــاء املوافــق‪ 1434/07/25‬ه ـ حضــر املدعي واملدعى‬\n      ‫علهــا واملعــرف بهــا مــن قبلــه وأمــا املترجــم فلــم يحضــر وقــد ســبقت‬\n      ‫الكتابــة لفضيلــة رئيــس احملكمــة وذلــك مبوجــب خطابنــا رقــم‬\n      ‫‪ 341724431‬يف ‪ 1434/7/17‬هـ وذلك بطلب مترجم للغة اإلندونيسية‬\n\n\n‫‪215‬‬\n\f‫لغــة املدعــى عليهــا وأحيــل هــذا اخلطــاب بشــرح رئيــس احملكمــة إلــى‬\n‫قســم اخلبــراء ثــم أعيــد إلينــا بشــرح رئيــس قســم اخلبــراء واملتضمــن ( أنــه‬\n‫ال يوجــد لديهــم مترجــم للغــة اإلندونيســية)‪.‬أ‪ .‬ه ـ وقــد ســبق أن ذكــر‬\n‫املدعــي أن بينتــه هــي إقــرار املدعــى عليهــا املصــدق شــرعا ومحضــر‬\n‫تفتيــش غرفــة املدعــى عليهــا ومحضــر داللتهــا وســبق رصــد إقرارهــا ثــم‬\n‫جــرى االطــاع علــى أوراق املعاملــة فوجــد علــى اللفــة رقــم ‪ 4‬ص ‪ 7‬مــا‬\n‫نصــه (بحضورنــا نحــن املوقعــن أدنــاه ويف متام الســاعة الواحدة والنصف‬\n‫مــن مســاء يــوم االثنــن املوافــق أعــاه جــرى االنتقــال إلــى منــزل املدعــو‬\n‫‪ ...‬الواقــع بحــي ‪ ...‬بالدخــول إلــى املنــزل برفقة املذكور تفتيش الســكن‬\n‫اخلــاص باخلادمــة املدعــوة ‪ ...‬وبتفتيشــه عثــر علــى مبلــغ ‪30000‬ريــال‬\n‫ملفوفــة داخــل كيــس بالســتيكي وجهــاز جــوال بداخــل محفظــة‬\n‫ســوداء مــن نــوع ‪ ...‬لونــه أبيــض وكان املبلــغ واجلــوال موجــود بداخــل‬\n‫ســيفون املــاء اخلــاص بــدورة امليــاه اخلاصــة بتلــك الغرفــة هــذا وحفظــا‬\n‫للحقيقــة والواقــع نظــم هــذا احملضــر وقــد جــرى تصويــر املوقــع مــن قبــل‬\n‫املختصــن يف األدلــة اجلنائيــة ) وعلــى اللفــة ‪ 4‬ص‪( 8‬جــرى االطــاع علــى‬\n‫مــا مت ضبطــه مــن مبلــغ مالــي وجهــاز جــوال بداخــل دورة امليــاه اخلاصــة‬\n‫باخلادمــة املدعــوة ‪ ........‬وكانــت املضبوطــات عبــارة عــن مبلــغ وقــدر‬\n‫‪ 30000‬ثالثــون ألــف ريــال جميعهــا مــن فئــة اخلمســمائة ريــال وكانــت‬\n‫ملفوفــة بكيــس بالســتيكي شــفاف يوجــد بــه كتابــة باللــون االصفــر‬\n‫تعــود الحــد املخابــز مخبــز ‪ ...‬وكذلــك جهــاز جــوال مــن نــوع ‪ .....‬لونــه‬\n‫أبيــض موديــل ‪ ......‬كان موضــوع بداخــل محفظــة نســائية ســوداء اللــون‬\n‫وكانــت ملفوفــة بداخــل كيــس بالســتيكي لونــه أزرق) وعلــى ص‬\n‫‪ (11‬ذكــرت جاراواتــي باجيمــن اثنــاء مناقشــتها داخــل الســجن أنــه‬\n\n\n                                                                                       ‫‪216‬‬\n\f      ‫يوجــد مبلــغ ال تعــرف قــدره فــوق ســطح املنــزل وجــرى االنتقــال للمنــزل‬\n      ‫وبالدخــول وتفتيــش ســطح املنــزل داخــل غرفــة وجــد مبلــغ ســبعة عشــر‬\n      ‫ألــف ريــال) ونظــرا النتهــاء الوقــت احملــدد للجلســة ولعــدم حضــور‬\n      ‫املترجــم قــررت رفــع اجللســة والكتابــة مجــددا لفضيلــة رئيــس احملكمة‬\n      ‫لبعــث مترجــم ويف جلســة أخــرى يف يــوم الثالثــاء املوافــق ‪1434/09/08‬‬\n      ‫ه ـ حضــر املدعــي أمــا املدعــى عليــه فلــم حتضــر وهــي ســجينة ولــم يردنــا‬\n      ‫مــن قبــل ســجن شــعبة الســجن إفــادة عــن ســبب عــدم بعثهــا وقــد طلــب‬\n      ‫املدعــي حتديــد موعــد آخــر وحيــث ال مانــع فقــد جــرى رفــع اجللســة‬\n      ‫وتأجيلهــا ويف جلســة أخــرى يف يــوم األحــد املوافــق ‪ 1434/11/09‬ه ـ‬\n      ‫حضــر املدعــي واملدعــى عليهــا وحضــر حلضورهــم اندونيســي اجلنســية‬\n      ‫مبوجــب اإلقامــة رقــم ثــم قــرر املدعــي قائــا لقــد ذكــرت يف دعــواي يف‬\n      ‫أول جلســة إننــي اطالــب مببلــغ وقــدره ســتة وثمانــون ألــف وخمســمائة‬\n      ‫وثالثــة وثمانــون ريــال والصحيــح أننــي أطالــب مببلــغ وقــدره مائــة ألــف‬\n      ‫وألفــن وســتمائة ريــال كمــا أن القــرار املشــار إليــه الصــادر عــن‬\n      ‫احملكمــة اجلزئيــة يتضمــن إدانتهــا بســرقة بــدون حــرز أطلــب تصحيــح‬\n      ‫دعــواي بذلــك هكــذا قــرر ثــم جــرى ســؤال املدعي عما ذكرتــه املدعى‬\n      ‫عليهــا يف اجللســة الثالثــة مــن أنــه اســتلم مبلــغ وقــدره ثالثــون ألــف ريــال‬\n      ‫فأجــاب نعــم ذلــك صحيــح هكــذا قــرر ثــم جــرى عــرض اإلقــرار‬\n      ‫(التحقيقــي) املنســوب للمدعــى عليهــا واملرصــود يف اجللســة الرابعــة‬\n      ‫واإلقــرار املصــدق شــرعا املنســوب للمدعــى عليهــا واملرصــود يف اجللســة‬\n      ‫الســابعة ومــا مت رصــده يف اجللســة الثامنــة مــن محاضــر وذلــك بواســطة‬\n      ‫املترجــم فأجابــت املدعــى عليهــا قائلــة بواســطته‪ :‬مــا ذكــر يف هــذه‬\n      ‫احملاضــر غيــر صحيــح جملــة وتفصيــا فأنــا لــم أســرق أي مبلــغ مالــي‬\n\n\n‫‪217‬‬\n\f‫وإمنــا فتحــي الــدوالب الــذي توجــد فيــه الشــنطة التــي بداخلهــا املــال‬\n‫وكنــت أبحــث عــن جوالــي وأخــذت الشــنطة التــي فيهــا املــال ظنــا منــي‬\n‫أن جوالــي فيهــا وتوجهــت بهــا إلــى الســطح وفتحتهــا بقــوة فانكســرت‬\n‫وتبــن لــي أن جوالــي ليــس فيهــا مبالــغ ماليــة فخفــت مــن ذلــك فوضعــت‬\n‫جــزء مــن املبالــغ املاليــة حتــت (بلكــة) يف الســطح وجــزء حتــت (ســيفون‬\n‫احلمــام ) ولــم أســرق منهــا أي شــيء وقــد وجدوهــا فيمــا بعــد هكــذا‬\n‫قــررت ثــم جــرى ســؤال املدعــي هــل لديــك زيــادة بينــة فقــال ليــس لــدي‬\n‫زيــادة بينــة ثــم جــرى ســؤال املدعــي هــل تطلب ميــن املدعى عليهــا فأجاب‬\n‫قائــا إننــي ال أطلــب ميينهــا وال أرضاهــا هكــذا قــرر ثــم جــرى ســؤال‬\n‫املتداعيــن هــل لديكمــا إضافــة علــى مــا ســبق فقــاال ليــس لدينــا إضافة‬\n‫علــى مــا ســبق هكــذا قــرر ا فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n‫وألن املدعــي ليــس لــه بينــة موصلــة وألن مــا أشــار إليــه املدعــي ممــا جــاء‬\n‫يف املعاملــة مبــا يف ذلــك اإلقــرار املصــدق شــرعا غيــر موصــل فلــم ينــص‬\n‫فيــه علــى املبلــغ املالــي الــذي يطالــب بــه املدعــي كمــا أن املدعــى عليهــا‬\n‫أنكــرت مــا جــاء يف هــذه األقاريــر واحملاضــر وألن املدعــي قــرر بأنــه‬\n‫ليــس لديــه زيــادة بينــة وملــا جــاء يف حديــث ابــن عبــاس قــال رســول اهلل‬\n‫صلــى اهلل عليــه وســلم ( لــو يعطــى النــاس بدعواهــم الدعــى نــاس دمــاء‬\n‫رجــال وأموالهــم ولكــن اليمــن علــى املدعــى عليــه ) متفــق عليــه واللفــظ‬\n‫ملســلم وللبيهقــي ( البينــة علــى املدعــي واليمــن علــى مــن أنكــر ) وألن‬\n‫املدعــي قــرر أنــه ال يطلــب ميــن املدعــى عليهــا لذلــك كلــه فقــد حكمت‬\n‫بصــرف النظــر عــن طلــب املدعــي احلكــم علــى املدعــى عليهــا بدفــع‬\n‫املبلــغ املالــي وأفهمتــه بــان لــه ميــن املدعــى عليهــا متــى طلبهــا وبعــرض‬\n‫احلكــم علــى املدعــي واملدعــى عليهــا قــرر املدعــي عــدم قناعتــه باحلكــم‬\n\n\n                                                                                       ‫‪218‬‬\n\f      ‫وقــررت املدعــى عليهــا قناعتهــا باحلكــم فأفهــم املدعــي بــأن يحضــر‬\n      ‫غــدا االثنــن املوافــق ‪ 1434/11/10‬ه ـ الســتالم نســخة مــن احلكــم‬\n      ‫وأفهــم بتعليمــات االســتئناف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                     ‫محمد وعلى آله وصحبه وسلم ‪ .‬حرر يف ‪ 1434/11/09‬هـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪،‬‬\n      ‫فقــد جــرى منــا نحــن قضــاة االســتئناف بالدائــرة اجلزائيــة السادســة‬\n      ‫مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة جــرى منــا اإلطــاع على‬\n      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بالطائــف برقــم‬\n      ‫(‪ )331640237‬وتاريــخ (‪1435/1/10‬هــ) املرفــق بهــا الصــك الصــادر‬\n      ‫مــن فضيلــة الشــيخ‪ ،........ /‬القاضــي باحملكمــة العامــة بالطائــف برقــم‬\n      ‫(‪ )34355584‬وتاريخ (‪1434/11/10‬هـ) املتضمن دعوى ‪ .......‬ســعودي‬\n      ‫اجلنســية ضــد‪ ....... /‬إندونيســية اجلنســية يف ســرقة مــال‪ ،‬احملكــوم فيــه‬\n      ‫مبــا دون باطنــه‪ ،‬وبدراســة الصــك وصــورة ضبطــه تقــررت املوافقــة‬\n      ‫علــى احلكــم‪ ،‬واهلل املوفــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                  ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪219‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":209,"source_page_end":219,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f67689df5edeb6f0d07132bc3aff58bde86f8e6b9482220955303f71ce0283ff","normalized_text_hash":"34cb33ca5d460dc2bf30796d3050a8001e18bacd17662185c418daca8dd1a229","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p209-34355584"},{"id":"de28c953-a9db-51bf-a63b-1098d7f8f904","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مسروق -سرقة سيارة من ورشة سيارات -تفريط يف حفظ املسروق -تقدير قيمة السيارة عن طريق رئيس معارض السيارات -ضمان األجير املشترك -إلزام املدعى عليه بدفع قيمة السيارة .","document_number":"3437753","case_number":"33626232","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بينبع","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/16","year":"1434","subject":"رد مسروق -سرقة سيارة من ورشة سيارات -تفريط يف حفظ املسروق -تقدير قيمة السيارة عن طريق رئيس معارض السيارات -ضمان األجير املشترك -إلزام املدعى عليه بدفع قيمة السيارة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/2/16 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3437753 :‬‬\n                   ‫َر ْق ُم الدعوى‪33626232:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34373689‬تاريخه‪1434/11/27:‬هـ‬\n\n\n‫رد مســروق ‪ -‬ســرقة ســيارة مــن ورشــة ســيارات ‪ -‬تفريــط يف حفــظ‬\n‫املســروق ‪ -‬تقديــر قيمــة الســيارة عــن طريــق رئيــس معــارض الســيارات‬\n‫‪ -‬ضمــان األجيــر املشــترك ‪ -‬إلــزام املدعــى عليــه بدفــع قيمــة الســيارة ‪.‬‬\n\n\n\n\n‫مــا اســتند إليــه القاضــي مــن مبــادئ عامــة وقواعــد العدالــة الــواردة يف‬\n                                                           ‫تســبيب احلكــم ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي بأنــه ســلم ســيارته للمدعــى عليــه ليقــوم بإصالحهــا يف‬\n‫الورشــة التــي يعمــل بهــا‪ ،‬وملــا حضــر يف اليــوم التالــي لــم يجدهــا فســأل‬\n‫املدعــى عليــه عنهــا فأجابــه بأنــه ال يعلــم؛ ولــذا فقــد طلــب إلزامــه بإعــادة‬\n‫قيمــة تلــك الســيارة إليــه‪ -‬أقــر املدعــى عليه باســتالم الســيارة من املدعي‬\n‫ليقــوم بإصالحهــا وأنهــا فقــدت بعــد ذلــك ودفــع بأنــه أوقــف الســيارة‬\n‫خــارج الورشــة لكونهــا مزدحمــة بعــد أن أغلــق أبوابهــا ‪ -‬مت تقديــر قيمــة‬\n‫الســيارة عــن طريــق رئيــس املعــارض‪ -‬املدعــى عليــه مفــرط يف حفــظ‬\n‫الســيارة التــي اســتلمها ‪ -‬قضــت احملكمــة بإلــزام املدعــى عليــه بتســليم‬\n‫قيمــة الســيارة إلــى املدعــي‪ -‬قنــع املدعــي باحلكــم وعــارض عليــه املدعى‬\n              ‫عليــه ‪ -‬قــررت محكمــة االســتئناف املوافقــة علــى احلكــم ‪.‬‬\n\n                                                                                         ‫‪220‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة بينبــع‬\n      ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫بينبع‪/‬املســاعد برقــم ‪ 33626232‬وتاريــخ ‪ 1433/10/28‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 331706916‬وتاريــخ ‪ 1433/09/16‬ه ـ بشــأن دعــوى‬\n      ‫ففــي يــوم الســبت املوافــق‪ 1433/11/13‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫‪ 08 : 00‬وفيهــا حضــر املدعــي‪ ..../‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫رقــم وحضــر حلضــوره املدعــى عليــه‪ ...../‬باكســتاني اجلنســية مبوجــب‬\n      ‫اإلقامــة رقــم ‪ ...‬ثــم ادعــى املدعــي قائــا ادعــي علــى احلاضــر معــي‬\n      ‫باملجلــس الشــرعي الــذي ســبق وأن ســلمته ســيارتي ‪ ...‬صنــع ‪ ...‬وذلــك‬\n      ‫بتاريــخ تقريبــا ‪1433/8/4‬ه ـ علــى أســاس ان يصلــح فيهــا أشــياء بســيطة‬\n      ‫وادخلتهــا ورشــته ثــم ســلمته املفتــاح واتفقنــا علــى ســعر اإلصــاح ألــف‬\n      ‫ومائتــن ريــال وقــال لــي تعــال بعــد ثالثــة أيــام وجتدهــا جاهــزة ولكننــي‬\n      ‫اســتعجلت وحضــرت إلــى الورشــة اليــوم التالــي إلــى الورشــة ولــم اجــد‬\n      ‫ســيارتي وســألته عنهــا وقــال أنــا ال اعلــم عنهــا شــيئا وقلــت ســوف أذهــب‬\n      ‫للشــرطة وقــال لــي أذهــب وبعــرض الدعــوى املرصــودة بعاليــة علــى‬\n      ‫املدعــى عليــه أجــاب علــى لســان مترجــم احملكمــة بقولــة فعــا اننــي‬\n      ‫اســتلمت ســيارة املدعــي ‪ ...‬وادخلهــا صاحبهــا الورشــة وســلمني املفتــاح‬\n      ‫واتفقــت معــه علــى اصالحهــا وقلــت لــه راجعنــي بعــد ثــاث أيــام ثــم‬\n      ‫أنصــرف وكانــت الورشــة مزدحمــة لــدي بالســيارات وأوقفــت الســيارة‬\n      ‫باخلــارج بعــد ربــع ســاعه يف برحــه أمــام الورشــة وأغلقــت أبوابهــا حوالــي‬\n      ‫الســاعة العاشــرة صباحــا ثــم عملــت بالورشــة حتــى الظهــر ورجعــت يف‬\n\n‫‪221‬‬\n\f‫املســاء حتــى الســاعة احلــادي عشــر ليــا ولكننــي لــم أتابــع وانظــر يف‬\n‫البرحــة هــل الســيارة مفقــودة أم ال وعندمــا حظــر صاحبهــا نظــرت إلــى‬\n‫البرحــة ولــم أجــد تلــك الســيارة وقــال هــذا دفعــي وعليــه أوقــع وبعــرض‬\n‫ذلــك علــى املدعــي أجــاب أننــي ســلمت الســيارة وأدخلتهــا إلــى الورشــة‬\n‫بنفســي وهــو الــذي أخرجهــا مــن احلــرز ثــم ســالت املدعــي متــى اشــتريت‬\n‫الســيارة قــال أننــي شــريتها قبــل ثالثــة اشــهر مــن معــرض ‪ ...‬ثــم طلبــت‬\n‫منــه اســتمارة الســيارة وســند البيــع وأســتعد بإحضارهــا يف اجللســة‬\n‫القادمــة ‪ ،‬ويف يــوم األحــد املوافــق‪ 1434/01/04‬ه ـ افتتحــت اجللســة‬\n‫الســاعة ‪ 8.30‬وفيهــا حضــر املدعــي وحضــر حلضــوره املدعــى عليــه ثــم‬\n‫أبــرز لنــا أصــل اســتمارة الســيارة ومكتــوب فيهــا املالــك ورقــم هويتــه‬\n‫ورقــم اللوحــة نــوع الســيارة ‪ ...‬وزن املركبــة ‪ ...‬اللــون ‪ ...‬نقــل خــاص‬\n‫ســنة الصنــع ‪ ...‬كذلــك أبــرز ســند الشــراء مــن معــرض ‪ ...‬والــذي جــاء‬\n‫فيــه قولــة اســتلمت مــن الســيد‪ ...‬مبلــغ وقــدرة ‪ 130.000‬الــف ريــال قيمــة‬\n‫‪ ...‬موديــل ‪ ...‬وذلــك بتاريــخ ‪1433/2/8‬ه ـ وبالرجــوع إلــى ملــف القضيــة‬\n‫وجــدت أن املدعــي تقــدم إلــى مركز شــرطة البلد بتاريــخ ‪1433/8/4‬هـ‬\n‫مبلغ ـ ًا عــن تعــرض ســيارته للســرقة حيــث كانــت يف إحــدى الــورش‬\n‫ويتهــم العامــل بســرقتها وجــرى التحقيــق معــه املدعــى عليــه ولــم يتوصــل‬\n‫التحقيــق إلــى نتائــج إلــى أن العامــل ذكــر بــأن مفتــاح الســيارة معــه وال‬\n‫يعلــم كيــف ســرقت ومت حتريــز املفتــاح بقســم الشــرطة ومت مخاطبــة‬\n‫صاحــب املعــرض مــن قبــل الشــرطة وذكــر أن الســيارة ال يوجــد عليهــا‬\n‫اقســاط بــل هــي بطاقــة جمركيــة ومت التعميــم عن تلك الســيارة مبوجب‬\n‫خطــاب مديــر شــرطة البلــد برقــم ‪ 3845‬يف ‪1433/8/5‬ه ـ وكتــب مدير‬\n‫شــرطة البلــد خطاب ـ ًا كذلــك إلــى قســم التحريــات والبحــث اجلنائــي‬\n\n\n                                                                                    ‫‪222‬‬\n\f      ‫برقــم ‪ 4150‬يف ‪1433/8/25‬ه ـ بالتنســيق مــع أصحــاب محالت املفاتيح‬\n      ‫وســؤالهم ملــن عملــوا مفاتيــح مشــابهه ملفاتيــح تلــك الســيارة حيــث أن‬\n      ‫الســيارة املســروقة حديثــة املوديــل ويســتبعد ســرقتها بالطــرق البدائيــة‬\n      ‫ثــم اقتضــت مصلحــه الدعــوى الكتابــة ملعــارض الســيارات لتقديــر ثمــن‬\n      ‫تلــك الســيارة ويف يــوم الســبت املوافــق‪ 1434/02/16‬ه ـ افتتحــت اجللســة‬\n      ‫الســاعة ‪ 08 : 30‬وفيهــا حضــر املدعــي وحضــر حلضــوره املدعــى عليــه‬\n      ‫ثــم وردنــا خطــاب مديــر الشــرطة رقم ‪275‬يف ‪1434/1/24‬ه ـ واملرفق به‬\n      ‫تقديــر قيمــة الســيارة مــن قبــل رئيــس معــارض الســيارات والــذي قدرهــا‬\n      ‫مببلــغ وقــدره مائــة وعشــرون الــف ريــال وبنــاء علــى دعــوى املدعــي الــذي‬\n      ‫ذكــر فيهــا بانــه ســلم الســيارة للمدعــى عليــه وادخلهــا الورشــة يف‬\n      ‫الســاعة احلاديــة عشــر ظهــرا ثــم اخرجهــا املدعــى عليــه واقفهــا بالبرحــة‬\n      ‫الن الورشــة مملــوءة بالســيارات ولــم يتابــع وضعهــا ولــم يدخلهــا يف املســاء‬\n      ‫يف الورشــة وعندمــا حضــر صاحبهــا يف اليــوم التالــي ســال املدعــى عليــه‬\n      ‫عنهــا وقــال وضعتهــا يف البرحــة ولــم يجدهــا بالبرحــة وفقــدت الســيارة‬\n      ‫ومت التعميــم عنهــا ولكــن لــم يعثــر عليهــا وقــد قــدرت مــن قبــل رئيــس‬\n      ‫املعــارض مببلــغ وقــدره مائــة وعشــرون الــف ريــال واملدعــى عليــه مفــرط‬\n      ‫بإخراجهــا للبرحــة ولــم يســأل عنهــا اال بعــد عــن حضــر صاحبهــا يف‬\n      ‫اليــوم التالــي لــذا حكمــت علــى املدعــى عليــه ‪ ...‬بــان يدفــع للمدعــي‬\n      ‫ثمــن تلــك الســيارة وقــدره مائــة وعشــرون الــف ريــال وبعــرض احلكــم‬\n      ‫علــى املدعــي قــال اننــي قانــع باحلكــم امــا املدعــى عليــه قــال اننــي غيــر‬\n      ‫قانــع واعطــي صــورة مــن احلكــم وافهــم علــى لســان املترجــم بــان مــدة‬\n      ‫االعتــراض ثالثــون يومــا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                          ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/02/16‬ه ـ‬\n\n\n‫‪223‬‬\n\f‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n‫أنــا القاضــي يف احملكمــة العامــة بينبــع وبنــاء علــى املعاملــة احملالــة لنــا‬\n‫مــن فضيلــة رئيــس احملكمــة العامــة بينبــع املســاعد برقــم ‪33626232‬‬\n‫وتاريــخ ‪ 1433/10/28‬ه ـ املقيــدة باحملكمــة برقــم ‪331706916‬‬\n‫وتاريــخ ‪ 1433/09/16‬ه ـ ففــي يــوم اخلميــس املوافــق‪ 1434/11/06‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪10.00‬وفيهــا حضــر املدعــي وحضــر حلضــوره‬\n‫املدعــى عليــه ثــم أعيــدت لنــا املعاملــة مبوجــب خطــاب فضيلــة رئيــس‬\n‫محكمــة االســتئناف ملنطقــة مكــة املكرمــة رقــم ‪331913856‬‬\n‫يف ‪1434/06/05‬ه ـ واملرفــق بــه قــرار املالحظــة رقــم ‪ 34226318‬يف‬\n‫‪1434/05/28‬ه ـ والــذي جــاء فيــه قوله وبدراســة الصــك وصورة ضبطه‬\n‫تقــرر إعادتهــا لفضيلــة حاكمهــا ملالحظــة مــا يلــي ‪ -1 :‬لالطــاع علــى‬\n‫الالئحــة االعتراضيــة املرفقــة والشــرح عليهــا مبــا يظهــر لــه ومعــاودة‬\n‫متابعــة البحــث والتحــري عــن الســيارة محــل الدعــوى والتعقيــب علــى‬\n‫البالغات التي اتخذتها اجلهات املختصة وماذا مت بصددها ‪ -2‬الدعوى‬\n‫غيــر محــررة وال بــد مــن حتريرهــا قبــل عرضهــا علــى املدعــى عليــه ‪-3‬‬\n‫لــم يعمــل املــادة ‪ 1/181‬مــن نظــام املرافعــات الشــرعية ولوائــح التنفيذيــة‬\n‫واهلل املوفــق قاضــي اســتئناف قاضــي اســتئناف رئيــس الدائــرة وبعــرض‬\n‫ا أدعــي علــى احلاضــر معــي باملجلــس‬           ‫ذلــك علــى املدعــي أجــاب قائ ـ ً‬\n‫الشــرعي الــذي ســبق وان ســلمته ســيارتي ‪ ...‬صنــع … ورقمهــا (‪)....‬‬\n‫وذلــك بتاريــخ ‪1433/8/4‬ه ـ علــى أســاس ان يصلــح فيهــا أشــياء بســيطة‬\n‫وادخلتهــا ورشــته ثــم ســلمته املفتــاح واتفقنــا علــى ســعر اإلصــاح وقــال‬\n‫لــي تعــال بعــد ثالثــة أيــام وجتدهــا جاهــزة ولكننــي اســتعجلت وحضرت‬\n‫إلــى الورشــة يف اليــوم الثانــي ولــم اجــد ســيارتي وســألته عنهــا وقــال إننــي‬\n\n\n                                                                                        ‫‪224‬‬\n\f      ‫حركتهــا ووضعتهــا يف البرحــة لــذا أطلــب أن يدفــع لــي ثمــن ســيارتي ‪...‬‬\n      ‫وقــدرة مائــة وثالثــون ألــف ريــال وبعــرض الدعــوى املرصــودة بعاليــة علــى‬\n      ‫ا نعــم اســتلمت ســيارة املدعــي املوصوفــة بعاليــة‬    ‫املدعــى عليــه اجــاب قائـ ً‬\n      ‫بعــد ان ادخلهــا إلــى ورشــتي واســتلمت مفتاحهــا وبعــد عشــرين دقيقــة‬\n      ‫تقريب ـ ًا وضعتهــا أمــام الورشــة مــع مجموعــه مــن الســيارات يف البرحــة‬\n      ‫ولــم أنتبــه أنهــا غيــر موجــودة إال بعــد حضــور صاحبهــا يف اليــوم الثانــي‬\n      ‫نظــرت إليهــا ولــم اجدهــا وســلمت املفتــاح إلى الشــرطة ثم ســألت املدعي‬\n      ‫هــل وجــدت الســيارة او وجــدت عنهــا خبــر مــن قريــب أو مــن بعيــد فقــال‬\n      ‫لــم اجــد عنهــا خبــر ولــم أشــاهدها وطيلــة املــدة وانــا أســأل عنهــا فقــال‬\n      ‫واهلل العظيــم إنــي ال أعلــم عنهــا وانهــا مصيبــة وقعــت علــي وليســت حيلــة‬\n      ‫وال خديعــة وإنــي ال أعلــم عــن تلــك الســيارة شــيء ثــم جــرى مخاطبــة‬\n      ‫الشــرطة مبوجــب خطابنــا رقــم ‪ 341458073‬يف ‪1434/6/17‬ه ـ‬\n      ‫بالبحــث عــن تلــك الســيارة وهــل وجــدوا بالغ ـ ًا عنهــا أم مــاذا فأفادونــا‬\n      ‫مبوجــب خطابهــم رقــم ‪ 22/3285/13/3‬يف ‪1434/8/17‬ه ـ بأنــه مت‬\n      ‫التعميــم عــن تلــك الســيارة برقــم ‪ 3845‬يف ‪1433/8/15‬ه ـ ولــم يتــم‬\n      ‫العثــور علــى الســيارة املذكــورة حتــى تاريخــه حتــت توقيــع مديــر شــرطة‬\n      ‫البلــد املقــدم ثــم جــرى منــي االطــاع علــى الالئحــة حســب املــادة ‪181‬‬\n      ‫مــن نظــام املرافعــات ولــم اجــد فيهــا شــيئ ًا لــذا لــم يطــرا لــدي مــا يوجــب‬\n      ‫تغييــر حكمــي الســابق وقــال املدعــي إننــي قانــع باحلكــم وقــال املدعــى‬\n      ‫عليــه إننــي غيــر قانــع والئحتــي مرفقــه يف املعاملــة لــذا جــرى إحلــاق ذلــك‬\n      ‫بالصــك وبعثــة إلــى محكمــة االســتئناف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/11/06‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n\n\n‫‪225‬‬\n\f‫أنــا القاضــي يف احملكمــة العامــة بينبــع والقائــم بعمــل فضيلــة الشــيخ‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بينبــع املســاعد برقــم ‪ 33626232‬وتاريــخ ‪ 1433/10/28‬ه ـ املقيــدة‬\n‫باحملكمة برقم ‪ 331706916‬وتاريخ ‪ 1433/09/16‬هـ ففي يوم األحد‬\n‫املوافــق‪ 1434/12/29‬ه ـ افتتحــت اجللســة الســاعة وفيها وردتنــا املعاملة‬\n‫مــن محكمــة االســتئناف برقــم ‪ 331913856‬يف ‪1434/12/17‬ه ـ‬\n‫والصــادر فيــه القــرار رقــم ‪ 34373689‬يف ‪1434/11/27‬ه ـ وفيــه نحــن‬\n‫قضــاة االســتئناف بالدائــرة احلقوقيــة اخلامســة يف محكمــة االســتئناف‬\n‫مبنطقــة مكــة املكرمــة جــرى منــا نحــن االطــاع علــى هــذا احلكــم‬\n‫الصــادر مــن فضيلــة الشــيخ القاضــي باحملكمــة العامــة بينبــع املســجل‬\n‫بعــدد ‪ 3437753‬وتاريــخ ‪1434/12/16‬ه ـ املتضمــن دعــوى ‪ ،‬احملكــوم‬\n‫فيــه مبــا دون باطــن الصــك وبدراســة احلكــم وصــورة ضبطــه والئحتــه‬\n‫االعتراضيــة تقــرر املوافقــة علــى احلكــم بعــد اإلجــراء األخيــر ‪ ،‬قاضــي‬\n‫اســتئناف قاضــي اســتئناف رئيــس الدائــرة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/1/1‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                  ‫‪226‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":220,"source_page_end":226,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"12f44643b8f68edb1bca3ed75b6d9acdfccf2b1c71014cb12f8d02d8f5313bcf","normalized_text_hash":"54c4ce99fabd301e19d175b5c9ee74552c6f77348b4ae03afa8e9208c31c6b30","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p220-3437753"},{"id":"a2895d1c-7f7c-583f-b02a-f68e9083e384","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبة برد مسروق -سرقة مبلغ مالي من سيارة -عجز عن إقامة البينة -احلكم برد الدعوى -استحقاق املدعي ليمن املدعى عليه على نفي الدعوى متى طلبها .","document_number":"33475191","case_number":"33666747","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/21","year":"1434","subject":"مطالبة برد مسروق -سرقة مبلغ مالي من سيارة -عجز عن إقامة البينة -احلكم برد الدعوى -استحقاق املدعي ليمن املدعى عليه على نفي الدعوى متى طلبها .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1433/11/21 :‬هـ‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪33475191 :‬‬\n                           ‫َر ْق ُم الدعوى‪33666747:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                    ‫‪ 3428329‬تاريخه‪1434/2/3:‬هـ‬\n\n\n       ‫مطالبــة بــرد مســروق ‪ -‬ســرقة مبلــغ مالــي مــن ســيارة ‪ -‬عجــز عــن إقامــة‬\n       ‫البينــة ‪ -‬احلكــم بــرد الدعــوى ‪ -‬اســتحقاق املدعــي ليمــن املدعــى عليــه‬\n                                               ‫علــى نفــي الدعــوى متــى طلبهــا ‪.‬‬\n\n\n\n\n       ‫قــول النبــي صلــى اهلل عليــه وســلم‪( :‬البينــة علــى املدعــي واليمــن علــى‬\n                                                                        ‫مــن أنكــر) ‪.‬‬\n\n\n\n\n       ‫ادعــى املدعــي علــى احلاضــر معــه بأنــه قــام بكســر زجــاج ســيارته‬\n       ‫وســرقة مبلــغ مالــي منهــا‪ ،‬وطلــب تأديبــه وإلزامــه بإعــادة املبلــغ املســروق‬\n       ‫إليــه ‪ -‬أنكــر املدعــى عليــه مــا جــاء يف دعــوى املدعــي ‪ -‬املدعــي لــم‬\n       ‫يقــدم بينــة تثبــت دعــواه ولــم يقبــل ميــن املدعــى عليــه علــى نفيهــا ‪ -‬قضت‬\n       ‫احملكمــة بصــرف النظــر عــن الدعــوى وأخلــت ســبيل املدعــى عليــه منها‬\n       ‫وأفهمــت املدعــي أن لــه ميــن املدعــى عليــه علــى نفــي دعــواه متــى مــا طلــب‬\n       ‫ذلــك ‪ -‬قنــع املدعــى عليــه باحلكــم وعــارض املدعــي‪ -‬قــررت محكمــة‬\n                                                  ‫االســتئناف املصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫‪227‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بحائــل وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بحائــل‪ /‬املكلــف برقــم ‪ 33666747‬وتاريــخ ‪ 1433/11/21‬ه ـ‬         ‫ّ‬\n‫املقيــدة باحملكمــة برقــم‪ 332048342‬وتاريــخ ‪1433/11/17‬ه ـ ففــي‬\n‫يــوم الثالثــاء املوافق‪1433/12/21‬ه ـ افتتحــت اجللســة الســاعة الثانيــة‬\n‫عشــرة وفيهــا حضــر ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬‬\n‫وادعــى علــى احلاضــر معــه ســعودي بالســجل املدنــي رقــم ‪ ...‬واملضــاف يف‬\n‫ســجل أســرة والــده واملرفــق باملعاملــة واملعــرف بــه مــن قبــل املدعــي ومــن‬\n‫أخيــه احلاضــر معــه ســعودي بالســجل املدنــي رقــم ‪ ...‬قائــا يف حتريــر‬\n‫دعــواه إن املدعــى عليــه قــد قــام بتاريــخ ‪1433/6/4‬ه ـ بكســر زجاجــة‬\n‫ســيارتي وهــي مــن نــوع ‪...‬موديــل ‪ .....‬وســرق منهــا مبلغ ـ ًا قــدره خمســة‬\n‫آالف ريــال أطلــب تأديبــه وإلزامــه بدفــع املبلــغ املســروق وقــدره خمســة‬\n‫آالف ريــال هــذه دعــواي هكــذا ادعــى املدعــي وبعــرض ذلــك علــى‬\n‫ا مــا ذكــره املدعــي ضــدي كلــه غيــر صحيــح‬       ‫املدعــى عليــه أجــاب قائـ ً‬\n‫وال أعلــم عــن هــذه الواقعــة شــيئا وليــس لــي أي عالقــة بكســر ســيارة‬\n‫املدعــي أو الســرقة منهــا وبعــرض ذلــك علــى املدعــي قــال الصحيــح مــا‬\n‫ذكرتــه يف دعــواي وبســؤاله عــن البينــة قــال ليــس عنــدي بينــة وجــرى‬\n‫ســؤاله هــل شــاهدت املدعــى عليــه وهــو يســرق فقــال ال فجــرى ســؤال‬\n‫املدعــي إن كان يرغــب ميــن املدعــى عليــه علــى نفــي دعــواه فقــال ال‬\n‫أقبــل ميينــه ثــم قــال املدعــى عليــه ال مانــع عنــدي مــن أداء اليمــن فجــرى‬\n‫منــي االطــاع علــى املعاملــة وبهــا خطــاب ســعادة مديــر دار املالحظــة‬\n\n                                                                                      ‫‪228‬‬\n\f      ‫االجتماعيــة بحائــل واملرفــق باملعاملــة واملتضمــن أنــه مت التحقيــق‬\n      ‫مــع املذكــور وأنكــر قيامــه بالســرقة كمــا مت مضاهــاة بصماتــه‬\n      ‫للقضايــا املقيــدة ضــد مجهــول ووردنــا كتــاب مديــر األدلــة اجلنائيــة رقــم‬\n      ‫‪ 5605/8/1/29‬يف ‪1433/10/28‬ه ـ واملتضمــن عــدم االســتدالل علــى‬\n      ‫أي بصمــات تنطبــق علــى بصمــات املذكــور وهــذا مرفــق علــى اللفــة‬\n      ‫رقــم (‪ )25‬باملعاملــة وبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ولعــدم‬\n      ‫مصادقــة املدعــى عليــه علــى الدعــوى وال بينــة للمدعــي ورفــض املدعــي‬\n      ‫طلــب ميــن املدعــى عليــه ولعمــوم قــول النبــي صلى اهلل عليه وســلم‪ :‬البينة‬\n      ‫علــى املدعــي واليمــن علــى مــن أنكــر فقــد حكمــت بصــرف النظــر‬\n      ‫عــن طلــب املدعــي تأديــب املدعــى عليــه وإلزامــه بدفــع املبلــغ املســروق‬\n      ‫وأخليــت ســبيل املدعــى عليــه وأفهمــت املدعــي أن لــه ميــن املدعــى عليــه‬\n      ‫علــى نفــي دعــواه متــى مــا طلــب ذلــك هــذا مــا ظهــر لــي وبــه حكمــت‬\n      ‫واهلل أعلــم وأحكــم وبعــرض احلكــم علــى الطرفــن لــم يقنــع املدعــي‬\n      ‫وطلــب رفعــه حملكمــة االســتئناف بــدون الئحــة اعتراضيــة وبعــرض‬\n      ‫احلكــم علــى املدعــى عليــه قنــع بــه وبــاهلل التوفيــق وبهــذا أقفلــت اجللســة‬\n      ‫يف متــام الســاعة الثانيــة عشــرة والنصــف وصلــى اهلل علــى نبينــا محمــد‬\n                              ‫وعلــى آلــه وصحبــه وســلم حــرر يف ‪1433/12/21‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة‬\n      ‫األولــى لتدقيــق القضايــا احلقوقيــة مبحكمــة االســتئناف مبنطقــة‬\n      ‫حائــل علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة‬\n      ‫بحائــل املكلــف برقــم ‪ 332048342‬وتاريخ‪1434/1/27‬ه ـ واملقيــدة‬\n      ‫لدينــا برقــم ‪ 34250118‬يف ‪1434/1/28‬ه ـ املرفــق بهــا الصــك رقــم‬\n      ‫‪ 33475191‬يف ‪1433/12/21‬ه ـ الصــادر مــن فضيلــة القاضــي ‪......‬‬\n\n\n‫‪229‬‬\n\f‫اخلــاص بدعــوى ‪ .......‬ضــد ‪ .......‬بشــأن اتهــام بســرقة (حــق خــاص)‬\n‫علــى الصفــة املوضحــة يف الصــك وقــد تضمــن الصــك حكــم فضيلتــه‬\n‫بصــرف النظــر عــن طلــب املدعــي تأديــب املدعــى عليــه وإلزامــه بدفــع‬\n‫املبلــغ املســروق وإخــاء ســبيل املدعــى عليــه مــن هــذه الدعــوى وأفهمــت‬\n‫املدعــي أن لــه ميــن املدعــى عليــه علــى نفــي دعــواه متــى مــا طلــب ذلــك‬\n‫وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة لــم يظهــر مــا يوجــب‬\n‫املالحظــة علــى مــا حكــم بــه فضيلتــه واهلل املوفــق وصلــى اهلل علــى‬\n                                   ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                    ‫‪230‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":227,"source_page_end":230,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"992db6f5386945301a1ef9768c27b477bd4e8ef3d37362b798d91364afe1f46e","normalized_text_hash":"4c01e70245f0f87eb20e06dff6999ce2a8c802dd42788c46e365f2f984daa83c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p227-33475191"},{"id":"ae07f93c-4591-5bc7-a83b-bbdefd1a7e1f","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مسروق -سرقة مواد إنشائية من مستودع -القبض على املتهم حال السرقة بدون مسروقات -بينة غير موصلة -اليمن على نفي الدعوى حق للمدعي وله عدم قبولها -احلكم برد دعوى .","document_number":"3420688","case_number":"33680256","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/24","year":"1434","subject":"رد مسروق -سرقة مواد إنشائية من مستودع -القبض على املتهم حال السرقة بدون مسروقات -بينة غير موصلة -اليمن على نفي الدعوى حق للمدعي وله عدم قبولها -احلكم برد دعوى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/1/24 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪3420688 :‬‬\n                         ‫َر ْق ُم الدعوى‪33680256:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 3450740‬تاريخه‪1434/2/3:‬هـ‬\n\n\n      ‫رد مســروق ‪ -‬ســرقة مــواد إنشــائية مــن مســتودع ‪ -‬القبــض علــى املتهــم‬\n      ‫حــال الســرقة بــدون مســروقات ‪ -‬بينــة غيــر موصلــة ‪ -‬اليمــن علــى نفــي‬\n                ‫الدعــوى حــق للمدعــي ولــه عــدم قبولهــا ‪ -‬احلكــم بــرد دعــوى ‪.‬‬\n\n\n\n\n      ‫قــول النبــي صلــى اهلل عليــه وســلم‪( :‬البينــة علــى املدعــي واليمــن علــى‬\n                                                                    ‫املدعــى عليــه) ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي بــأن املدعــى عليــه قــام بســرقة مــواد إنشــائية مــن مســتودع‬\n      ‫عائــد لــه؛ وطلــب إلزامــه بــرد املســروقات أو تســليمه قيمتهــا‪ -‬أنكــر‬\n      ‫املدعــى عليــه دعــوى املدعــي جتاهــه جملــة وتفصيــا‪ -‬املدعــي قــدم‬\n      ‫بينــات غيــر موصلــة ولــم يقبــل ميــن املدعــى عليــه علــى نفــي دعــواه‪ -‬مــن‬\n      ‫املقــرر شــرعا أن البينــة علــى املدعــي واليمــن علــى املدعــى عليــه‪ -‬قضت‬\n      ‫احملكمــة بعــدم اســتحقاق املدعــي ملــا يدعيــه وأخلــت ســبيل املدعــى‬\n      ‫عليــه منهــا وأفهمــت املدعــي بــأن لــه ميــن املدعــى عليــه متــى طلبهــا‪-‬‬\n      ‫قنــع املدعــى عليــه باحلكــم وعــارض عليــه املدعــي ‪ -‬قــررت محكمــة‬\n                                              ‫االســتئناف املوافقــة علــى احلكــم ‪.‬‬\n\n\n‫‪231‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامة مبكة‬\n‫املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة مبكــة املكرمــة برقــم ‪ 33680256‬وتاريــخ ‪1433/11/28‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 332014010‬وتاريــخ ‪ 1433/11/14‬ه ـ‬\n‫حضــر بالســجل املدنــي رقــم ‪ ...‬وادعــى علــى احلاضــر معــه الســجني‬\n‫بالســجل املدنــي رقــم ‪ ...‬يرافقــه اجلنــدي قائــا يف دعــواه عليــه لقــد قفــز‬\n‫املدعــى عليــه علــى مســتودعي الواقــع بــ‪ ........‬وســرق منــه مــا يلــي أوال‬\n‫مائــة وخمســة وثمانــن طفايــة حريــق مســتعمله وقيمتهــا اإلجمالية ســبعة‬\n‫وعشــرون ألفــا وســبعمائة وخمســون ريــال ثانيــا مائتــان وتســعون طفايــة‬\n‫حريــق جديــد وقيمتهــا اإلجماليــة ســبعة وثمانــون ألــف ريــال ثالثــا اثنــا‬\n‫عشــر مولــد كهربائــي مببلــغ إجمالــي ســبعة وعشــرين ألفــا وســتمائة‬\n‫ريــال رابعــا ثالثــون لفــة كيابــل كبيــره مببلــغ إجمالــي ســتة وثالثــن‬\n‫ألــف ريــال خامســا خمســة عشــر لفــة كيابــل صغيــر مببلــغ إجمالــي‬\n‫تســعة آالف ريــال سادســا مائتــان وعشــرة ملبــة فلورســنت مــع قواعدهــا‬\n‫مببلــغ إجمالــي خمســة آالف ومائتــان وخمســون ريــاال ســابعا ســبعة‬\n‫وأربعــون شــوال مــن أكيــاس النفايــات الكبيــرة مببلــغ ثالثــة آالف‬\n‫وتســعمائة وخمســة وتســعني ريــاال ومجمــوع ذلــك مبلــغ وقــدره مائــة‬\n‫وســتة وتســعون ألــف ريــال فأطلــب إلزامــه بــرد مــا ســرقه أو دفــع قيمتــه‬\n‫هــذه دعــواي وبســؤال املدعــى عليــه عــن دعــوى املدعــي أجــاب قائــا ال‬\n‫صحــة ملــا ذكــره فلــم أدخــل مســتودعه الواقــع بالشــرائع ولــم أســرق منــه‬\n‫شــيئا هــذه إجابتــي وبســؤال املدعــي هــل لديــه بينــة علــى دعــواه فقــال‬\n\n                                                                                     ‫‪232‬‬\n\f      ‫نعــم لــدي البينــة وأحضــر للشــهادة وأدائهــا بالســجل املدنــي رقــم وطلــب‬\n      ‫ســماع مــا لديــه مــن شــهادة وشــهد قائــا أشــهد إننــي رأيــت املدعــى عليــه‬\n      ‫هــذا احلاضــر ومعــه شــخص آخــر فــوق ســور مســتودع املدعــي املجــاور‬\n      ‫ملنزلنــا وقــد أبلغــت الشــرطة عنــه وملــا حضــرت الدوريــة قمــت مبســاعدة‬\n      ‫الدوريــة والقبــض عليــه عندمــا قفــز مــن فــوق الســور إلــى األرض وأمــا‬\n      ‫صاحبــه اآلخــر فقــد هــرب وقــد رأيــت أســفل الســور لفتــن مــن لفائــف‬\n      ‫أســاك الكهربــاء وال أعلــم مــن أخرجهــا ولــم يكــن بيــد املدعــى عليــه‬\n      ‫شــيء عنــد القبــض عليــه هــذا مــا لــدي وأشــهد بــه وبعــرض الشــاهد‬\n      ‫وشــهادته علــى املدعــى عليــه قــال الشــاهد ال أعرفــه وال أقــول بــه شــيئا‬\n      ‫وشــهادته بأنــه قبــض علــي صحيحــة ولكــن شــهادته أننــي كنــت فــوق‬\n      ‫الســور غيــر صحيحــة فأنــا لــم أكــن فــوق الســور أبــدا وإمنــا كنــت‬\n      ‫أســفل الســور وزميلــي الــذي كان معــي هــو الــذي دخــل املســتودع حيــث‬\n      ‫قفــز فــوق الســور لســرقة مــا بداخلــه وكنــت أنــا يف اخلــارج ولــم أشــاهده‬\n      ‫يخــرج شــيئا وقــد شــاهده الشــاهد وهــو فــوق الســور وملــا أراد القبــض‬\n      ‫علينــا هــرب وأنــا كنــت أســفل الســور وقبــض الشــاهد علــي هكــذا‬\n      ‫قــرر وبســؤال املدعــي هــل لديــه زيــادة بينــة فقــال ال وعليــه فقــد أفهمتــه‬\n      ‫بــأن لــه ميــن املدعــى عليــه علــى نفــي دعــواه فقــال إننــي ال أريــد ميينــه وال‬\n      ‫أقبلهــا هكــذا قــرر ثــم جــرى الرجــوع إلــى أوراق املعاملــة فلــم أجــد فيهــا‬\n      ‫إقــرارا للمدعــى عليــه بالســرقة أه ـ فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n      ‫واإلجابــة وألن املدعــى عليــه أنكــر ســرقة مــا يدعيــه املدعــي ولعمــوم‬\n      ‫قولــه صلــى اهلل عليــه وســلم البينــة علــى املدعــي واليمــن علــى من أنكر‬\n      ‫وألن البينــة التــي أحضرهــا املدعــي ليســت موصلــة حيــث شــهد الشــاهد‬\n      ‫أنــه رأى املدعــى عليــه فــوق الســور ثــم قفــز أســفله ومت القبــض عليــه ولــم‬\n\n\n‫‪233‬‬\n\f‫يكــن معــي شــيء وألن املدعــي قــرر أنــه ال يقبــل بيمــن املدعــى عليــه‬\n‫علــى نفــي دعــواه لذلــك كلــه فقــد حكمــت بعــدم اســتحقاق املدعــى‬\n‫عليــه ملــا يدعيــه وأخليــت ســبيل املدعــى عليــه مــن هــذه الدعــوى وأفهمتــه‬\n‫بــأن لــه ميــن املدعــى عليــه علــى نفــي دعــواه متــى طلبهــا وبعــرض احلكــم‬\n‫علــى الطرفــن قــرر املدعــى عليــه القناعــة وقــرر املدعــي عــدم القناعــة‬\n‫وطلــب رفعــه حملكمــة االســتئناف بعــد تقــدمي الئحــة اعتراضيــة عليــه‬\n‫فأفهمتــه مبراجعــة احملكمــة خــال عشــرة أيــام الســتالم الصــك وتقدمي‬\n‫الالئحــة االعتراضيــة خــال ثالثــن يومــا مــدة االعتــراض فــإذا تأخــر‬\n‫ســقط حقــه يف طلــب االســتئناف واكتســب احلكــم القطعيــة وبــاهلل‬\n‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر‬\n                                                          ‫يف ‪1434/1/21‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ثــم عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫بشــرح فضيلــة الرئيــس برقــم ‪ 34489001‬يف ‪1434/4/23‬ه ـ علــى‬\n‫خطــاب رئيــس محكمــة االســتئناف مبنطقــة مكــة املكرمــة املكلــف‬\n‫برقــم ‪ 34489001‬يف ‪1434/3/18‬ه ـ برفقهــا قــرار التصديــق مبوجــب‬\n‫القــرار رقــم ‪ 3450740‬يف ‪1434/2/3‬ه وهــذا نصــه ‪ -:‬احلمــد هلل ‪،‬‬\n‫والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ -:‬فقــد جــرى منــا نحــن‬\n‫قضــاة الدائــرة اجلزائيــة الثالثــة مبحكمــة االســتئناف مبنطقــة مكــة‬\n‫املكرمــة االطــاع علــى املعاملــة الــواردة الينــا شــفع خطــاب فضيلــة‬\n‫رئيــس احملكمــة العامــة مبكــة املكرمــة رقــم ‪ 332014010‬وتاريــخ‬\n‫‪1434/2/24‬ه ـ املشــتملة علــى الصــك الصــادر مــن فضيلــة الشــيخ‬\n‫القاضــي باحملكمــة العامــة مبكــة املكرمــة املــؤرخ يف ‪1434/1/24‬هـ‬\n‫واملســجل بعــدد ‪ 3420688‬املتضمــن دعــوى ضــد الســجني املتهم بســرقة‬\n\n\n                                                                                     ‫‪234‬‬\n\f      ‫كيابــل احملكــوم فيــه مبــا دون باطــن القرار ‪ ،‬وبدراســة الصك وصورة‬\n      ‫ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة علــى احلكــم ‪ .‬وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪،‬‬\n      ‫قاضــي اســتئناف ختــم وتوقيــع د‪ /‬قاضــي اســتئناف ختــم وتوقيــع رئيــس‬\n      ‫الدائــرة ختــم وتوقيــع ‪ ،‬لــذا جــرى مبوجبــه ‪.‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/5/5‬ه ـ ‪.‬‬\n\n\n\n\n‫‪235‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":231,"source_page_end":235,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b50ee4ca6b1035afee0fd1efd531d5a27ccad9e0d58cdf24c9825bada7c269b0","normalized_text_hash":"a9ad90dce9f6ffefa538086b940115b3ff66b6d6030bf5034041bee38e722cb0","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p231-3420688"},{"id":"a52cd1bb-9e95-50a3-af07-2abfe484c56c","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مسروق -سرقة سيارة وإتالفها -طلب املدعي اليمن النافية من قبل املدعى عليه -القضاء بالنكول عن اليمن -إلزام املدعى عليه بقيمة السيارة .","document_number":"3423451","case_number":"33688344","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املوافقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/26","year":"1434","subject":"رد مسروق -سرقة سيارة وإتالفها -طلب املدعي اليمن النافية من قبل املدعى عليه -القضاء بالنكول عن اليمن -إلزام املدعى عليه بقيمة السيارة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/1/26 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3423451 :‬‬\n                   ‫َر ْق ُم الدعوى‪33688344 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n             ‫‪ 3451302‬تاريخه‪1434/3/1:‬هـ‬\n\n\n‫رد مســروق ‪ -‬ســرقة ســيارة وإتالفهــا ‪ -‬طلــب املدعــي اليمــن النافيــة مــن‬\n‫قبــل املدعــى عليــه ‪ -‬القضــاء بالنكــول عــن اليمــن ‪ -‬إلــزام املدعــى عليــه‬\n                                                             ‫بقيمــة الســيارة ‪.‬‬\n\n\n\n\n                                       ‫اليمني تشرع يف جانب أقوى املتداعيني ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي علــى احلاضــر معــه بأنــه قــام بســرقة ســيارته ثــم عثــر عليها‬\n‫محترقــة بشــكل كامــل بعــد أخــذ بعــض أجزائهــا ‪ ،‬وطلــب إلزامــه‬\n‫بإعــادة قيمــة تلــك الســيارة إليــه ‪ -‬أنكــر املدعــى عليــه مــا جــاء يف دعــوى‬\n‫املدعــي‪ -‬املدعــي لــم يقــدم بينــة موصلــة وطلــب ميــن املدعــى عليــه علــى‬\n‫نفــي دعــواه فنــكل عــن أدائهــا بعــد إنــذاره ‪ -‬أدى املدعــي اليمــن طبــق‬\n‫مــا طلــب منــه‪ -‬قضــت احملكمــة علــى املدعــى عليــه بإلزامــه بتســليم‬\n‫قيمــة الســيارة إلــى املدعــي‪ -‬عــارض املدعــى عليــه علــى احلكــم‪ -‬قــررت‬\n                               ‫محكمــة االســتئناف املوافقــة علــى احلكــم ‪.‬‬\n\n\n\n\n                                                                                       ‫‪236‬‬\n\f      ‫احلمد هلل وحده وبعد فلدي أنا ‪ ...‬القاضي يف احملكمة اجلزائية باملدينة‬\n      ‫املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة باملدينــة املنــورة برقــم ‪ 33688344‬وتاريــخ ‪ 1433/12/18‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 332178767‬وتاريــخ ‪ 1433/12/18‬ه ـ‬\n      ‫واملتعلقــة بدعــوى ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬ضــد‬\n      ‫‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬ففــي يــوم الثالثــاء‬\n      ‫املوافــق‪ 1434/01/20‬ه ـ افتتحــت اجللســة الســاعة ‪ 10 : 45‬وفيهــا‬\n      ‫ا ‪ :‬أدعــي ضــد املدعــى عليــه حيــث‬    ‫حضــر الطرفــان فادعــى املدعــي قائـ ً‬\n      ‫إنــه بتاريــخ ‪1432/7/27‬ه ـ ســرقت ســيارتي مــن نــوع ‪ .......‬غمــارة موديــل‬\n      ‫‪ ......‬رقــم لوحتهــا (‪ )....‬مــن أمــام منزلــي فقمــت بتبليــغ اجلهــات األمنيــة‬\n      ‫بذلــك ‪ ،‬وبعــد البحــث والتحــري وجــدت ســيارتي مــن قبــل الشــرطة يف‬\n      ‫منطقــة جبليــة وهــي محترقــة بالكامــل ومتعرضــة للتشــليح علمـ ًا بأننــي‬\n      ‫اشــتريت الســيارة بتاريــخ ‪1430/2/27‬ه ـ مببلــغ ســبعة عشــر ألــف ريــال‬\n      ‫وتعــذر تقديــر أرش اجلنايــة عليهــا لكونهــا يف منطقــة نائيــة ويصعــب‬\n      ‫إحضارهــا ملعــارض الســيارات وحيــث أديــن املدعــى عليــه يف احلــق العــام‬\n      ‫بســرقة عــدة ســيارات وإحراقهــا ومــن ضمنهــا ســيارتي فأطلــب إلزامــه‬\n      ‫بتســليمي قيمــة ســيارتي التــي أتلفهــا وقدرهــا ســبعة عشــر ألــف ريــال‬\n      ‫حــا ًال هــذه دعــواي‪ ،‬وبســؤال املدعــى عليــه عــن دعــوى املدعــي ضــده‬\n      ‫أجــاب قائ ـاً‪ :‬مــا ذكــره املدعــي ضــدي غيــر صحيــح حيــث لــم أســرق‬\n      ‫ســيارته املذكــورة يف دعــواه ولــم أقــم بتشــليحها وال إحراقهــا وال أعلــم‬\n      ‫مــن قــام بذلــك هكــذا أجــاب ‪ ،‬فســألت املدعــي هــل لديــه بينــة علــى مــا‬\n\n‫‪237‬‬\n\f‫ادعــاه ونفــاه املدعــى عليــه فقــال ‪ :‬ليــس لــدي ســوى مــا يف أوراق املعاملــة‬\n‫هكــذا قــال ‪ ،‬فجــرى منــي دراســة أوراق املعاملــة فوجــدت مــن ضمنهــا‬\n‫بــاغ املدعــي املتضمــن نحــو مــا ورد يف دعــواه ‪ ،‬كمــا وجــدت القــرار‬\n‫الصــادر منــا برقــم ‪ 33156416‬يف ‪1433/3/27‬ه ـ املتضمــن عــدم ثبــوت‬\n‫إدانــة املدعــى عليــه بســرقة عــدد مــن الســيارات ومــن ضمنهــا ســيارة‬\n‫املدعــي ولكــن الشــبهة القويــة تتجــه ضــده بذلــك وحكــم مبجازاتــه‬\n‫لقــاء ذلــك بســجنه عشــر ســنوات وجلــده ألف ـ ًا ومائــة وخمس ـ ًا وعشــرين‬\n‫جلــدة وتغرميــه مبلــغ خمســة عشــر ألــف ريــال وصــدق احلكــم مــن‬\n‫محكمــة االســتئناف بقرارهــا رقــم ‪ 33360258‬يف ‪1433/7/29‬ه ـ ‪،‬‬\n‫وحيــث لــم أجــد يف أوراق املعاملــة مــا يديــن املدعــى عليــه مبــا جــاء يف‬\n‫دعــوى املدعــي ضــده ولكــون احلكــم املذكــور مضمونــه بعاليــة ومــا‬\n‫بنــي عليــه مــن قرائــن يعتبــر قرينــة قويــة تقــوي جانــب املدعــي وملــا قــرره‬\n‫العلمــاء مــن أن اليمــن تكــون يف جانــب أقــوى املتداعيــن فقــد أفهمــت‬\n‫املدعــي بأنــه تتجــه ضــده اليمــن املكملــة لبينتــه فرفــض أداء اليمــن‬\n‫لكونــه لــم يشــاهد املدعــى عليــه وهــو يقــوم بســرقة ســيارته وطلــب ميــن‬\n‫املدعــى عليــه علــى نفــي دعــواه وبعرضــه علــى املدعــى عليــه رفــض أداء‬\n‫اليمــن علــى نفــي دعــوى املدعــي ضــده فجــرى إنــذاره ثــاث مــرات بــأن‬\n‫عــدم أدائــه لليمــن يعــد نكــو ًال فأصــر علــى عــدم أداء اليمــن فأفهمــت‬\n‫املدعــي أنــه تتجــه ضــده اليمــن علــى أن قيمــة ســيارته ســبعة عشــر‬\n‫ألــف ريــال وقــت ســرقتها فاســتعد بــأداء اليمــن ثــم حلــف قائ ـاً‪ :‬واهلل‬\n‫العظيــم إن قيمــة ســيارتي وقــت ســرقتها ســبعة عشــر ألــف ريــال واهلل‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبعد‬\n                                                  ‫العظيــم هكــذا حلــف‪ ،‬فبنـ ً‬\n‫االطــاع علــى أوراق املعاملــة وحيــث أنكــر املدعــى عليــه مــا جــاء يف‬\n\n\n                                                                                        ‫‪238‬‬\n\f      ‫دعــوى املدعــي ضــده وقــرر املدعــي أنــه ال بينــة لــه علــى دعــواه ســوى مــا‬\n      ‫يف أوراق املعاملــة‪ ،‬وحيــث لــم أجــد يف أوراق املعاملــة مــا يديــن املدعــى‬\n      ‫عليــه مبــا جــاء يف دعــوى املدعــي ضــده إال أن القــرار الصــادر منــا يوجــه‬\n      ‫الشــبهة القويــة للمدعــى عليــه بســرقة ســيارة املدعــي وطلــب مــن املدعــي‬\n      ‫أداء اليمــن املكملــة لبينتــه فرفــض ذلــك وطلــب ميــن املدعــى عليــه علــى‬\n      ‫نفــي دعــواه وحيــث رفــض املدعــى عليــه أداء اليمــن علــى نفــي دعــوى‬\n      ‫املدعــي ضــده وحلــف املدعــي علــى أن قيمــة ســيارته ســبعة عشــر ألــف‬\n      ‫ريــال فقــد ثبــت لــدي أن بذمــة املدعــى عليــه للمدعــي مبلــغ ســبعة عشــر‬\n      ‫ألــف ريــال وألزمتــه بتســليمها إيــاه حــا ًال بــدون مماطلــة أو تأخيــر وبذلــك‬\n      ‫حكمــت وبعرضــه علــى املدعــى عليــه قــرر عــدم قناعتــه بــه وطلــب رفعــه‬\n      ‫حملكمــة االســتئناف بــدون الئحــة اعتراضيــة وعليــه جــرى التوقيــع‬\n      ‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‬\n                                                                        ‫‪1434/01/20‬ه ـ‬\n      ‫احلمــد هلل والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ ،‬فقــد جــرى‬\n      ‫منــا نحــن قضــاة الدائــرة اجلزائيــة الســابعة مبحكمــة االســتئناف يف‬\n      ‫منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n      ‫رئيــس احملكمــة اجلزائيــة باملدينــة املنــورة رقــم ‪ 332178767‬وتاريــخ‬\n      ‫‪1434/2/12‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‪.../‬‬\n      ‫القاضــي باحملكمــة اجلزائيــة باملدينــة املنــورة رقــم ‪ 3423451‬وتاريــخ‬\n      ‫‪1434/1/26‬ه ـ احملكــوم فيــه مبــا دون بباطــن الصــك املتضمــن‬\n      ‫دعوى‪..........‬ســعودي اجلنســية ضد‪ ........... /‬ســعودي اجلنســية يف قضية‬\n      ‫حقوقيــة وبدراســة الصــك وصــورة ضبطــه تقــررت املوافقــة علــى احلكم‬\n      ‫‪ ،‬واهلل املوفــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n‫‪239‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":236,"source_page_end":239,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"389e66484e49d215531edbf865d873a79d16f3eb16850d2f9a53a9fe7706d6a1","normalized_text_hash":"231ef72d238c916329ce9a924f7d0960d2b1ed8cd05a52baf2c453f1034b113e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p236-3423451"},{"id":"4282c92f-30bc-5f52-9454-76e4636cb50f","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مسروق -سرقة أجهزة إلكترونية من متجر -إقرار -قبول قول املدعي مع ميينه -التثبت من صيغة اليمن ألهميتها -اليمن تشرع يف جانب أقوى املتداعين -ثبوت الدعوى -اإللزام بالسداد .","document_number":"34236377","case_number":"34122122","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باجلفر باألحساء بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/11","year":"1434","subject":"رد مسروق -سرقة أجهزة إلكترونية من متجر -إقرار -قبول قول املدعي مع ميينه -التثبت من صيغة اليمن ألهميتها -اليمن تشرع يف جانب أقوى املتداعين -ثبوت الدعوى -اإللزام بالسداد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/6/11 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34236377 :‬‬\n                   ‫َر ْق ُم الدعوى‪34122122 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 35117553‬تاريخه‪1435/1/16:‬هـ‬\n\n\n‫رد مســروق ‪ -‬ســرقة أجهــزة إلكترونيــة مــن متجــر ‪ -‬إقــرار ‪ -‬قبــول قــول‬\n‫املدعــي مــع ميينــه ‪ -‬التثبــت مــن صيغــة اليمــن ألهميتهــا ‪ -‬اليمــن‬\n‫تشــرع يف جانــب أقــوى املتداعيــن ‪ -‬ثبــوت الدعــوى ‪ -‬اإللــزام بالســداد ‪.‬‬\n\n\n\n\n                                       ‫اليمني تشرع يف جانب أقوى املتداعيني ‪.‬‬\n\n\n\n\n‫ادعــى وكيــل املدعــي بــأن املدعــى عليــه قــام بســرقة أجهــزة إلكترونيــة‬\n‫مــن متجــر مملــوك ملوكلــه وأتلــف أثنــاء ذلــك بعــض موجــودات املتجــر؛‬\n‫وطلــب إلزامــه بتســليم موكلــه قيمة املســروقات والتلفيات‪ -‬أقر املدعى‬\n‫عليــه بالســرقة إال أنــه أنكــر ســرقة بعــض األجهــزة التــي يطالــب بهــا‬\n‫املدعــي‪ -‬مــن املقــرر شــرعا أن اليمــن تشــرع يف جانب أقــوى املتداعيني‪-‬‬\n‫وألن جانــب املدعــي تقــوى بإقــرار املدعــى عليــه بالســرقة فيقبــل قولــه‬\n‫فيمــا يتعلــق بنــوع وقيمــة املســروقات‪ -‬لذلــك قــررت احملكمــة توجيــه‬\n‫اليمــن إلــى املدعــي علــى صحــة دعــواه فأداهــا طبــق مــا طلــب منــه‪-‬‬\n‫قضــت احملكمــة بإلــزام املدعــى عليــه بتســليم املدعــي قيمــة املســروقات‬\n‫والتلفيــات املدعــى بهــا‪ -‬عــارض املدعــى عليــه علــى احلكــم‪ -‬قــررت‬\n              ‫محكمــة االســتئناف باألكثريــة املصادقــة علــى احلكــم ‪.‬‬\n\n                                                                                 ‫‪240‬‬\n\f      ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ...‬القاضــي باحملكمــة العامــة‬\n      ‫باجلفــر باألحســاء بنــاء علــى االســتدعاء املقيــد بهــذه احملكمــة برقــم‬\n      ‫‪34644715‬يف ‪1434/3/15‬ه ـ واحملــال إلينــا مــن فضيلــة الرئيــس‬\n      ‫املكلــف برقــم ‪ 34122122‬يف ‪1434/3/15‬ه ـ املتعلقــة بدعوى ســعودي‬\n      ‫بالســجل املدنــي رقــم ‪ ...‬حــال كونــه وكيــا عــن مبوجــب الوكالــة‬\n      ‫الصــادرة مــن كتابــة عــدل اجلفــر برقــم ‪1459‬بتاريــخ ‪1433/3/21‬ه ـ‬\n      ‫ضــد ســعودي بالســجل املدنــي رقــم ‪ ...‬فبموجبــه حضــر لــدي الطرفــان‬\n      ‫يف هــذا اليــوم الســبت تاريــخ ‪1434/4/27‬ه ـ الســاعة التاســعة والنصــف‬\n      ‫صباحــا فادعــى املذكــور قائــا إن املدعــى عليــه ســرق محــل أجهــزة‬\n      ‫كمبيوتــر عائــد ملوكلــي وأطلــب إلزامــه بدفــع قيمــة املســروقات هــذه‬\n      ‫دعــواي فجــرى أفهــام املدعــي وكالــة أن الدعــوى يجــب حتريرهــا‬\n      ‫بذكــر املســروقات وأنواعهــا ومجمــوع املبلــغ الــذي يطالــب بــه موكلــك‬\n      ‫فقــال بأننــي أطلــب إمهالــي للرجــوع إلــى موكلــي وســوف أحــرر دعــواي‬\n      ‫يف اجللســة القادمــة وعليــه جــرى رفــع اجللســة ويف يــوم االثنــن تاريــخ‬\n      ‫‪ 1434/4/20‬ه ـ الســاعة التاســعة والنصــف صباحــا افتتحــت اجللســة‬\n      ‫وفيهــا حضــر املدعــي بالســجل املدنــي رقــم وحضــر حلضــوره املدعــى‬\n      ‫عليــه وبســؤال املدعــي عمــا طلبنــاه مــن وكيلــه قــال بــأن األجهــزة التــي‬\n      ‫ســرقها املدعــى عليــه هــي كمــا يلــي كمبيوتــر محمــول نــوع ‪ ...‬طــراز إل‬\n      ‫‪ 500‬وقيمتــه ألفــان وأربعمائــة وأربعــون ريــاال وكمبيوتــر محمــول نــوع‬\n      ‫إتــش بــي طــراز ‪ ...‬إي إي وقيمتــه مبلــغ الفــان وثالثمائــة وخمســة وأربعــون‬\n      ‫‪ 2345‬ريــال وجهــاز كمبيوتــر محمــول (الب تــوب ) نــوع ‪ ...‬قيمتــه الفــان‬\n\n‫‪241‬‬\n\f‫وأربعمائــة وأربعــون ‪ 2440‬ريــال وجهــاز وكمبيوتــر محمــول (الب تــوب)‬\n‫نــوع ‪ ...‬طــراز ‪ ...15‬وقيمتــه مبلــغ ألفــان وثالثمائــة وخمســة وأربعــون‬\n‫‪ 2345‬ريــال وكمبيوتــر محمــول (الب تــوب ) نــوع ‪ ...‬طــراز ‪ ...‬وقيمتــه‬\n‫مبلــغ ألــف وتســعمائة وســبعون ‪ 1970‬ريــال وكمبيوتــر محمــول (الب‬\n‫تــوب ) نــوع ‪ ...‬طــراز ‪ ...‬وقيمتــه مبلــغ ألــف وثمامنائــة وتســعون ريــال و‬\n‫كمبيوتــر محمــول الب تــوب نــوع ‪ ...‬طــراز ‪ ...‬وقيمتــه ألــف وثمامنائــة‬\n‫وخمســون ريــال و كمبيوتــر محمــول الب تــوب نــوع ‪ ...‬طــراز ‪ ...‬وقيمتــه‬\n‫ألــف وســبعمائة وخمســون ريــال و ثانيــا أجهــزة االتصــال جــواالت جهــاز‬\n‫جــوال نــوع ‪ ...‬طــراز ‪ ...‬وقيمتــه ألــف وثمامنائــة ريــال وجهــاز جــوال نــوع‬\n‫‪ ...‬طــراز ‪ ...‬وقيمتــه ألــف ومائــة ريــال مســتعمل و جهــاز جــوال نــوع ‪...‬‬\n‫طــراز ‪ ...‬وقيمتــه ألــف مائــة وخمســون ريــال و جهــاز جــوال نــوع ‪ ...‬طــراز‬\n‫‪ ...‬وقيمتــه ألــف ومائتــان وخمســون ريــال و جهــاز جــوال نــوع ‪ ...‬طــراز‬\n‫‪ ...‬وقيمتــه ســبعمائة وثمانــون ريــال و جهــاز نــوع ‪ ...‬طــراز ‪ ...‬وقيمتــه‬\n‫ثالثمائــة وخمســون ريــال و جهــاز نــوع ‪ ...‬طــراز ‪ ...‬وقيمتــه ثالثمائــة و‬\n‫خمســة وأربعــون ريــال وجهــاز جــوال نــوع ‪ ...‬طــراز ‪ ...‬وقيمتــه خمســمائة‬\n‫وســبعون ريــال وجهــاز جــوال نــوع ‪ ...‬طــراز ‪ ...‬وقيمتــه ثمامنائــة وخمســون‬\n‫ريــال وجهــاز جــوال نــوع ‪ ...‬طــراز ‪ ...‬وقيمتــه خمســمائة واربعــون ريــال‬\n‫وكذلــك مبلــغ نقــدي كان موجــود ًا يف درج احملــل وقــدره ســتمائة ‪600‬‬\n‫ريــال وكذلــك قــام املدعــى عليــه أثنــاء دخوله من النافــذة العلوية للمحل‬\n‫بكســر ســقف الديكــور وقطــع كابــات االنترنــت وأســاك اللوحــة‬\n‫اخلارجيــة مــع اإلضــاءة وســلك التلفــاز وخــط الهاتــف كمــا كســر طاولة‬\n‫املعــرض الزجاجيــة وكلهــا تقــدر مببلــغ ألــف و أربعمائــة‪ 1400‬ريــال و‬\n‫مجمــوع املبلــغ الــذي أطالــب املدعــى عليــه بدفعــه هــو ثالثــة وعشــرون‬\n\n\n                                                                                     ‫‪242‬‬\n\f      ‫ألــف ‪ 23.000‬ريــال هــذه دعــواي وبســؤال املدعــى عليــه عــن دعــوى‬\n      ‫املدعــي أجــاب قائــا بأننــي فعــا دخلــت احملــل يف املســاء مــن النافــذة‬\n      ‫العلويــة وقــد ســرقت مــن احملــل جهــازي البتــوب اثنــن فقــط وأمــا مــا‬\n      ‫ذكــره املدعــي مــن ســرقتي لعــدة أجهــزه وجــواالت فغيــر صحيــح وقــد‬\n      ‫مت احلكــم علــي يف احلــق العــام مــدة ســنتني مــع اجللــد وقــد خرجــت مــن‬\n      ‫الســجن قبــل انتهــاء املــدة بأربعــة أشــهر وأنــا ال أوافــق علــى دفــع مــا طلبــه‬\n      ‫املدعــي هكــذا أجــاب املدعــى عليــه ثــم جــرى ســؤال املدعــي هــل لديــك‬\n      ‫بينــه علــى أن املدعــى عليــه ســرق األجهــزة املذكــورة فقــال بأنــه ليــس‬\n      ‫لــدي شــهود علــى ذلــك وأنــا أكتفــي بإقــرار املدعــى عليــه بدخــول احملــل‬\n      ‫وســرقة اجلهازيــن ألنــه ليــس لــي أي مصلحــة أن أتهمــه بســرقة شــيء لــم‬\n      ‫يأخــذه وقــد حضــرت الشــرطة وشــاهدت احملــل بعــد ســرقته ومت احلكــم‬\n      ‫علــى املدعــى عليــه مــدة ســنتني مــن أجــل ســرقة األجهــزة املذكــورة‬\n      ‫وإلــى حــن دراســة هــذه القضيــة واالطــاع علــى الطــرد املرفــق بهــا جــرى‬\n      ‫رفــع اجللســة ويف يــوم االثنــن تاريــخ ‪1434/6/5‬ه ـ افتتحــت اجللســة يف‬\n      ‫متــام الســاعة التاســعة والنصــف صباحــا وفيهــا حضــر املدعــى وحضــر‬\n      ‫حلضــوره املدعــى عليــه وقــد ســبق منــي دراســة هــذه القضيــة ومــا ســبق‬\n      ‫ضبطــه فيهــا كمــا جــرى االطــاع علــى قــرار املدعــى عليه املصــدق على‬\n      ‫الصحيفــة رقــم (‪ )7‬مــن ملــف التحقيــق لفــه ( ‪ )2‬ونصــه ( أقــر أنــا احلــدث‬\n      ‫‪ 17‬ســنة ســعودي اجلنســية وأنــا بكامــل قــواي العقليــة املعتبــرة شــرعا‬\n      ‫ال مجبــر وال مكــره مــن أحــد أنــه مــن حوالــي أربعــة أشــهر تقريبــا ويف‬\n      ‫حوالــي الســاعة الثالثــة فجــرا ذهبــت إلــى محــل ‪ ...‬لالتصــاالت الواقــع‬\n      ‫بحــي ‪ ...‬الشــارع العــام وقمــت بتســلق بــاب احملــل حتــى وصلــت إلــى فتحــة‬\n      ‫تهويــة باحملــل وقمــت بالدخــول مــن تلــك الفتحــة إلــى الســطح بعــد ذلــك‬\n\n\n‫‪243‬‬\n\f‫قمــت بفتــح ديكــور الســطح ونزلــت داخــل احملــل وقمــت بســرقة عــدد‬\n‫(‪ )2‬أجهــزة الب تــوب وطلعــت مــن نفــس املــكان الــذي دخلــت منــه وقمت‬\n‫بوضــع األجهــزة بغرفتــي باملنــزل هــذا مــا حــدث وعليــه أوقــع وبعرضــه‬\n‫علــى املدعــى عليــه قــال فعــا أنــا ســرقت جهــازي البتــوب فقــط ولــم‬\n‫أســرق أكثــر مــن ذلــك ثــم جــرى االطــاع علــى فذلكــه التحقيــق لفــه‬\n‫(‪ )25-24‬وتتضمــن بــاغ املدعــي بســرقة أجهــزة كمبيوتــر وجــوالت‬\n‫ومبلــغ مــن املــال وأن املســروقات تقــدر مببلــغ عشــرين الــف‪ 20000‬ريــال‬\n‫وقــد أديــن املدعــى عليــه حتقيقــا بســرقة األجهــزة املذكــورة وبعــرض‬\n‫ذلــك علــى املدعــي قــال بأننــي ذكــرت هــذا املبلــغ للمحقــق يف أول‬\n‫وقــت الســرقة ولكــن بعــد ذلــك قمــت بجــرد املســروقات وتبــن لــي‬\n‫أن املبلــغ هــو مــا ادعيــت بــه علمــا أننــي لــم أضــف مبلــغ إتــاف احملــل‬\n‫والديكــور والزجــاج املكســور واكتفيــت مبــا تأكــدت مــن ســرقته‬\n‫يقينــا لكــي ال أحمــل ذمتــي أي شــيء مشــكوك فيــه ثــم جــرى االطــاع‬\n‫علــى القــرار الصــادر مــن قضــاة احملكمــة العامــة بالدمــام برقــم ‪/9/22‬‬\n‫ج‪ 6‬يف ‪1432/3/9‬ه ـ واملتضمــن احلكــم بتعزيــر املدعــى عليــه بالســجن‬\n‫ســنتني مــع اجللــد مائتــي جلــده واملكتســب القطعيــة بتصديــق محكمــة‬\n‫االســتئناف فبنــاء علــى مــا تقــدم وحيــث طالــب املدعــي بإلــزام املدعــى‬\n‫عليــه بدفــع املبلــغ املدعــى بــه والــذي ميثــل قيمــة املســروقات املذكــورة‬\n‫وحيــث أقــر املدعــى عليــه بدخــول محــل املدعــي وســرقة جهازيــن فقــط‬\n‫وأنكــر الباقــي وحيــث أن املدعــى عليــه مــدان حتقيقــا بســرقة األجهــزة‬\n‫املذكــورة كمــا مت احلكــم عليــه للحــق العــام بالســجن املــدة املذكــورة‬\n‫بالقــرار املشــار إليــه لقــاء ســرقة األجهــزة وحيــث أن ذلــك يقــوي جانــب‬\n‫املدعــي فيمــا أدعــى بــه وحيــث أن أهــل العلــم رحمهــم اهلل ذكــروا بــأن‬\n\n\n                                                                                    ‫‪244‬‬\n\f      ‫اليمــن تكــون يف جانــب أقــوى املتداعيــن وهــو املدعــي هنــا لــذا فقــد‬\n      ‫ســألت املدعــي هــل أنــت مســتعد بــأداء اليمــن فقــال نعــم فجــرى إفهامــه‬\n      ‫بخطــورة اليمــن الكاذبــة فقــال بأننــي واثــق مــن ســرقة املدعــى عليــه‬\n      ‫ثــم أمرتــه أن يحلــف فحلــف قائــا واهلل العظيــم الــذي ال الــه إال هــو أن‬\n      ‫املدعــى عليــه هــذا احلاضــر ســرق مــن محلــي ســت أجهــزه كمبيوتــر‬\n      ‫محمــول وعشــرة جــواالت ومبلــغ نقــدي ســتمائة ريــال ومجمــوع قيمــة مــا‬\n      ‫ســرقه ثالثــة وعشــرون ألــف ‪ 23000‬ريــال واهلل شــاهد علــى مــا أقــول‬\n      ‫هكــذا حلــف املدعــي لذلــك كلــه فقــد ثبــت لــدي مــا أدعــاه املدعــي‬\n      ‫ضــد املدعــى عليــه وألزمــت املدعــى عليــه بدفــع مبلــغ ثالثــة وعشــرين‬\n      ‫ألــف ‪ 23000‬ريــال فــورا للمدعــي وبذلــك حكمــت وبعــرض احلكــم‬\n      ‫علــى املدعــى عليــه قــرر عــدم قناعتــه باحلكــم وطلــب االســتئناف بعــد‬\n      ‫تقــدمي الئحــة اعتــراض فأجبتــه لطلبــه وأفهمتــه مبراجعــة احملكمــة يــوم‬\n      ‫االثنــن تاريــخ ‪1434/6/12‬ه ـ الســتالم صــورة مــن القــرار الشــرعي‬\n      ‫ومــدة االعتــراض ثالثــون يومــا ففهــم ذلــك وصلــى اهلل علــى نبينــا محمــد‬\n                                ‫وعلــى الــه وصحبــه وســلم حــرر يف ‪1434/6/5‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد عــادت األوراق مــن محكمــة االســتئناف‬\n      ‫يف املنطقــة الشــرقية برقــم ‪ 341902688‬يف ‪1434/9/6‬ه ـ املقيــدة‬\n      ‫بهــذه احملكمــة برقــم ‪ 342163918‬يف ‪ 1434/9/10‬ه ـ املرفــق بهــا‬\n      ‫القــرار الصــادر مــن الدائــرة احلقوقيــة الثانيــة برقــم ‪ 34307355‬يف‬\n      ‫‪1434/8/28‬ه ـ املتضمــن املالحظــة علــى احلكــم ونــص املالحظــة مــا‬\n      ‫يلــي ( وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق‬\n      ‫املعاملــة لوحــظ أن صيغــة اليمــن التــي أداهــا املدعي حتتــاج إلى تصحيح‬\n      ‫بحيــث يحلــف بــاهلل العظيــم انــه فقــد مــن محلــه ســتة أجهــزة كمبيوتــر‬\n\n\n‫‪245‬‬\n\f‫محمــول وعشــرة جــواالت ومبلــغ نقــدي مقــداره ســتمائة ريــال وإنــه ال‬\n‫يتهــم إال املدعــى عليــه بســرقة مــا ذكــر وعلــى فضيلتــه مالحظــة مــا‬\n‫ذكــر وإجــراء الــازم بحضــور الطرفــن واهلل املوفــق وصلــى اهلل علــى‬\n‫نبينــا محمــد وعلــى الــه وصحبــه وســلم حــرر يف ‪1434/8/28‬ه ـ قاضــي‬\n‫اســتئناف قاضــي اســتئناف رئيــس الدائــرة وبــه ختــم وتوقيــع كل منهــم‬\n‫عليــه ويف يــوم اخلميــس تاريــخ ‪1434/10/29‬ه ـ افتتحــت اجللســة يف متــام‬\n‫الســاعة العاشــرة والنصــف وفيهــا حضــر املدعــي ولــم يحضــر املدعــى‬\n‫عليــه وبعــرض مــا جــاء يف قــرار محكمــة االســتئناف اســتعد املدعــي‬\n‫بــأداء اليمــن فجــرى إفهامــه بخطــورة اليمــن الكاذبــة ثــم أمرتــه أن‬\n‫يحلــف فحلــف قائــا واهلل العظيــم أننــي فقــدت مــن محلــي ســتة أجهــزة‬\n‫كمبيوتــر محمــول وعشــرة جــواالت ومبلــغ نقــدي مقــداره ســتمائة ‪600‬‬\n‫ريــال وإننــي ال أتهــم إال املدعــى عليــه بســرقتها هكــذا حلــف لــذا فقــد‬\n‫أمــرت بإحلــاق ذلــك بالقــرار وإعادتــه حملكمــة االســتئناف واهلل املوفــق‬\n‫وللبيــان حــرر يف ‪1434/12/4‬ه ـ وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                             ‫آلــه وصحبــه وســلم‪.‬‬\n‫احلمــد هلل وحــده أمــا بعــد فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة احلقوقيــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة‬\n‫املقيــدة لــدى احملكمــة برقــم ‪ 342879195‬وتاريــخ ‪1434/12/25‬ه ـ‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة باجلفــر مبحافظــة اإلحســاء‬\n‫الشــيخ‪ ............. /‬برقــم ‪ 342163918‬وتاريــخ ‪1434/12/19‬ه ـ املرفــق‬\n‫بهــا الصــك الصــادر مــن فضيلتــه املســجل برقــم ‪ 34236377‬وتاريــخ‬\n‫‪1434/6/11‬ه ـ بشــأن دعــوى‪ ...... /‬ضــد‪ ....... /‬يف قضيــة حقوقيــه‬\n‫وقــد تضمــن الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪.‬‬\n\n\n                                                                                      ‫‪246‬‬\n\f      ‫وحيــث ســبق دراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n      ‫وأوراق املعاملــة وباإلطــاع علــى مــا أجــاب بــه فضيلتــه علــى قرارنــا ذي‬\n      ‫الرقــم ‪/34307355‬ق‪/2‬ب والتاريخ‪1434/8/28‬ه ـ قررنــا باألكثريــة‬\n      ‫املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                       ‫وصحبــه وســلم حــرر يف ‪1435/1/16‬ه ـ ‪.‬‬\n\n\n\n\n‫‪247‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":240,"source_page_end":247,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0d1ead798c5bcf95daf63ad524c63d5c38d0feff68927f723d98108d530c9011","normalized_text_hash":"f29f485449349706e3c27693121d63bb7c3fa8d70677c41f3ed875132b691e53","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p240-34236377"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"da505033-dc00-57fa-a00a-48b73fafea4e","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مسروق -سرقة مبلغ مالي من منزل -إدانة يف احلق العام - مترجم -بينة غير موصلة -اليمن على نفي الدعوى حق للمدعي وله عدم قبولها -احلكم برد الدعوى -استحقاق املدعي ليمن املدعى عليه على نفي الدعوى متى طلبها.","document_number":"34355584","case_number":"33561481","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/10","year":"1434","subject":"رد مسروق -سرقة مبلغ مالي من منزل -إدانة يف احلق العام - مترجم -بينة غير موصلة -اليمن على نفي الدعوى حق للمدعي وله عدم قبولها -احلكم برد الدعوى -استحقاق املدعي ليمن املدعى عليه على نفي الدعوى متى طلبها.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/11/10 :‬هـ‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪34355584 :‬‬\n                           ‫َر ْق ُم الدعوى‪33561481:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 35122590‬تاريخه‪1435/1/22:‬هـ‬\n\n\n       ‫رد مســروق ‪ -‬ســرقة مبلــغ مالــي مــن منــزل ‪ -‬إدانــة يف احلــق العــام ‪-‬‬\n       ‫مترجــم ‪ -‬بينــة غيــر موصلــة ‪ -‬اليمــن علــى نفــي الدعوى حــق للمدعي‬\n       ‫ولــه عــدم قبولهــا ‪ -‬احلكــم بــرد الدعــوى ‪ -‬اســتحقاق املدعــي ليمــن‬\n                             ‫املدعــى عليــه علــى نفــي الدعــوى متــى طلبهــا‪.‬‬\n\n\n\n\n       ‫‪ -1‬قــول النبــي صلــى اهلل عليــه وســلم‪ ( :‬لــو يعطــى النــاس بدعواهــم‬\n       ‫الدعــى نــاس دمــاء رجــال وأموالهــم ولكــن اليمــن علــى املدعــى عليــه)‬\n                                                                      ‫متفــق عليــه‪.‬‬\n       ‫‪ -2‬قــول النبــي صلــى اهلل عليــه وســلم‪( :‬البينــة علــى املدعــي واليمــن‬\n                                                 ‫علــى مــن أنكــر) رواه البيهقــي ‪.‬‬\n\n\n\n\n       ‫ادعــى املدعــي بــأن املدعــى عليهــا قامــت بســرقة مبلــغ مالــي مــن شــنطة‬\n       ‫كانــت يف منزلــه َّإبــان عملهــا لديــه كخادمــة منزليــة؛ وطلــب إلزامهــا‬\n       ‫بــرد املبلــغ املســروق ‪ -‬أنكــرت املدعــى عليهــا دعــوى املدعــي جتاههــا‬\n       ‫ســوى العثــور علــى جــزء مــن املبلــغ يف غرفتهــا ‪ -‬قــدم املدعــي بينــات‬\n       ‫غيــر موصلــة ولــم يقبــل ميــن املدعــى عليهــا علــى نفــي دعــواه‪ -‬مــن املقــرر‬\n       ‫شــرعا أن البينــة علــى املدعــي واليمــن علــى املدعــى عليــه ‪ -‬فقــد قضــت‬\n\n‫‪209‬‬\n\f‫احملكمــة بصــرف النظــر عــن طلــب املدعــي وأفهمتــه بــأن لــه ميــن‬\n‫املدعــى عليهــا متــى طلبهــا ‪ -‬قنعــت املدعــى عليهــا باحلكــم وعــارض‬\n ‫عليــه املدعــي ‪ -‬قــررت محكمــة االســتئناف املوافقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالطائــف برقــم ‪ 33561481‬وتاريــخ ‪ 1433/09/04‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 331640237‬وتاريــخ ‪ 1433/09/03‬ه ـ ففــي يــوم‬\n‫األحــد املوافــق ‪ 1433/11/14‬ه ـ افتتحــت اجللســة الســاعة ‪12 : 00‬‬\n‫وفيهــا حضــر ســعودي اجلنســية‪ ......./‬مبوجــب ســجله املدنــي رقــم‪....../‬‬\n‫وحضــرت حلضــوره‪ ......../‬إندونيســية اجلنســية مبوجــب اجلــواز رقــم‪......./‬‬\n‫واملعــرف بهــا مــن قبــل مشــرفة التفتيــش علــى النســاء باحملكمــة ثــم‬\n‫ادعــى األول قائــا يف دعــواه إن املدعــى عليهــا كانــت تعمــل لــدي‬\n‫كخادمــة منزليــة ثــم إنه يف صباح يوم األربعاء املوافق ‪1433/01/19‬هـ‬\n‫كنــت نائمــا حيــث عملــت عمليــة جراحيــة وكان لــدي شــنطة وفيهــا‬\n‫مبلــغ وقــدره مائــة وخمســة عشــر ألــف ريــال وجــوازات ســفر وثــاث‬\n‫جــواالت نــوع ‪ ...‬وعلبــة فيهــا ذهــب وملــا عــادت زوجتــي بعــد الظهــر لــم‬\n‫جتــد الشــنطة فقمنــا بالبحــث يف البيــت ثــم وجدنــا الشــنطة علــى ســطح‬\n‫البيــت وهــي مكســورة وقــد ألقــي مــا فيهــا مــن جــوازات ســفر وجــوالت‬\n‫وذهــب بجوارهــا وأمــا املبلــغ املالــي فلــم يعثــر عليه وبعد أن بلغنا الشــرطة‬\n‫أرشــدت املدعــى عليهــا إلــى قطعــة إســمنتية ( بلــك ) وجــد حتتهــا مبلــغ‬\n‫وقــدره ســبعة عشــر ألــف وأربعمائــة وســتة عشــر ريــاال كمــا مت تفتيــش‬\n                                                                                     ‫‪210‬‬\n\f      ‫غرفــة املدعــى عليهــا وعثــر فيهــا علــى مبلــغ وقــدره ثالثــون ألــف ريــال‬\n      ‫وقــد صــدر يف احلــق العــام قــرار مــن احملكمــة اجلزئيــة بالطائــف برقــم‬\n      ‫‪ 33286491‬يف تاريــخ ‪1433/06/08‬ه ـ ويتضمــن إثبــات إدانــة املدعــى‬\n      ‫عليهــا بســرقة مبلــغ مالــي مــن حــرز وهــذا القــرار مصــدق مــن محكمــة‬\n      ‫االســتئناف وبقــي لديهــا مبلــغ وقــدره ســتة وثمانــون ألــف وخمســمائة‬\n      ‫وثالثــة وثمانــون ريــاال أطلــب احلكــم عليهــا بدفعــه لــي هــذه دعــواي‬\n      ‫ونظــرا ألن املدعــى عليهــا ال تتقــن العربيــة وألنــه ال يوجــد مترجــم‬\n      ‫باحملكمــة جــرى رفــع اجللســة وتأجيلهــا ويف جلســة اخــرى يف يــوم األحــد‬\n      ‫املوافــق‪ 1434/01/11‬ه ـ حضــر املدعــي وأمــا املدعــى عليهــا فلم حتضر‬\n      ‫ونظــرا لكــون املدعــى عليهــا ســجينه بالســجن العــام بالطائــف فلــم تيــم‬\n      ‫احضارهــا مــن قبــل الســجن لــذا فقــد قــررت الكتابــة للســجن إلحضــار‬\n      ‫املدعــى عليهــا ويف جلســة أخــرى يف يــوم األحــد املوافــق‪ 1434/02/10‬هـ‬\n      ‫حضــر املدعــي وحضــرت حلضــوره املدعــى عليهــا واملعــرف بهــا مــن قبــل‬\n      ‫مفتشــة النســاء باحملكمــة وحضــر أيضــا بصفتــه مترجــم احملكمــة ثــم‬\n      ‫جــرى عــرض دعــوى املدعــي علــى املدعــى عليهــا بواســطة املترجــم‬\n      ‫فأجابــت قائلــة مــا ذكــره املدعــي يف دعــواه كلــه غيــر صحيــح جملــة‬\n      ‫وتفصيــا ماعــدا أننــي وضعــت مبلــغ وقــدره ثالثــن ألــف ريــال وأنــه‬\n      ‫وجــده املدعــي فــإن ذلــك صحيــح هكــذا أجــاب ثــم جــرى ســؤال املدعــي‬\n      ‫هــل لديــك بينــة علــى أن املدعــى عليهــا قــد ســرقت املبلــغ املذكــور يف‬\n      ‫الدعــوى فقــال ليــس لــدي بينــة ســوى مــا جــاء يف قــرار احملكمــة اجلزئيــة‬\n      ‫املشــار إلــي رقمــه وتاريخــه يف دعــواي ونظــرا النتهــاء وقــت اجللســة جــرى‬\n      ‫رفعهــا وتأجيلهــا ويف جلســة أخــرى يف يــوم األحــد املوافــق‪1434/03/08‬‬\n      ‫ه ـ حضــر املدعــي وأمــا املدعــى عليهــا فهــي ســجينة ولــم حتضــر مــن قبــل‬\n\n\n‫‪211‬‬\n\f‫الســجن وقــد ســبق أن ذكــر املدعــي بــأن بينتــه هــو مــا جــاء يف القــرار‬\n‫الصــادر مــن احملكمــة اجلزئيــة وباالطــاع علــى املعاملــة وجــد ضمــن‬\n‫طياتهــا القــرار رقــم ‪ 33286491‬يف ‪1433/6/8‬ه ـ والصــادر مــن‬\n‫احملكمــة اجلزائيــة بالطائــف واملصــدق مــن محكمــة االســتئناف‬\n‫مبنطقــة مكــة املكرمــة مبوجــب القــرار رقــم ‪ 33286491‬يف تاريــخ‬\n‫‪1433/6/8‬ه ـ واملتضمــن مــا نــص احلاجــة منــه (مــا ذكــره املدعــي العــام‬\n‫مــن أننــي قمــت بســرقة مبلــغ مالــي عائــد لكفيلــي ولــم أقــم بكســر‬\n‫األبــواب وإمنــا وجــدت الشــنطة يف الغرفــة فقمــت بأخــذ الشــنطة مــن‬\n‫دوالب كفيلــي فصحيــح ومــا مــا ذكــره املدعــي العــام مــن مقــدار املبلــغ‬\n‫فأنــا ال أعلــم عنــه بالتحديــد هكــذا أجابــت وبطلــب البينــة مــن املدعــي‬\n‫العــام علــى مقــدار املبلــغ املدعــى بــه قــال بينتــي اعترافهــا املصــدق شــرعا‬\n‫لفــه (‪ )4‬ص (‪ )15‬واملتضمــن أنــه أثنــاء غيــاب أصحــاب املنــزل عــن‬\n‫منزلهــم قمــت بفتــح الــدوالب اخلــاص باملالبــس التابعــة لهــم واســتيالئي‬\n‫علــى شــنطة بنيــة اللــون وكذلــك كيــس بالســتيكي يوجــد بــه مبلــغ‬\n‫مــن املــال والتوجــه بــه إلــى أعلــى ســطح املنــزل ثــم قمــت بفتــح الشــنطة‬\n‫وأخــذ جميــع املبلــغ املالــي الــذي كان بداخــل الشــنطة والكيــس ثــم‬\n‫قمــت بتجزئتــه إلــى جزأيــن أحــد اجلزأيــن قمــت بوضعــه فــوق الســطح‬\n‫حتــت أحــد القطــع اإلســمنتية والقســم اآلخــر قمــت بوضعــه بداخــل‬\n‫ســيفون دورة امليــاه اخلاصــة بــي وكان هــذا العمــل مبفــردي ولــم يكــن‬\n‫معــي أي شــخص آخــر ولــم أجــد فيــه مــا ينــص علــى مقــدار املبلــغ يف‬\n‫اعترافهــا وبســؤال املدعــي العــام هــل لديــك زيــادة بينــة أجــاب قائــا‬\n‫اكتفــى مبــا يف أوراق املعاملــة مــن بينــات ولــم أجــد فيهــا مــا يعضــد‬\n‫دعــواه يف إثبــات مقــدار املبلــغ فضــا أن بعضهــا ممــا ذكــره املبلــغ‬\n\n\n                                                                                        ‫‪212‬‬\n\f      ‫وزوجتــه ومــا ذكــراه دعــوى حتتــاج إلــى بينــة وبنــاء علــى مــا تقــدم مــن‬\n      ‫الدعــوى واإلجابــة وحيــث صادقــت املدعــى عليهــا علــى ســرقة مبلــغ‬\n      ‫مالــي ونظــرا لكــون مــا أقدمــت عليــه املدعــى عليهــا يعــد عمــا محرمــا‬\n      ‫وفعــل قبيــح وجــرأة يف الباطــل واعتــداء علــى أمــوال النــاس بغيــر حــق‬\n      ‫ولقولــه صلــى اهلل عليــه وســلم (ال يحــل مــال امــرئ مســلم إال بطيــب نفس‬\n      ‫منــه) لهــذا كلــه فقــد ثبــت لــدي إدانــة املدعــى عليهــا بســرقة مبلــغ مالــي‬\n      ‫مــن دون حرز)أ‪.‬ه ـ ثــم أضــاف املدعــي أن املدعــى عليهــا لهــا إقــرار‬\n      ‫مصــدق شــرعا علــى اللفــة رقم ‪ 4‬ص ‪ 15‬ضمــن طيات املعاملة وباالطالع‬\n      ‫عليــه وجــد يتضمــن مــا نصــه (أقــر أنــا املدعــوة‪ /‬إندونيســية اجلنســية‬\n      ‫مبوجــب اجلــواز رقــم وإقامــة رقــم أقــر لــدى جهــة التحقيــق بداخــل شــعبة‬\n      ‫الســجن العــام وأنــا بكامــل قــواي العقليــة املعتبــرة شــرعا ال مجبــره وال‬\n      ‫مكرهــه مــن أحــد أقــر بأننــي قمــت بدخــول غرفــة زوجــة كفيلــي يف‬\n      ‫يــوم األربعــاء املوافــق ‪1433/1/19‬ه ـ وأثنــاء غيابهــم عــن املنــزل قمــت‬\n      ‫بفتــح الــدوالب اخلــاص باملالبــس التابعــة لهــم واســتيالئي علــى شــنطة‬\n      ‫بنيــة اللــون وكذلــك كيــس بالســتيكي يوجــد بــه مبلــغ مــن املــال‬\n      ‫والتوجــه بــه إلــى أعلــى ســطح املنــزل ثــم قمــت بفتــح هــذه الشــنطة‬\n      ‫والكيــس ثــم قمــت بتجزئتــه إلــى جزأيــن أحــد هــذه اجلزأيــن قمــت‬\n      ‫بوضعــه فــوق الســطح حتــت أحــد القطــع اإلســمنتية (بلــك) واجلــزء اآلخــر‬\n      ‫قمــت بوضعــه يف كيــس بالســتيكي ووضعتــه بداخــل ســيفون دورة‬\n      ‫امليــاه يف الــدور األســفل مــن منــزل كفيلــي وقمــت بإلقــاء الشــنطة فــوق‬\n      ‫ســطح غرفــة الــدرج و كان هــذا العمــل قمــت بــه مبفــردي ولــم يكــن‬\n      ‫معــي أي شــخص آخــر وكنــت أحــاول التهــرب والتخلــص ممــا نســب إلــي‬\n      ‫مــن تهمــه إال أننــي لــم أســتطع ذلــك وعلــى هــذا أســجل إقــرار واعتــرايف‬\n\n\n‫‪213‬‬\n\f‫وعلــى ذلــك أوقــع) وحتــى حتضــر املدعــى عليهــا لعــرض ذلــك عليهــا‬\n‫جــرى رفــع اجللســة وتأجيلهــا ويف جلســة أخــرى يف يــوم األحــد املوافــق‬\n‫‪ 1434/04/14‬ه ـ حضــر املدعــي وحضــرت حلضــوره املدعــى عليهــا‬\n‫وحضــر مترجــم احملكمــة ‪ ...‬ثــم جــرى ســؤال املدعــي هــل لديــك زيــادة‬\n‫بينــة فقــال ليــس لــدي زيــادة بينــة هكــذا قــرر ونظــرا ألن مترجــم‬\n‫احملكمــة احلاضــر ال يتقــن اللغــة اإلندونيســية جــرى رفــع اجللســة‬\n‫إلحضــار مترجــم آخــر ويف جلســة أخــرى يف يــوم األربعــاء املوافــق‬\n‫‪ 1434/05/22‬ه ـ حضــر املدعــي واملدعــى عليهــا واملعــرف بهــا مــن قبلــه‬\n‫ولــم يحضــر املترجــم وقــد جــرت مهاتفــة قســم اخلبــراء باحملكمــة‬\n‫وأفــادوا بأنــه تعــذر حضــوره لهــذا اليــوم ويرغبــون يف حتديــد موعــد آخــر‬\n‫للجلســة ليتســنى لهــم إحضــاره وقــد قــرر املدعــي قائــا لقــد راجعــت‬\n‫قســم النزهــة وطلبــت منهــم تزويــدي بإثباتــات تتعلــق بالقضيــة فأفادنــي‬\n‫مديــر قســم شــرطة النزهــة بــأن إثباتــات القضيــة جميعهــا مرفقــة‬\n‫باملعاملــة وأهــم إثبــات مــدون يف دفاتــر التحقيــق هكــذا قــال ثــم أضــاف‬\n‫أطلــب مــن فضيلتكــم االطــاع عليهــا هكــذا قــرر وحتــى يحصــل ذلــك‬\n‫ويتــم حضــور املترجــم جــرى رفــع اجللســة وتأجيلهــا ويف جلســة أخــرى يف‬\n‫يــوم األحــد املوافــق ‪1434/07/02‬ه ـ حضــر املدعــي وحضــرت حلضــوره‬\n‫املدعــى عليهــا واملعــرف بهــا مــن قبلــه وقــد ســبق وأن رفعــت اجللســة لطلب‬\n‫مترجــم وطلــب املعاملــة األساســية لالطــاع علــى البيانــات التــي يطلــب‬\n‫املدعــي االطــاع عليهــا عليــه فقــد جــرى بعــث أوراق املعاملــة وباالطــاع‬\n‫عليهــا وســؤال املدعــي عــن بينتــه فيهــا قــال بينتــي هــي‪ :‬أوالً‪ :‬إقرارهــا‬\n‫املصــدق شــرعاً‪ .‬ثاني ـاُ‪ :‬محضــر تفتيــش غرفــة املدعــى عليهــا حيــث‬\n‫تضمــن العثــور علــى مبلــغ ثالثــن ألــف ريــال‪ .‬ثالثـاً‪ :‬محضــر داللتهــا علــى‬\n\n\n                                                                                     ‫‪214‬‬\n\f      ‫مــكان تخبيــة بقيــة املبلــغ‪ .‬هكــذا قــرر‪ .‬وباالطــاع علــى أوراق املعاملــة‬\n      ‫وجــد علــى اللفــة رقــم(‪ )4‬إقــرار مصــدق شــرع ًا مــن احملكمــة اجلزئيــة‬\n      ‫بالطائــف ونصه(أقــر أنــا املدعــوة‪ ......./‬إندونيســية اجلنســية مبوجــب‬\n      ‫اإلقامــة رقــم‪ ....../‬أقــر لــدى جهــة التحقيــق بداخــل شــعبة الســجن العــام‬\n      ‫وأنــا بكامــل قــواي العقليــة املعتبــرة شــرع ًا ال مجبــرة وال مكرهــه مــن‬\n      ‫أحــد أقــر بأننــي قمــت بدخــول غرفــة زوجــة كفيلــي يف يــوم األربعــاء‬\n      ‫املوافــق ‪1433/1/19‬ه ـ وأثنــاء غيابهــم عــن املنــزل قمــت بفتــح الــدوالب‬\n      ‫اخلــاص باملالبــس التابعــة لهــم واســتيالئي علــى شــنطة بنيــة اللــون‬\n      ‫وكذلــك كيــس بالســتيكي يوجــد بــه مبلــغ مــن املــال والتوجــه بــه إلــى‬\n      ‫أعلــى ســطح املنــزل ثــم قمــت بفتــح هــذه الشــنطة وهــذا الكيــس وأخــذ‬\n      ‫جميــع املبلــغ املالــي الــذي كان يوجــد داخــل الشــنطة والكيــس ثــم‬\n      ‫قمــت بتجزئتــه إلــى جزأيــن أحــد هــذه اجلزأيــن قمــت بوضعــه فــوق‬\n      ‫الســطح حتــت أحــد القطــع اإلســمنتية (بلــك) واجلــزء اآلخر قمــت بوضعه‬\n      ‫يف كيــس بالســتيكي ووضعتــه بداخــل ســيفون دورة امليــاه اخلاصــة بــي‬\n      ‫يف الــدور األســفل مــن منــزل كفيلــي وقمــت بإلقــاء الشــنطة فــوق ســطح‬\n      ‫غرفــة الــدرج وهــذا العمــل قمــت بــه مبفــردي ولــم يكــن معــي أي شــخص‬\n      ‫آخــر وكنــت أحــاول التهــرب والتخلــص ممــا نســب إلــي مــن تهمــة إال‬\n      ‫إننــي لــم أســتطع ذلــك وعلــى هــذا أســجل إقــراري واعتــرايف وعلــى ذلــك‬\n      ‫أوقــع)‪ .‬ونظــر ًا النتهــاء وقــت اجللســة جــرى رفعهــا وتأجيلهــا ويف جلســة‬\n      ‫أخــرى يف يــوم الثالثــاء املوافــق‪ 1434/07/25‬ه ـ حضــر املدعي واملدعى‬\n      ‫علهــا واملعــرف بهــا مــن قبلــه وأمــا املترجــم فلــم يحضــر وقــد ســبقت‬\n      ‫الكتابــة لفضيلــة رئيــس احملكمــة وذلــك مبوجــب خطابنــا رقــم‬\n      ‫‪ 341724431‬يف ‪ 1434/7/17‬هـ وذلك بطلب مترجم للغة اإلندونيسية‬\n\n\n‫‪215‬‬\n\f‫لغــة املدعــى عليهــا وأحيــل هــذا اخلطــاب بشــرح رئيــس احملكمــة إلــى‬\n‫قســم اخلبــراء ثــم أعيــد إلينــا بشــرح رئيــس قســم اخلبــراء واملتضمــن ( أنــه‬\n‫ال يوجــد لديهــم مترجــم للغــة اإلندونيســية)‪.‬أ‪ .‬ه ـ وقــد ســبق أن ذكــر‬\n‫املدعــي أن بينتــه هــي إقــرار املدعــى عليهــا املصــدق شــرعا ومحضــر‬\n‫تفتيــش غرفــة املدعــى عليهــا ومحضــر داللتهــا وســبق رصــد إقرارهــا ثــم‬\n‫جــرى االطــاع علــى أوراق املعاملــة فوجــد علــى اللفــة رقــم ‪ 4‬ص ‪ 7‬مــا‬\n‫نصــه (بحضورنــا نحــن املوقعــن أدنــاه ويف متام الســاعة الواحدة والنصف‬\n‫مــن مســاء يــوم االثنــن املوافــق أعــاه جــرى االنتقــال إلــى منــزل املدعــو‬\n‫‪ ...‬الواقــع بحــي ‪ ...‬بالدخــول إلــى املنــزل برفقة املذكور تفتيش الســكن‬\n‫اخلــاص باخلادمــة املدعــوة ‪ ...‬وبتفتيشــه عثــر علــى مبلــغ ‪30000‬ريــال‬\n‫ملفوفــة داخــل كيــس بالســتيكي وجهــاز جــوال بداخــل محفظــة‬\n‫ســوداء مــن نــوع ‪ ...‬لونــه أبيــض وكان املبلــغ واجلــوال موجــود بداخــل‬\n‫ســيفون املــاء اخلــاص بــدورة امليــاه اخلاصــة بتلــك الغرفــة هــذا وحفظــا‬\n‫للحقيقــة والواقــع نظــم هــذا احملضــر وقــد جــرى تصويــر املوقــع مــن قبــل‬\n‫املختصــن يف األدلــة اجلنائيــة ) وعلــى اللفــة ‪ 4‬ص‪( 8‬جــرى االطــاع علــى‬\n‫مــا مت ضبطــه مــن مبلــغ مالــي وجهــاز جــوال بداخــل دورة امليــاه اخلاصــة‬\n‫باخلادمــة املدعــوة ‪ ........‬وكانــت املضبوطــات عبــارة عــن مبلــغ وقــدر‬\n‫‪ 30000‬ثالثــون ألــف ريــال جميعهــا مــن فئــة اخلمســمائة ريــال وكانــت‬\n‫ملفوفــة بكيــس بالســتيكي شــفاف يوجــد بــه كتابــة باللــون االصفــر‬\n‫تعــود الحــد املخابــز مخبــز ‪ ...‬وكذلــك جهــاز جــوال مــن نــوع ‪ .....‬لونــه‬\n‫أبيــض موديــل ‪ ......‬كان موضــوع بداخــل محفظــة نســائية ســوداء اللــون‬\n‫وكانــت ملفوفــة بداخــل كيــس بالســتيكي لونــه أزرق) وعلــى ص‬\n‫‪ (11‬ذكــرت جاراواتــي باجيمــن اثنــاء مناقشــتها داخــل الســجن أنــه‬\n\n\n                                                                                       ‫‪216‬‬\n\f      ‫يوجــد مبلــغ ال تعــرف قــدره فــوق ســطح املنــزل وجــرى االنتقــال للمنــزل‬\n      ‫وبالدخــول وتفتيــش ســطح املنــزل داخــل غرفــة وجــد مبلــغ ســبعة عشــر‬\n      ‫ألــف ريــال) ونظــرا النتهــاء الوقــت احملــدد للجلســة ولعــدم حضــور‬\n      ‫املترجــم قــررت رفــع اجللســة والكتابــة مجــددا لفضيلــة رئيــس احملكمة‬\n      ‫لبعــث مترجــم ويف جلســة أخــرى يف يــوم الثالثــاء املوافــق ‪1434/09/08‬‬\n      ‫ه ـ حضــر املدعــي أمــا املدعــى عليــه فلــم حتضــر وهــي ســجينة ولــم يردنــا‬\n      ‫مــن قبــل ســجن شــعبة الســجن إفــادة عــن ســبب عــدم بعثهــا وقــد طلــب‬\n      ‫املدعــي حتديــد موعــد آخــر وحيــث ال مانــع فقــد جــرى رفــع اجللســة‬\n      ‫وتأجيلهــا ويف جلســة أخــرى يف يــوم األحــد املوافــق ‪ 1434/11/09‬ه ـ‬\n      ‫حضــر املدعــي واملدعــى عليهــا وحضــر حلضورهــم اندونيســي اجلنســية‬\n      ‫مبوجــب اإلقامــة رقــم ثــم قــرر املدعــي قائــا لقــد ذكــرت يف دعــواي يف‬\n      ‫أول جلســة إننــي اطالــب مببلــغ وقــدره ســتة وثمانــون ألــف وخمســمائة‬\n      ‫وثالثــة وثمانــون ريــال والصحيــح أننــي أطالــب مببلــغ وقــدره مائــة ألــف‬\n      ‫وألفــن وســتمائة ريــال كمــا أن القــرار املشــار إليــه الصــادر عــن‬\n      ‫احملكمــة اجلزئيــة يتضمــن إدانتهــا بســرقة بــدون حــرز أطلــب تصحيــح‬\n      ‫دعــواي بذلــك هكــذا قــرر ثــم جــرى ســؤال املدعي عما ذكرتــه املدعى‬\n      ‫عليهــا يف اجللســة الثالثــة مــن أنــه اســتلم مبلــغ وقــدره ثالثــون ألــف ريــال‬\n      ‫فأجــاب نعــم ذلــك صحيــح هكــذا قــرر ثــم جــرى عــرض اإلقــرار‬\n      ‫(التحقيقــي) املنســوب للمدعــى عليهــا واملرصــود يف اجللســة الرابعــة‬\n      ‫واإلقــرار املصــدق شــرعا املنســوب للمدعــى عليهــا واملرصــود يف اجللســة‬\n      ‫الســابعة ومــا مت رصــده يف اجللســة الثامنــة مــن محاضــر وذلــك بواســطة‬\n      ‫املترجــم فأجابــت املدعــى عليهــا قائلــة بواســطته‪ :‬مــا ذكــر يف هــذه‬\n      ‫احملاضــر غيــر صحيــح جملــة وتفصيــا فأنــا لــم أســرق أي مبلــغ مالــي‬\n\n\n‫‪217‬‬\n\f‫وإمنــا فتحــي الــدوالب الــذي توجــد فيــه الشــنطة التــي بداخلهــا املــال‬\n‫وكنــت أبحــث عــن جوالــي وأخــذت الشــنطة التــي فيهــا املــال ظنــا منــي‬\n‫أن جوالــي فيهــا وتوجهــت بهــا إلــى الســطح وفتحتهــا بقــوة فانكســرت‬\n‫وتبــن لــي أن جوالــي ليــس فيهــا مبالــغ ماليــة فخفــت مــن ذلــك فوضعــت‬\n‫جــزء مــن املبالــغ املاليــة حتــت (بلكــة) يف الســطح وجــزء حتــت (ســيفون‬\n‫احلمــام ) ولــم أســرق منهــا أي شــيء وقــد وجدوهــا فيمــا بعــد هكــذا‬\n‫قــررت ثــم جــرى ســؤال املدعــي هــل لديــك زيــادة بينــة فقــال ليــس لــدي‬\n‫زيــادة بينــة ثــم جــرى ســؤال املدعــي هــل تطلب ميــن املدعى عليهــا فأجاب‬\n‫قائــا إننــي ال أطلــب ميينهــا وال أرضاهــا هكــذا قــرر ثــم جــرى ســؤال‬\n‫املتداعيــن هــل لديكمــا إضافــة علــى مــا ســبق فقــاال ليــس لدينــا إضافة‬\n‫علــى مــا ســبق هكــذا قــرر ا فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n‫وألن املدعــي ليــس لــه بينــة موصلــة وألن مــا أشــار إليــه املدعــي ممــا جــاء‬\n‫يف املعاملــة مبــا يف ذلــك اإلقــرار املصــدق شــرعا غيــر موصــل فلــم ينــص‬\n‫فيــه علــى املبلــغ املالــي الــذي يطالــب بــه املدعــي كمــا أن املدعــى عليهــا‬\n‫أنكــرت مــا جــاء يف هــذه األقاريــر واحملاضــر وألن املدعــي قــرر بأنــه‬\n‫ليــس لديــه زيــادة بينــة وملــا جــاء يف حديــث ابــن عبــاس قــال رســول اهلل‬\n‫صلــى اهلل عليــه وســلم ( لــو يعطــى النــاس بدعواهــم الدعــى نــاس دمــاء‬\n‫رجــال وأموالهــم ولكــن اليمــن علــى املدعــى عليــه ) متفــق عليــه واللفــظ‬\n‫ملســلم وللبيهقــي ( البينــة علــى املدعــي واليمــن علــى مــن أنكــر ) وألن‬\n‫املدعــي قــرر أنــه ال يطلــب ميــن املدعــى عليهــا لذلــك كلــه فقــد حكمت‬\n‫بصــرف النظــر عــن طلــب املدعــي احلكــم علــى املدعــى عليهــا بدفــع‬\n‫املبلــغ املالــي وأفهمتــه بــان لــه ميــن املدعــى عليهــا متــى طلبهــا وبعــرض‬\n‫احلكــم علــى املدعــي واملدعــى عليهــا قــرر املدعــي عــدم قناعتــه باحلكــم‬\n\n\n                                                                                       ‫‪218‬‬\n\f      ‫وقــررت املدعــى عليهــا قناعتهــا باحلكــم فأفهــم املدعــي بــأن يحضــر‬\n      ‫غــدا االثنــن املوافــق ‪ 1434/11/10‬ه ـ الســتالم نســخة مــن احلكــم‬\n      ‫وأفهــم بتعليمــات االســتئناف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                     ‫محمد وعلى آله وصحبه وسلم ‪ .‬حرر يف ‪ 1434/11/09‬هـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪،‬‬\n      ‫فقــد جــرى منــا نحــن قضــاة االســتئناف بالدائــرة اجلزائيــة السادســة‬\n      ‫مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة جــرى منــا اإلطــاع على‬\n      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بالطائــف برقــم‬\n      ‫(‪ )331640237‬وتاريــخ (‪1435/1/10‬هــ) املرفــق بهــا الصــك الصــادر‬\n      ‫مــن فضيلــة الشــيخ‪ ،........ /‬القاضــي باحملكمــة العامــة بالطائــف برقــم‬\n      ‫(‪ )34355584‬وتاريخ (‪1434/11/10‬هـ) املتضمن دعوى ‪ .......‬ســعودي‬\n      ‫اجلنســية ضــد‪ ....... /‬إندونيســية اجلنســية يف ســرقة مــال‪ ،‬احملكــوم فيــه‬\n      ‫مبــا دون باطنــه‪ ،‬وبدراســة الصــك وصــورة ضبطــه تقــررت املوافقــة‬\n      ‫علــى احلكــم‪ ،‬واهلل املوفــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                  ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪219‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":209,"source_page_end":219,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f67689df5edeb6f0d07132bc3aff58bde86f8e6b9482220955303f71ce0283ff","normalized_text_hash":"34cb33ca5d460dc2bf30796d3050a8001e18bacd17662185c418daca8dd1a229","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p209-34355584"},{"id":"de28c953-a9db-51bf-a63b-1098d7f8f904","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مسروق -سرقة سيارة من ورشة سيارات -تفريط يف حفظ املسروق -تقدير قيمة السيارة عن طريق رئيس معارض السيارات -ضمان األجير املشترك -إلزام املدعى عليه بدفع قيمة السيارة .","document_number":"3437753","case_number":"33626232","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بينبع","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/16","year":"1434","subject":"رد مسروق -سرقة سيارة من ورشة سيارات -تفريط يف حفظ املسروق -تقدير قيمة السيارة عن طريق رئيس معارض السيارات -ضمان األجير املشترك -إلزام املدعى عليه بدفع قيمة السيارة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/2/16 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3437753 :‬‬\n                   ‫َر ْق ُم الدعوى‪33626232:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34373689‬تاريخه‪1434/11/27:‬هـ‬\n\n\n‫رد مســروق ‪ -‬ســرقة ســيارة مــن ورشــة ســيارات ‪ -‬تفريــط يف حفــظ‬\n‫املســروق ‪ -‬تقديــر قيمــة الســيارة عــن طريــق رئيــس معــارض الســيارات‬\n‫‪ -‬ضمــان األجيــر املشــترك ‪ -‬إلــزام املدعــى عليــه بدفــع قيمــة الســيارة ‪.‬‬\n\n\n\n\n‫مــا اســتند إليــه القاضــي مــن مبــادئ عامــة وقواعــد العدالــة الــواردة يف‬\n                                                           ‫تســبيب احلكــم ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي بأنــه ســلم ســيارته للمدعــى عليــه ليقــوم بإصالحهــا يف‬\n‫الورشــة التــي يعمــل بهــا‪ ،‬وملــا حضــر يف اليــوم التالــي لــم يجدهــا فســأل‬\n‫املدعــى عليــه عنهــا فأجابــه بأنــه ال يعلــم؛ ولــذا فقــد طلــب إلزامــه بإعــادة‬\n‫قيمــة تلــك الســيارة إليــه‪ -‬أقــر املدعــى عليه باســتالم الســيارة من املدعي‬\n‫ليقــوم بإصالحهــا وأنهــا فقــدت بعــد ذلــك ودفــع بأنــه أوقــف الســيارة‬\n‫خــارج الورشــة لكونهــا مزدحمــة بعــد أن أغلــق أبوابهــا ‪ -‬مت تقديــر قيمــة‬\n‫الســيارة عــن طريــق رئيــس املعــارض‪ -‬املدعــى عليــه مفــرط يف حفــظ‬\n‫الســيارة التــي اســتلمها ‪ -‬قضــت احملكمــة بإلــزام املدعــى عليــه بتســليم‬\n‫قيمــة الســيارة إلــى املدعــي‪ -‬قنــع املدعــي باحلكــم وعــارض عليــه املدعى‬\n              ‫عليــه ‪ -‬قــررت محكمــة االســتئناف املوافقــة علــى احلكــم ‪.‬‬\n\n                                                                                         ‫‪220‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة بينبــع‬\n      ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫بينبع‪/‬املســاعد برقــم ‪ 33626232‬وتاريــخ ‪ 1433/10/28‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 331706916‬وتاريــخ ‪ 1433/09/16‬ه ـ بشــأن دعــوى‬\n      ‫ففــي يــوم الســبت املوافــق‪ 1433/11/13‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫‪ 08 : 00‬وفيهــا حضــر املدعــي‪ ..../‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫رقــم وحضــر حلضــوره املدعــى عليــه‪ ...../‬باكســتاني اجلنســية مبوجــب‬\n      ‫اإلقامــة رقــم ‪ ...‬ثــم ادعــى املدعــي قائــا ادعــي علــى احلاضــر معــي‬\n      ‫باملجلــس الشــرعي الــذي ســبق وأن ســلمته ســيارتي ‪ ...‬صنــع ‪ ...‬وذلــك‬\n      ‫بتاريــخ تقريبــا ‪1433/8/4‬ه ـ علــى أســاس ان يصلــح فيهــا أشــياء بســيطة‬\n      ‫وادخلتهــا ورشــته ثــم ســلمته املفتــاح واتفقنــا علــى ســعر اإلصــاح ألــف‬\n      ‫ومائتــن ريــال وقــال لــي تعــال بعــد ثالثــة أيــام وجتدهــا جاهــزة ولكننــي‬\n      ‫اســتعجلت وحضــرت إلــى الورشــة اليــوم التالــي إلــى الورشــة ولــم اجــد‬\n      ‫ســيارتي وســألته عنهــا وقــال أنــا ال اعلــم عنهــا شــيئا وقلــت ســوف أذهــب‬\n      ‫للشــرطة وقــال لــي أذهــب وبعــرض الدعــوى املرصــودة بعاليــة علــى‬\n      ‫املدعــى عليــه أجــاب علــى لســان مترجــم احملكمــة بقولــة فعــا اننــي‬\n      ‫اســتلمت ســيارة املدعــي ‪ ...‬وادخلهــا صاحبهــا الورشــة وســلمني املفتــاح‬\n      ‫واتفقــت معــه علــى اصالحهــا وقلــت لــه راجعنــي بعــد ثــاث أيــام ثــم‬\n      ‫أنصــرف وكانــت الورشــة مزدحمــة لــدي بالســيارات وأوقفــت الســيارة‬\n      ‫باخلــارج بعــد ربــع ســاعه يف برحــه أمــام الورشــة وأغلقــت أبوابهــا حوالــي‬\n      ‫الســاعة العاشــرة صباحــا ثــم عملــت بالورشــة حتــى الظهــر ورجعــت يف‬\n\n‫‪221‬‬\n\f‫املســاء حتــى الســاعة احلــادي عشــر ليــا ولكننــي لــم أتابــع وانظــر يف‬\n‫البرحــة هــل الســيارة مفقــودة أم ال وعندمــا حظــر صاحبهــا نظــرت إلــى‬\n‫البرحــة ولــم أجــد تلــك الســيارة وقــال هــذا دفعــي وعليــه أوقــع وبعــرض‬\n‫ذلــك علــى املدعــي أجــاب أننــي ســلمت الســيارة وأدخلتهــا إلــى الورشــة‬\n‫بنفســي وهــو الــذي أخرجهــا مــن احلــرز ثــم ســالت املدعــي متــى اشــتريت‬\n‫الســيارة قــال أننــي شــريتها قبــل ثالثــة اشــهر مــن معــرض ‪ ...‬ثــم طلبــت‬\n‫منــه اســتمارة الســيارة وســند البيــع وأســتعد بإحضارهــا يف اجللســة‬\n‫القادمــة ‪ ،‬ويف يــوم األحــد املوافــق‪ 1434/01/04‬ه ـ افتتحــت اجللســة‬\n‫الســاعة ‪ 8.30‬وفيهــا حضــر املدعــي وحضــر حلضــوره املدعــى عليــه ثــم‬\n‫أبــرز لنــا أصــل اســتمارة الســيارة ومكتــوب فيهــا املالــك ورقــم هويتــه‬\n‫ورقــم اللوحــة نــوع الســيارة ‪ ...‬وزن املركبــة ‪ ...‬اللــون ‪ ...‬نقــل خــاص‬\n‫ســنة الصنــع ‪ ...‬كذلــك أبــرز ســند الشــراء مــن معــرض ‪ ...‬والــذي جــاء‬\n‫فيــه قولــة اســتلمت مــن الســيد‪ ...‬مبلــغ وقــدرة ‪ 130.000‬الــف ريــال قيمــة‬\n‫‪ ...‬موديــل ‪ ...‬وذلــك بتاريــخ ‪1433/2/8‬ه ـ وبالرجــوع إلــى ملــف القضيــة‬\n‫وجــدت أن املدعــي تقــدم إلــى مركز شــرطة البلد بتاريــخ ‪1433/8/4‬هـ‬\n‫مبلغ ـ ًا عــن تعــرض ســيارته للســرقة حيــث كانــت يف إحــدى الــورش‬\n‫ويتهــم العامــل بســرقتها وجــرى التحقيــق معــه املدعــى عليــه ولــم يتوصــل‬\n‫التحقيــق إلــى نتائــج إلــى أن العامــل ذكــر بــأن مفتــاح الســيارة معــه وال‬\n‫يعلــم كيــف ســرقت ومت حتريــز املفتــاح بقســم الشــرطة ومت مخاطبــة‬\n‫صاحــب املعــرض مــن قبــل الشــرطة وذكــر أن الســيارة ال يوجــد عليهــا‬\n‫اقســاط بــل هــي بطاقــة جمركيــة ومت التعميــم عن تلك الســيارة مبوجب‬\n‫خطــاب مديــر شــرطة البلــد برقــم ‪ 3845‬يف ‪1433/8/5‬ه ـ وكتــب مدير‬\n‫شــرطة البلــد خطاب ـ ًا كذلــك إلــى قســم التحريــات والبحــث اجلنائــي‬\n\n\n                                                                                    ‫‪222‬‬\n\f      ‫برقــم ‪ 4150‬يف ‪1433/8/25‬ه ـ بالتنســيق مــع أصحــاب محالت املفاتيح‬\n      ‫وســؤالهم ملــن عملــوا مفاتيــح مشــابهه ملفاتيــح تلــك الســيارة حيــث أن‬\n      ‫الســيارة املســروقة حديثــة املوديــل ويســتبعد ســرقتها بالطــرق البدائيــة‬\n      ‫ثــم اقتضــت مصلحــه الدعــوى الكتابــة ملعــارض الســيارات لتقديــر ثمــن‬\n      ‫تلــك الســيارة ويف يــوم الســبت املوافــق‪ 1434/02/16‬ه ـ افتتحــت اجللســة‬\n      ‫الســاعة ‪ 08 : 30‬وفيهــا حضــر املدعــي وحضــر حلضــوره املدعــى عليــه‬\n      ‫ثــم وردنــا خطــاب مديــر الشــرطة رقم ‪275‬يف ‪1434/1/24‬ه ـ واملرفق به‬\n      ‫تقديــر قيمــة الســيارة مــن قبــل رئيــس معــارض الســيارات والــذي قدرهــا‬\n      ‫مببلــغ وقــدره مائــة وعشــرون الــف ريــال وبنــاء علــى دعــوى املدعــي الــذي‬\n      ‫ذكــر فيهــا بانــه ســلم الســيارة للمدعــى عليــه وادخلهــا الورشــة يف‬\n      ‫الســاعة احلاديــة عشــر ظهــرا ثــم اخرجهــا املدعــى عليــه واقفهــا بالبرحــة‬\n      ‫الن الورشــة مملــوءة بالســيارات ولــم يتابــع وضعهــا ولــم يدخلهــا يف املســاء‬\n      ‫يف الورشــة وعندمــا حضــر صاحبهــا يف اليــوم التالــي ســال املدعــى عليــه‬\n      ‫عنهــا وقــال وضعتهــا يف البرحــة ولــم يجدهــا بالبرحــة وفقــدت الســيارة‬\n      ‫ومت التعميــم عنهــا ولكــن لــم يعثــر عليهــا وقــد قــدرت مــن قبــل رئيــس‬\n      ‫املعــارض مببلــغ وقــدره مائــة وعشــرون الــف ريــال واملدعــى عليــه مفــرط‬\n      ‫بإخراجهــا للبرحــة ولــم يســأل عنهــا اال بعــد عــن حضــر صاحبهــا يف‬\n      ‫اليــوم التالــي لــذا حكمــت علــى املدعــى عليــه ‪ ...‬بــان يدفــع للمدعــي‬\n      ‫ثمــن تلــك الســيارة وقــدره مائــة وعشــرون الــف ريــال وبعــرض احلكــم‬\n      ‫علــى املدعــي قــال اننــي قانــع باحلكــم امــا املدعــى عليــه قــال اننــي غيــر‬\n      ‫قانــع واعطــي صــورة مــن احلكــم وافهــم علــى لســان املترجــم بــان مــدة‬\n      ‫االعتــراض ثالثــون يومــا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                          ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/02/16‬ه ـ‬\n\n\n‫‪223‬‬\n\f‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n‫أنــا القاضــي يف احملكمــة العامــة بينبــع وبنــاء علــى املعاملــة احملالــة لنــا‬\n‫مــن فضيلــة رئيــس احملكمــة العامــة بينبــع املســاعد برقــم ‪33626232‬‬\n‫وتاريــخ ‪ 1433/10/28‬ه ـ املقيــدة باحملكمــة برقــم ‪331706916‬‬\n‫وتاريــخ ‪ 1433/09/16‬ه ـ ففــي يــوم اخلميــس املوافــق‪ 1434/11/06‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪10.00‬وفيهــا حضــر املدعــي وحضــر حلضــوره‬\n‫املدعــى عليــه ثــم أعيــدت لنــا املعاملــة مبوجــب خطــاب فضيلــة رئيــس‬\n‫محكمــة االســتئناف ملنطقــة مكــة املكرمــة رقــم ‪331913856‬‬\n‫يف ‪1434/06/05‬ه ـ واملرفــق بــه قــرار املالحظــة رقــم ‪ 34226318‬يف‬\n‫‪1434/05/28‬ه ـ والــذي جــاء فيــه قوله وبدراســة الصــك وصورة ضبطه‬\n‫تقــرر إعادتهــا لفضيلــة حاكمهــا ملالحظــة مــا يلــي ‪ -1 :‬لالطــاع علــى‬\n‫الالئحــة االعتراضيــة املرفقــة والشــرح عليهــا مبــا يظهــر لــه ومعــاودة‬\n‫متابعــة البحــث والتحــري عــن الســيارة محــل الدعــوى والتعقيــب علــى‬\n‫البالغات التي اتخذتها اجلهات املختصة وماذا مت بصددها ‪ -2‬الدعوى‬\n‫غيــر محــررة وال بــد مــن حتريرهــا قبــل عرضهــا علــى املدعــى عليــه ‪-3‬‬\n‫لــم يعمــل املــادة ‪ 1/181‬مــن نظــام املرافعــات الشــرعية ولوائــح التنفيذيــة‬\n‫واهلل املوفــق قاضــي اســتئناف قاضــي اســتئناف رئيــس الدائــرة وبعــرض‬\n‫ا أدعــي علــى احلاضــر معــي باملجلــس‬           ‫ذلــك علــى املدعــي أجــاب قائ ـ ً‬\n‫الشــرعي الــذي ســبق وان ســلمته ســيارتي ‪ ...‬صنــع … ورقمهــا (‪)....‬‬\n‫وذلــك بتاريــخ ‪1433/8/4‬ه ـ علــى أســاس ان يصلــح فيهــا أشــياء بســيطة‬\n‫وادخلتهــا ورشــته ثــم ســلمته املفتــاح واتفقنــا علــى ســعر اإلصــاح وقــال‬\n‫لــي تعــال بعــد ثالثــة أيــام وجتدهــا جاهــزة ولكننــي اســتعجلت وحضرت‬\n‫إلــى الورشــة يف اليــوم الثانــي ولــم اجــد ســيارتي وســألته عنهــا وقــال إننــي‬\n\n\n                                                                                        ‫‪224‬‬\n\f      ‫حركتهــا ووضعتهــا يف البرحــة لــذا أطلــب أن يدفــع لــي ثمــن ســيارتي ‪...‬‬\n      ‫وقــدرة مائــة وثالثــون ألــف ريــال وبعــرض الدعــوى املرصــودة بعاليــة علــى‬\n      ‫ا نعــم اســتلمت ســيارة املدعــي املوصوفــة بعاليــة‬    ‫املدعــى عليــه اجــاب قائـ ً‬\n      ‫بعــد ان ادخلهــا إلــى ورشــتي واســتلمت مفتاحهــا وبعــد عشــرين دقيقــة‬\n      ‫تقريب ـ ًا وضعتهــا أمــام الورشــة مــع مجموعــه مــن الســيارات يف البرحــة‬\n      ‫ولــم أنتبــه أنهــا غيــر موجــودة إال بعــد حضــور صاحبهــا يف اليــوم الثانــي‬\n      ‫نظــرت إليهــا ولــم اجدهــا وســلمت املفتــاح إلى الشــرطة ثم ســألت املدعي‬\n      ‫هــل وجــدت الســيارة او وجــدت عنهــا خبــر مــن قريــب أو مــن بعيــد فقــال‬\n      ‫لــم اجــد عنهــا خبــر ولــم أشــاهدها وطيلــة املــدة وانــا أســأل عنهــا فقــال‬\n      ‫واهلل العظيــم إنــي ال أعلــم عنهــا وانهــا مصيبــة وقعــت علــي وليســت حيلــة‬\n      ‫وال خديعــة وإنــي ال أعلــم عــن تلــك الســيارة شــيء ثــم جــرى مخاطبــة‬\n      ‫الشــرطة مبوجــب خطابنــا رقــم ‪ 341458073‬يف ‪1434/6/17‬ه ـ‬\n      ‫بالبحــث عــن تلــك الســيارة وهــل وجــدوا بالغ ـ ًا عنهــا أم مــاذا فأفادونــا‬\n      ‫مبوجــب خطابهــم رقــم ‪ 22/3285/13/3‬يف ‪1434/8/17‬ه ـ بأنــه مت‬\n      ‫التعميــم عــن تلــك الســيارة برقــم ‪ 3845‬يف ‪1433/8/15‬ه ـ ولــم يتــم‬\n      ‫العثــور علــى الســيارة املذكــورة حتــى تاريخــه حتــت توقيــع مديــر شــرطة‬\n      ‫البلــد املقــدم ثــم جــرى منــي االطــاع علــى الالئحــة حســب املــادة ‪181‬‬\n      ‫مــن نظــام املرافعــات ولــم اجــد فيهــا شــيئ ًا لــذا لــم يطــرا لــدي مــا يوجــب‬\n      ‫تغييــر حكمــي الســابق وقــال املدعــي إننــي قانــع باحلكــم وقــال املدعــى‬\n      ‫عليــه إننــي غيــر قانــع والئحتــي مرفقــه يف املعاملــة لــذا جــرى إحلــاق ذلــك‬\n      ‫بالصــك وبعثــة إلــى محكمــة االســتئناف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/11/06‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n\n\n‫‪225‬‬\n\f‫أنــا القاضــي يف احملكمــة العامــة بينبــع والقائــم بعمــل فضيلــة الشــيخ‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بينبــع املســاعد برقــم ‪ 33626232‬وتاريــخ ‪ 1433/10/28‬ه ـ املقيــدة‬\n‫باحملكمة برقم ‪ 331706916‬وتاريخ ‪ 1433/09/16‬هـ ففي يوم األحد‬\n‫املوافــق‪ 1434/12/29‬ه ـ افتتحــت اجللســة الســاعة وفيها وردتنــا املعاملة‬\n‫مــن محكمــة االســتئناف برقــم ‪ 331913856‬يف ‪1434/12/17‬ه ـ‬\n‫والصــادر فيــه القــرار رقــم ‪ 34373689‬يف ‪1434/11/27‬ه ـ وفيــه نحــن‬\n‫قضــاة االســتئناف بالدائــرة احلقوقيــة اخلامســة يف محكمــة االســتئناف‬\n‫مبنطقــة مكــة املكرمــة جــرى منــا نحــن االطــاع علــى هــذا احلكــم‬\n‫الصــادر مــن فضيلــة الشــيخ القاضــي باحملكمــة العامــة بينبــع املســجل‬\n‫بعــدد ‪ 3437753‬وتاريــخ ‪1434/12/16‬ه ـ املتضمــن دعــوى ‪ ،‬احملكــوم‬\n‫فيــه مبــا دون باطــن الصــك وبدراســة احلكــم وصــورة ضبطــه والئحتــه‬\n‫االعتراضيــة تقــرر املوافقــة علــى احلكــم بعــد اإلجــراء األخيــر ‪ ،‬قاضــي‬\n‫اســتئناف قاضــي اســتئناف رئيــس الدائــرة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/1/1‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                  ‫‪226‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":220,"source_page_end":226,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"12f44643b8f68edb1bca3ed75b6d9acdfccf2b1c71014cb12f8d02d8f5313bcf","normalized_text_hash":"54c4ce99fabd301e19d175b5c9ee74552c6f77348b4ae03afa8e9208c31c6b30","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p220-3437753"},{"id":"a2895d1c-7f7c-583f-b02a-f68e9083e384","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبة برد مسروق -سرقة مبلغ مالي من سيارة -عجز عن إقامة البينة -احلكم برد الدعوى -استحقاق املدعي ليمن املدعى عليه على نفي الدعوى متى طلبها .","document_number":"33475191","case_number":"33666747","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/21","year":"1434","subject":"مطالبة برد مسروق -سرقة مبلغ مالي من سيارة -عجز عن إقامة البينة -احلكم برد الدعوى -استحقاق املدعي ليمن املدعى عليه على نفي الدعوى متى طلبها .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1433/11/21 :‬هـ‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪33475191 :‬‬\n                           ‫َر ْق ُم الدعوى‪33666747:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                    ‫‪ 3428329‬تاريخه‪1434/2/3:‬هـ‬\n\n\n       ‫مطالبــة بــرد مســروق ‪ -‬ســرقة مبلــغ مالــي مــن ســيارة ‪ -‬عجــز عــن إقامــة‬\n       ‫البينــة ‪ -‬احلكــم بــرد الدعــوى ‪ -‬اســتحقاق املدعــي ليمــن املدعــى عليــه‬\n                                               ‫علــى نفــي الدعــوى متــى طلبهــا ‪.‬‬\n\n\n\n\n       ‫قــول النبــي صلــى اهلل عليــه وســلم‪( :‬البينــة علــى املدعــي واليمــن علــى‬\n                                                                        ‫مــن أنكــر) ‪.‬‬\n\n\n\n\n       ‫ادعــى املدعــي علــى احلاضــر معــه بأنــه قــام بكســر زجــاج ســيارته‬\n       ‫وســرقة مبلــغ مالــي منهــا‪ ،‬وطلــب تأديبــه وإلزامــه بإعــادة املبلــغ املســروق‬\n       ‫إليــه ‪ -‬أنكــر املدعــى عليــه مــا جــاء يف دعــوى املدعــي ‪ -‬املدعــي لــم‬\n       ‫يقــدم بينــة تثبــت دعــواه ولــم يقبــل ميــن املدعــى عليــه علــى نفيهــا ‪ -‬قضت‬\n       ‫احملكمــة بصــرف النظــر عــن الدعــوى وأخلــت ســبيل املدعــى عليــه منها‬\n       ‫وأفهمــت املدعــي أن لــه ميــن املدعــى عليــه علــى نفــي دعــواه متــى مــا طلــب‬\n       ‫ذلــك ‪ -‬قنــع املدعــى عليــه باحلكــم وعــارض املدعــي‪ -‬قــررت محكمــة‬\n                                                  ‫االســتئناف املصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫‪227‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بحائــل وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بحائــل‪ /‬املكلــف برقــم ‪ 33666747‬وتاريــخ ‪ 1433/11/21‬ه ـ‬         ‫ّ‬\n‫املقيــدة باحملكمــة برقــم‪ 332048342‬وتاريــخ ‪1433/11/17‬ه ـ ففــي‬\n‫يــوم الثالثــاء املوافق‪1433/12/21‬ه ـ افتتحــت اجللســة الســاعة الثانيــة‬\n‫عشــرة وفيهــا حضــر ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬‬\n‫وادعــى علــى احلاضــر معــه ســعودي بالســجل املدنــي رقــم ‪ ...‬واملضــاف يف‬\n‫ســجل أســرة والــده واملرفــق باملعاملــة واملعــرف بــه مــن قبــل املدعــي ومــن‬\n‫أخيــه احلاضــر معــه ســعودي بالســجل املدنــي رقــم ‪ ...‬قائــا يف حتريــر‬\n‫دعــواه إن املدعــى عليــه قــد قــام بتاريــخ ‪1433/6/4‬ه ـ بكســر زجاجــة‬\n‫ســيارتي وهــي مــن نــوع ‪...‬موديــل ‪ .....‬وســرق منهــا مبلغ ـ ًا قــدره خمســة‬\n‫آالف ريــال أطلــب تأديبــه وإلزامــه بدفــع املبلــغ املســروق وقــدره خمســة‬\n‫آالف ريــال هــذه دعــواي هكــذا ادعــى املدعــي وبعــرض ذلــك علــى‬\n‫ا مــا ذكــره املدعــي ضــدي كلــه غيــر صحيــح‬       ‫املدعــى عليــه أجــاب قائـ ً‬\n‫وال أعلــم عــن هــذه الواقعــة شــيئا وليــس لــي أي عالقــة بكســر ســيارة‬\n‫املدعــي أو الســرقة منهــا وبعــرض ذلــك علــى املدعــي قــال الصحيــح مــا‬\n‫ذكرتــه يف دعــواي وبســؤاله عــن البينــة قــال ليــس عنــدي بينــة وجــرى‬\n‫ســؤاله هــل شــاهدت املدعــى عليــه وهــو يســرق فقــال ال فجــرى ســؤال‬\n‫املدعــي إن كان يرغــب ميــن املدعــى عليــه علــى نفــي دعــواه فقــال ال‬\n‫أقبــل ميينــه ثــم قــال املدعــى عليــه ال مانــع عنــدي مــن أداء اليمــن فجــرى‬\n‫منــي االطــاع علــى املعاملــة وبهــا خطــاب ســعادة مديــر دار املالحظــة‬\n\n                                                                                      ‫‪228‬‬\n\f      ‫االجتماعيــة بحائــل واملرفــق باملعاملــة واملتضمــن أنــه مت التحقيــق‬\n      ‫مــع املذكــور وأنكــر قيامــه بالســرقة كمــا مت مضاهــاة بصماتــه‬\n      ‫للقضايــا املقيــدة ضــد مجهــول ووردنــا كتــاب مديــر األدلــة اجلنائيــة رقــم‬\n      ‫‪ 5605/8/1/29‬يف ‪1433/10/28‬ه ـ واملتضمــن عــدم االســتدالل علــى‬\n      ‫أي بصمــات تنطبــق علــى بصمــات املذكــور وهــذا مرفــق علــى اللفــة‬\n      ‫رقــم (‪ )25‬باملعاملــة وبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ولعــدم‬\n      ‫مصادقــة املدعــى عليــه علــى الدعــوى وال بينــة للمدعــي ورفــض املدعــي‬\n      ‫طلــب ميــن املدعــى عليــه ولعمــوم قــول النبــي صلى اهلل عليه وســلم‪ :‬البينة‬\n      ‫علــى املدعــي واليمــن علــى مــن أنكــر فقــد حكمــت بصــرف النظــر‬\n      ‫عــن طلــب املدعــي تأديــب املدعــى عليــه وإلزامــه بدفــع املبلــغ املســروق‬\n      ‫وأخليــت ســبيل املدعــى عليــه وأفهمــت املدعــي أن لــه ميــن املدعــى عليــه‬\n      ‫علــى نفــي دعــواه متــى مــا طلــب ذلــك هــذا مــا ظهــر لــي وبــه حكمــت‬\n      ‫واهلل أعلــم وأحكــم وبعــرض احلكــم علــى الطرفــن لــم يقنــع املدعــي‬\n      ‫وطلــب رفعــه حملكمــة االســتئناف بــدون الئحــة اعتراضيــة وبعــرض‬\n      ‫احلكــم علــى املدعــى عليــه قنــع بــه وبــاهلل التوفيــق وبهــذا أقفلــت اجللســة‬\n      ‫يف متــام الســاعة الثانيــة عشــرة والنصــف وصلــى اهلل علــى نبينــا محمــد‬\n                              ‫وعلــى آلــه وصحبــه وســلم حــرر يف ‪1433/12/21‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة‬\n      ‫األولــى لتدقيــق القضايــا احلقوقيــة مبحكمــة االســتئناف مبنطقــة‬\n      ‫حائــل علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة‬\n      ‫بحائــل املكلــف برقــم ‪ 332048342‬وتاريخ‪1434/1/27‬ه ـ واملقيــدة‬\n      ‫لدينــا برقــم ‪ 34250118‬يف ‪1434/1/28‬ه ـ املرفــق بهــا الصــك رقــم‬\n      ‫‪ 33475191‬يف ‪1433/12/21‬ه ـ الصــادر مــن فضيلــة القاضــي ‪......‬‬\n\n\n‫‪229‬‬\n\f‫اخلــاص بدعــوى ‪ .......‬ضــد ‪ .......‬بشــأن اتهــام بســرقة (حــق خــاص)‬\n‫علــى الصفــة املوضحــة يف الصــك وقــد تضمــن الصــك حكــم فضيلتــه‬\n‫بصــرف النظــر عــن طلــب املدعــي تأديــب املدعــى عليــه وإلزامــه بدفــع‬\n‫املبلــغ املســروق وإخــاء ســبيل املدعــى عليــه مــن هــذه الدعــوى وأفهمــت‬\n‫املدعــي أن لــه ميــن املدعــى عليــه علــى نفــي دعــواه متــى مــا طلــب ذلــك‬\n‫وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة لــم يظهــر مــا يوجــب‬\n‫املالحظــة علــى مــا حكــم بــه فضيلتــه واهلل املوفــق وصلــى اهلل علــى‬\n                                   ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                    ‫‪230‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":227,"source_page_end":230,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"992db6f5386945301a1ef9768c27b477bd4e8ef3d37362b798d91364afe1f46e","normalized_text_hash":"4c01e70245f0f87eb20e06dff6999ce2a8c802dd42788c46e365f2f984daa83c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p227-33475191"},{"id":"ae07f93c-4591-5bc7-a83b-bbdefd1a7e1f","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مسروق -سرقة مواد إنشائية من مستودع -القبض على املتهم حال السرقة بدون مسروقات -بينة غير موصلة -اليمن على نفي الدعوى حق للمدعي وله عدم قبولها -احلكم برد دعوى .","document_number":"3420688","case_number":"33680256","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/24","year":"1434","subject":"رد مسروق -سرقة مواد إنشائية من مستودع -القبض على املتهم حال السرقة بدون مسروقات -بينة غير موصلة -اليمن على نفي الدعوى حق للمدعي وله عدم قبولها -احلكم برد دعوى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/1/24 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪3420688 :‬‬\n                         ‫َر ْق ُم الدعوى‪33680256:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 3450740‬تاريخه‪1434/2/3:‬هـ‬\n\n\n      ‫رد مســروق ‪ -‬ســرقة مــواد إنشــائية مــن مســتودع ‪ -‬القبــض علــى املتهــم‬\n      ‫حــال الســرقة بــدون مســروقات ‪ -‬بينــة غيــر موصلــة ‪ -‬اليمــن علــى نفــي‬\n                ‫الدعــوى حــق للمدعــي ولــه عــدم قبولهــا ‪ -‬احلكــم بــرد دعــوى ‪.‬‬\n\n\n\n\n      ‫قــول النبــي صلــى اهلل عليــه وســلم‪( :‬البينــة علــى املدعــي واليمــن علــى‬\n                                                                    ‫املدعــى عليــه) ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي بــأن املدعــى عليــه قــام بســرقة مــواد إنشــائية مــن مســتودع‬\n      ‫عائــد لــه؛ وطلــب إلزامــه بــرد املســروقات أو تســليمه قيمتهــا‪ -‬أنكــر‬\n      ‫املدعــى عليــه دعــوى املدعــي جتاهــه جملــة وتفصيــا‪ -‬املدعــي قــدم‬\n      ‫بينــات غيــر موصلــة ولــم يقبــل ميــن املدعــى عليــه علــى نفــي دعــواه‪ -‬مــن‬\n      ‫املقــرر شــرعا أن البينــة علــى املدعــي واليمــن علــى املدعــى عليــه‪ -‬قضت‬\n      ‫احملكمــة بعــدم اســتحقاق املدعــي ملــا يدعيــه وأخلــت ســبيل املدعــى‬\n      ‫عليــه منهــا وأفهمــت املدعــي بــأن لــه ميــن املدعــى عليــه متــى طلبهــا‪-‬‬\n      ‫قنــع املدعــى عليــه باحلكــم وعــارض عليــه املدعــي ‪ -‬قــررت محكمــة‬\n                                              ‫االســتئناف املوافقــة علــى احلكــم ‪.‬‬\n\n\n‫‪231‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامة مبكة‬\n‫املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة مبكــة املكرمــة برقــم ‪ 33680256‬وتاريــخ ‪1433/11/28‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 332014010‬وتاريــخ ‪ 1433/11/14‬ه ـ‬\n‫حضــر بالســجل املدنــي رقــم ‪ ...‬وادعــى علــى احلاضــر معــه الســجني‬\n‫بالســجل املدنــي رقــم ‪ ...‬يرافقــه اجلنــدي قائــا يف دعــواه عليــه لقــد قفــز‬\n‫املدعــى عليــه علــى مســتودعي الواقــع بــ‪ ........‬وســرق منــه مــا يلــي أوال‬\n‫مائــة وخمســة وثمانــن طفايــة حريــق مســتعمله وقيمتهــا اإلجمالية ســبعة‬\n‫وعشــرون ألفــا وســبعمائة وخمســون ريــال ثانيــا مائتــان وتســعون طفايــة‬\n‫حريــق جديــد وقيمتهــا اإلجماليــة ســبعة وثمانــون ألــف ريــال ثالثــا اثنــا‬\n‫عشــر مولــد كهربائــي مببلــغ إجمالــي ســبعة وعشــرين ألفــا وســتمائة‬\n‫ريــال رابعــا ثالثــون لفــة كيابــل كبيــره مببلــغ إجمالــي ســتة وثالثــن‬\n‫ألــف ريــال خامســا خمســة عشــر لفــة كيابــل صغيــر مببلــغ إجمالــي‬\n‫تســعة آالف ريــال سادســا مائتــان وعشــرة ملبــة فلورســنت مــع قواعدهــا‬\n‫مببلــغ إجمالــي خمســة آالف ومائتــان وخمســون ريــاال ســابعا ســبعة‬\n‫وأربعــون شــوال مــن أكيــاس النفايــات الكبيــرة مببلــغ ثالثــة آالف‬\n‫وتســعمائة وخمســة وتســعني ريــاال ومجمــوع ذلــك مبلــغ وقــدره مائــة‬\n‫وســتة وتســعون ألــف ريــال فأطلــب إلزامــه بــرد مــا ســرقه أو دفــع قيمتــه‬\n‫هــذه دعــواي وبســؤال املدعــى عليــه عــن دعــوى املدعــي أجــاب قائــا ال‬\n‫صحــة ملــا ذكــره فلــم أدخــل مســتودعه الواقــع بالشــرائع ولــم أســرق منــه‬\n‫شــيئا هــذه إجابتــي وبســؤال املدعــي هــل لديــه بينــة علــى دعــواه فقــال‬\n\n                                                                                     ‫‪232‬‬\n\f      ‫نعــم لــدي البينــة وأحضــر للشــهادة وأدائهــا بالســجل املدنــي رقــم وطلــب‬\n      ‫ســماع مــا لديــه مــن شــهادة وشــهد قائــا أشــهد إننــي رأيــت املدعــى عليــه‬\n      ‫هــذا احلاضــر ومعــه شــخص آخــر فــوق ســور مســتودع املدعــي املجــاور‬\n      ‫ملنزلنــا وقــد أبلغــت الشــرطة عنــه وملــا حضــرت الدوريــة قمــت مبســاعدة‬\n      ‫الدوريــة والقبــض عليــه عندمــا قفــز مــن فــوق الســور إلــى األرض وأمــا‬\n      ‫صاحبــه اآلخــر فقــد هــرب وقــد رأيــت أســفل الســور لفتــن مــن لفائــف‬\n      ‫أســاك الكهربــاء وال أعلــم مــن أخرجهــا ولــم يكــن بيــد املدعــى عليــه‬\n      ‫شــيء عنــد القبــض عليــه هــذا مــا لــدي وأشــهد بــه وبعــرض الشــاهد‬\n      ‫وشــهادته علــى املدعــى عليــه قــال الشــاهد ال أعرفــه وال أقــول بــه شــيئا‬\n      ‫وشــهادته بأنــه قبــض علــي صحيحــة ولكــن شــهادته أننــي كنــت فــوق‬\n      ‫الســور غيــر صحيحــة فأنــا لــم أكــن فــوق الســور أبــدا وإمنــا كنــت‬\n      ‫أســفل الســور وزميلــي الــذي كان معــي هــو الــذي دخــل املســتودع حيــث‬\n      ‫قفــز فــوق الســور لســرقة مــا بداخلــه وكنــت أنــا يف اخلــارج ولــم أشــاهده‬\n      ‫يخــرج شــيئا وقــد شــاهده الشــاهد وهــو فــوق الســور وملــا أراد القبــض‬\n      ‫علينــا هــرب وأنــا كنــت أســفل الســور وقبــض الشــاهد علــي هكــذا‬\n      ‫قــرر وبســؤال املدعــي هــل لديــه زيــادة بينــة فقــال ال وعليــه فقــد أفهمتــه‬\n      ‫بــأن لــه ميــن املدعــى عليــه علــى نفــي دعــواه فقــال إننــي ال أريــد ميينــه وال‬\n      ‫أقبلهــا هكــذا قــرر ثــم جــرى الرجــوع إلــى أوراق املعاملــة فلــم أجــد فيهــا‬\n      ‫إقــرارا للمدعــى عليــه بالســرقة أه ـ فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n      ‫واإلجابــة وألن املدعــى عليــه أنكــر ســرقة مــا يدعيــه املدعــي ولعمــوم‬\n      ‫قولــه صلــى اهلل عليــه وســلم البينــة علــى املدعــي واليمــن علــى من أنكر‬\n      ‫وألن البينــة التــي أحضرهــا املدعــي ليســت موصلــة حيــث شــهد الشــاهد‬\n      ‫أنــه رأى املدعــى عليــه فــوق الســور ثــم قفــز أســفله ومت القبــض عليــه ولــم‬\n\n\n‫‪233‬‬\n\f‫يكــن معــي شــيء وألن املدعــي قــرر أنــه ال يقبــل بيمــن املدعــى عليــه‬\n‫علــى نفــي دعــواه لذلــك كلــه فقــد حكمــت بعــدم اســتحقاق املدعــى‬\n‫عليــه ملــا يدعيــه وأخليــت ســبيل املدعــى عليــه مــن هــذه الدعــوى وأفهمتــه‬\n‫بــأن لــه ميــن املدعــى عليــه علــى نفــي دعــواه متــى طلبهــا وبعــرض احلكــم‬\n‫علــى الطرفــن قــرر املدعــى عليــه القناعــة وقــرر املدعــي عــدم القناعــة‬\n‫وطلــب رفعــه حملكمــة االســتئناف بعــد تقــدمي الئحــة اعتراضيــة عليــه‬\n‫فأفهمتــه مبراجعــة احملكمــة خــال عشــرة أيــام الســتالم الصــك وتقدمي‬\n‫الالئحــة االعتراضيــة خــال ثالثــن يومــا مــدة االعتــراض فــإذا تأخــر‬\n‫ســقط حقــه يف طلــب االســتئناف واكتســب احلكــم القطعيــة وبــاهلل‬\n‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر‬\n                                                          ‫يف ‪1434/1/21‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ثــم عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫بشــرح فضيلــة الرئيــس برقــم ‪ 34489001‬يف ‪1434/4/23‬ه ـ علــى‬\n‫خطــاب رئيــس محكمــة االســتئناف مبنطقــة مكــة املكرمــة املكلــف‬\n‫برقــم ‪ 34489001‬يف ‪1434/3/18‬ه ـ برفقهــا قــرار التصديــق مبوجــب‬\n‫القــرار رقــم ‪ 3450740‬يف ‪1434/2/3‬ه وهــذا نصــه ‪ -:‬احلمــد هلل ‪،‬‬\n‫والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ -:‬فقــد جــرى منــا نحــن‬\n‫قضــاة الدائــرة اجلزائيــة الثالثــة مبحكمــة االســتئناف مبنطقــة مكــة‬\n‫املكرمــة االطــاع علــى املعاملــة الــواردة الينــا شــفع خطــاب فضيلــة‬\n‫رئيــس احملكمــة العامــة مبكــة املكرمــة رقــم ‪ 332014010‬وتاريــخ‬\n‫‪1434/2/24‬ه ـ املشــتملة علــى الصــك الصــادر مــن فضيلــة الشــيخ‬\n‫القاضــي باحملكمــة العامــة مبكــة املكرمــة املــؤرخ يف ‪1434/1/24‬هـ‬\n‫واملســجل بعــدد ‪ 3420688‬املتضمــن دعــوى ضــد الســجني املتهم بســرقة‬\n\n\n                                                                                     ‫‪234‬‬\n\f      ‫كيابــل احملكــوم فيــه مبــا دون باطــن القرار ‪ ،‬وبدراســة الصك وصورة‬\n      ‫ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة علــى احلكــم ‪ .‬وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪،‬‬\n      ‫قاضــي اســتئناف ختــم وتوقيــع د‪ /‬قاضــي اســتئناف ختــم وتوقيــع رئيــس‬\n      ‫الدائــرة ختــم وتوقيــع ‪ ،‬لــذا جــرى مبوجبــه ‪.‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/5/5‬ه ـ ‪.‬‬\n\n\n\n\n‫‪235‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":231,"source_page_end":235,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b50ee4ca6b1035afee0fd1efd531d5a27ccad9e0d58cdf24c9825bada7c269b0","normalized_text_hash":"a9ad90dce9f6ffefa538086b940115b3ff66b6d6030bf5034041bee38e722cb0","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p231-3420688"},{"id":"a52cd1bb-9e95-50a3-af07-2abfe484c56c","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مسروق -سرقة سيارة وإتالفها -طلب املدعي اليمن النافية من قبل املدعى عليه -القضاء بالنكول عن اليمن -إلزام املدعى عليه بقيمة السيارة .","document_number":"3423451","case_number":"33688344","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املوافقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/26","year":"1434","subject":"رد مسروق -سرقة سيارة وإتالفها -طلب املدعي اليمن النافية من قبل املدعى عليه -القضاء بالنكول عن اليمن -إلزام املدعى عليه بقيمة السيارة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/1/26 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3423451 :‬‬\n                   ‫َر ْق ُم الدعوى‪33688344 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n             ‫‪ 3451302‬تاريخه‪1434/3/1:‬هـ‬\n\n\n‫رد مســروق ‪ -‬ســرقة ســيارة وإتالفهــا ‪ -‬طلــب املدعــي اليمــن النافيــة مــن‬\n‫قبــل املدعــى عليــه ‪ -‬القضــاء بالنكــول عــن اليمــن ‪ -‬إلــزام املدعــى عليــه‬\n                                                             ‫بقيمــة الســيارة ‪.‬‬\n\n\n\n\n                                       ‫اليمني تشرع يف جانب أقوى املتداعيني ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي علــى احلاضــر معــه بأنــه قــام بســرقة ســيارته ثــم عثــر عليها‬\n‫محترقــة بشــكل كامــل بعــد أخــذ بعــض أجزائهــا ‪ ،‬وطلــب إلزامــه‬\n‫بإعــادة قيمــة تلــك الســيارة إليــه ‪ -‬أنكــر املدعــى عليــه مــا جــاء يف دعــوى‬\n‫املدعــي‪ -‬املدعــي لــم يقــدم بينــة موصلــة وطلــب ميــن املدعــى عليــه علــى‬\n‫نفــي دعــواه فنــكل عــن أدائهــا بعــد إنــذاره ‪ -‬أدى املدعــي اليمــن طبــق‬\n‫مــا طلــب منــه‪ -‬قضــت احملكمــة علــى املدعــى عليــه بإلزامــه بتســليم‬\n‫قيمــة الســيارة إلــى املدعــي‪ -‬عــارض املدعــى عليــه علــى احلكــم‪ -‬قــررت‬\n                               ‫محكمــة االســتئناف املوافقــة علــى احلكــم ‪.‬‬\n\n\n\n\n                                                                                       ‫‪236‬‬\n\f      ‫احلمد هلل وحده وبعد فلدي أنا ‪ ...‬القاضي يف احملكمة اجلزائية باملدينة‬\n      ‫املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة باملدينــة املنــورة برقــم ‪ 33688344‬وتاريــخ ‪ 1433/12/18‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 332178767‬وتاريــخ ‪ 1433/12/18‬ه ـ‬\n      ‫واملتعلقــة بدعــوى ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬ضــد‬\n      ‫‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬ففــي يــوم الثالثــاء‬\n      ‫املوافــق‪ 1434/01/20‬ه ـ افتتحــت اجللســة الســاعة ‪ 10 : 45‬وفيهــا‬\n      ‫ا ‪ :‬أدعــي ضــد املدعــى عليــه حيــث‬    ‫حضــر الطرفــان فادعــى املدعــي قائـ ً‬\n      ‫إنــه بتاريــخ ‪1432/7/27‬ه ـ ســرقت ســيارتي مــن نــوع ‪ .......‬غمــارة موديــل‬\n      ‫‪ ......‬رقــم لوحتهــا (‪ )....‬مــن أمــام منزلــي فقمــت بتبليــغ اجلهــات األمنيــة‬\n      ‫بذلــك ‪ ،‬وبعــد البحــث والتحــري وجــدت ســيارتي مــن قبــل الشــرطة يف‬\n      ‫منطقــة جبليــة وهــي محترقــة بالكامــل ومتعرضــة للتشــليح علمـ ًا بأننــي‬\n      ‫اشــتريت الســيارة بتاريــخ ‪1430/2/27‬ه ـ مببلــغ ســبعة عشــر ألــف ريــال‬\n      ‫وتعــذر تقديــر أرش اجلنايــة عليهــا لكونهــا يف منطقــة نائيــة ويصعــب‬\n      ‫إحضارهــا ملعــارض الســيارات وحيــث أديــن املدعــى عليــه يف احلــق العــام‬\n      ‫بســرقة عــدة ســيارات وإحراقهــا ومــن ضمنهــا ســيارتي فأطلــب إلزامــه‬\n      ‫بتســليمي قيمــة ســيارتي التــي أتلفهــا وقدرهــا ســبعة عشــر ألــف ريــال‬\n      ‫حــا ًال هــذه دعــواي‪ ،‬وبســؤال املدعــى عليــه عــن دعــوى املدعــي ضــده‬\n      ‫أجــاب قائ ـاً‪ :‬مــا ذكــره املدعــي ضــدي غيــر صحيــح حيــث لــم أســرق‬\n      ‫ســيارته املذكــورة يف دعــواه ولــم أقــم بتشــليحها وال إحراقهــا وال أعلــم‬\n      ‫مــن قــام بذلــك هكــذا أجــاب ‪ ،‬فســألت املدعــي هــل لديــه بينــة علــى مــا‬\n\n‫‪237‬‬\n\f‫ادعــاه ونفــاه املدعــى عليــه فقــال ‪ :‬ليــس لــدي ســوى مــا يف أوراق املعاملــة‬\n‫هكــذا قــال ‪ ،‬فجــرى منــي دراســة أوراق املعاملــة فوجــدت مــن ضمنهــا‬\n‫بــاغ املدعــي املتضمــن نحــو مــا ورد يف دعــواه ‪ ،‬كمــا وجــدت القــرار‬\n‫الصــادر منــا برقــم ‪ 33156416‬يف ‪1433/3/27‬ه ـ املتضمــن عــدم ثبــوت‬\n‫إدانــة املدعــى عليــه بســرقة عــدد مــن الســيارات ومــن ضمنهــا ســيارة‬\n‫املدعــي ولكــن الشــبهة القويــة تتجــه ضــده بذلــك وحكــم مبجازاتــه‬\n‫لقــاء ذلــك بســجنه عشــر ســنوات وجلــده ألف ـ ًا ومائــة وخمس ـ ًا وعشــرين‬\n‫جلــدة وتغرميــه مبلــغ خمســة عشــر ألــف ريــال وصــدق احلكــم مــن‬\n‫محكمــة االســتئناف بقرارهــا رقــم ‪ 33360258‬يف ‪1433/7/29‬ه ـ ‪،‬‬\n‫وحيــث لــم أجــد يف أوراق املعاملــة مــا يديــن املدعــى عليــه مبــا جــاء يف‬\n‫دعــوى املدعــي ضــده ولكــون احلكــم املذكــور مضمونــه بعاليــة ومــا‬\n‫بنــي عليــه مــن قرائــن يعتبــر قرينــة قويــة تقــوي جانــب املدعــي وملــا قــرره‬\n‫العلمــاء مــن أن اليمــن تكــون يف جانــب أقــوى املتداعيــن فقــد أفهمــت‬\n‫املدعــي بأنــه تتجــه ضــده اليمــن املكملــة لبينتــه فرفــض أداء اليمــن‬\n‫لكونــه لــم يشــاهد املدعــى عليــه وهــو يقــوم بســرقة ســيارته وطلــب ميــن‬\n‫املدعــى عليــه علــى نفــي دعــواه وبعرضــه علــى املدعــى عليــه رفــض أداء‬\n‫اليمــن علــى نفــي دعــوى املدعــي ضــده فجــرى إنــذاره ثــاث مــرات بــأن‬\n‫عــدم أدائــه لليمــن يعــد نكــو ًال فأصــر علــى عــدم أداء اليمــن فأفهمــت‬\n‫املدعــي أنــه تتجــه ضــده اليمــن علــى أن قيمــة ســيارته ســبعة عشــر‬\n‫ألــف ريــال وقــت ســرقتها فاســتعد بــأداء اليمــن ثــم حلــف قائ ـاً‪ :‬واهلل‬\n‫العظيــم إن قيمــة ســيارتي وقــت ســرقتها ســبعة عشــر ألــف ريــال واهلل‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبعد‬\n                                                  ‫العظيــم هكــذا حلــف‪ ،‬فبنـ ً‬\n‫االطــاع علــى أوراق املعاملــة وحيــث أنكــر املدعــى عليــه مــا جــاء يف‬\n\n\n                                                                                        ‫‪238‬‬\n\f      ‫دعــوى املدعــي ضــده وقــرر املدعــي أنــه ال بينــة لــه علــى دعــواه ســوى مــا‬\n      ‫يف أوراق املعاملــة‪ ،‬وحيــث لــم أجــد يف أوراق املعاملــة مــا يديــن املدعــى‬\n      ‫عليــه مبــا جــاء يف دعــوى املدعــي ضــده إال أن القــرار الصــادر منــا يوجــه‬\n      ‫الشــبهة القويــة للمدعــى عليــه بســرقة ســيارة املدعــي وطلــب مــن املدعــي‬\n      ‫أداء اليمــن املكملــة لبينتــه فرفــض ذلــك وطلــب ميــن املدعــى عليــه علــى‬\n      ‫نفــي دعــواه وحيــث رفــض املدعــى عليــه أداء اليمــن علــى نفــي دعــوى‬\n      ‫املدعــي ضــده وحلــف املدعــي علــى أن قيمــة ســيارته ســبعة عشــر ألــف‬\n      ‫ريــال فقــد ثبــت لــدي أن بذمــة املدعــى عليــه للمدعــي مبلــغ ســبعة عشــر‬\n      ‫ألــف ريــال وألزمتــه بتســليمها إيــاه حــا ًال بــدون مماطلــة أو تأخيــر وبذلــك‬\n      ‫حكمــت وبعرضــه علــى املدعــى عليــه قــرر عــدم قناعتــه بــه وطلــب رفعــه‬\n      ‫حملكمــة االســتئناف بــدون الئحــة اعتراضيــة وعليــه جــرى التوقيــع‬\n      ‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‬\n                                                                        ‫‪1434/01/20‬ه ـ‬\n      ‫احلمــد هلل والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ ،‬فقــد جــرى‬\n      ‫منــا نحــن قضــاة الدائــرة اجلزائيــة الســابعة مبحكمــة االســتئناف يف‬\n      ‫منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n      ‫رئيــس احملكمــة اجلزائيــة باملدينــة املنــورة رقــم ‪ 332178767‬وتاريــخ‬\n      ‫‪1434/2/12‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‪.../‬‬\n      ‫القاضــي باحملكمــة اجلزائيــة باملدينــة املنــورة رقــم ‪ 3423451‬وتاريــخ‬\n      ‫‪1434/1/26‬ه ـ احملكــوم فيــه مبــا دون بباطــن الصــك املتضمــن‬\n      ‫دعوى‪..........‬ســعودي اجلنســية ضد‪ ........... /‬ســعودي اجلنســية يف قضية‬\n      ‫حقوقيــة وبدراســة الصــك وصــورة ضبطــه تقــررت املوافقــة علــى احلكم‬\n      ‫‪ ،‬واهلل املوفــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n‫‪239‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":236,"source_page_end":239,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"389e66484e49d215531edbf865d873a79d16f3eb16850d2f9a53a9fe7706d6a1","normalized_text_hash":"231ef72d238c916329ce9a924f7d0960d2b1ed8cd05a52baf2c453f1034b113e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p236-3423451"},{"id":"4282c92f-30bc-5f52-9454-76e4636cb50f","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مسروق -سرقة أجهزة إلكترونية من متجر -إقرار -قبول قول املدعي مع ميينه -التثبت من صيغة اليمن ألهميتها -اليمن تشرع يف جانب أقوى املتداعين -ثبوت الدعوى -اإللزام بالسداد .","document_number":"34236377","case_number":"34122122","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باجلفر باألحساء بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/11","year":"1434","subject":"رد مسروق -سرقة أجهزة إلكترونية من متجر -إقرار -قبول قول املدعي مع ميينه -التثبت من صيغة اليمن ألهميتها -اليمن تشرع يف جانب أقوى املتداعين -ثبوت الدعوى -اإللزام بالسداد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/6/11 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34236377 :‬‬\n                   ‫َر ْق ُم الدعوى‪34122122 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 35117553‬تاريخه‪1435/1/16:‬هـ‬\n\n\n‫رد مســروق ‪ -‬ســرقة أجهــزة إلكترونيــة مــن متجــر ‪ -‬إقــرار ‪ -‬قبــول قــول‬\n‫املدعــي مــع ميينــه ‪ -‬التثبــت مــن صيغــة اليمــن ألهميتهــا ‪ -‬اليمــن‬\n‫تشــرع يف جانــب أقــوى املتداعيــن ‪ -‬ثبــوت الدعــوى ‪ -‬اإللــزام بالســداد ‪.‬‬\n\n\n\n\n                                       ‫اليمني تشرع يف جانب أقوى املتداعيني ‪.‬‬\n\n\n\n\n‫ادعــى وكيــل املدعــي بــأن املدعــى عليــه قــام بســرقة أجهــزة إلكترونيــة‬\n‫مــن متجــر مملــوك ملوكلــه وأتلــف أثنــاء ذلــك بعــض موجــودات املتجــر؛‬\n‫وطلــب إلزامــه بتســليم موكلــه قيمة املســروقات والتلفيات‪ -‬أقر املدعى‬\n‫عليــه بالســرقة إال أنــه أنكــر ســرقة بعــض األجهــزة التــي يطالــب بهــا‬\n‫املدعــي‪ -‬مــن املقــرر شــرعا أن اليمــن تشــرع يف جانب أقــوى املتداعيني‪-‬‬\n‫وألن جانــب املدعــي تقــوى بإقــرار املدعــى عليــه بالســرقة فيقبــل قولــه‬\n‫فيمــا يتعلــق بنــوع وقيمــة املســروقات‪ -‬لذلــك قــررت احملكمــة توجيــه‬\n‫اليمــن إلــى املدعــي علــى صحــة دعــواه فأداهــا طبــق مــا طلــب منــه‪-‬‬\n‫قضــت احملكمــة بإلــزام املدعــى عليــه بتســليم املدعــي قيمــة املســروقات‬\n‫والتلفيــات املدعــى بهــا‪ -‬عــارض املدعــى عليــه علــى احلكــم‪ -‬قــررت‬\n              ‫محكمــة االســتئناف باألكثريــة املصادقــة علــى احلكــم ‪.‬‬\n\n                                                                                 ‫‪240‬‬\n\f      ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ...‬القاضــي باحملكمــة العامــة‬\n      ‫باجلفــر باألحســاء بنــاء علــى االســتدعاء املقيــد بهــذه احملكمــة برقــم‬\n      ‫‪34644715‬يف ‪1434/3/15‬ه ـ واحملــال إلينــا مــن فضيلــة الرئيــس‬\n      ‫املكلــف برقــم ‪ 34122122‬يف ‪1434/3/15‬ه ـ املتعلقــة بدعوى ســعودي‬\n      ‫بالســجل املدنــي رقــم ‪ ...‬حــال كونــه وكيــا عــن مبوجــب الوكالــة‬\n      ‫الصــادرة مــن كتابــة عــدل اجلفــر برقــم ‪1459‬بتاريــخ ‪1433/3/21‬ه ـ‬\n      ‫ضــد ســعودي بالســجل املدنــي رقــم ‪ ...‬فبموجبــه حضــر لــدي الطرفــان‬\n      ‫يف هــذا اليــوم الســبت تاريــخ ‪1434/4/27‬ه ـ الســاعة التاســعة والنصــف‬\n      ‫صباحــا فادعــى املذكــور قائــا إن املدعــى عليــه ســرق محــل أجهــزة‬\n      ‫كمبيوتــر عائــد ملوكلــي وأطلــب إلزامــه بدفــع قيمــة املســروقات هــذه‬\n      ‫دعــواي فجــرى أفهــام املدعــي وكالــة أن الدعــوى يجــب حتريرهــا‬\n      ‫بذكــر املســروقات وأنواعهــا ومجمــوع املبلــغ الــذي يطالــب بــه موكلــك‬\n      ‫فقــال بأننــي أطلــب إمهالــي للرجــوع إلــى موكلــي وســوف أحــرر دعــواي‬\n      ‫يف اجللســة القادمــة وعليــه جــرى رفــع اجللســة ويف يــوم االثنــن تاريــخ‬\n      ‫‪ 1434/4/20‬ه ـ الســاعة التاســعة والنصــف صباحــا افتتحــت اجللســة‬\n      ‫وفيهــا حضــر املدعــي بالســجل املدنــي رقــم وحضــر حلضــوره املدعــى‬\n      ‫عليــه وبســؤال املدعــي عمــا طلبنــاه مــن وكيلــه قــال بــأن األجهــزة التــي‬\n      ‫ســرقها املدعــى عليــه هــي كمــا يلــي كمبيوتــر محمــول نــوع ‪ ...‬طــراز إل‬\n      ‫‪ 500‬وقيمتــه ألفــان وأربعمائــة وأربعــون ريــاال وكمبيوتــر محمــول نــوع‬\n      ‫إتــش بــي طــراز ‪ ...‬إي إي وقيمتــه مبلــغ الفــان وثالثمائــة وخمســة وأربعــون‬\n      ‫‪ 2345‬ريــال وجهــاز كمبيوتــر محمــول (الب تــوب ) نــوع ‪ ...‬قيمتــه الفــان‬\n\n‫‪241‬‬\n\f‫وأربعمائــة وأربعــون ‪ 2440‬ريــال وجهــاز وكمبيوتــر محمــول (الب تــوب)‬\n‫نــوع ‪ ...‬طــراز ‪ ...15‬وقيمتــه مبلــغ ألفــان وثالثمائــة وخمســة وأربعــون‬\n‫‪ 2345‬ريــال وكمبيوتــر محمــول (الب تــوب ) نــوع ‪ ...‬طــراز ‪ ...‬وقيمتــه‬\n‫مبلــغ ألــف وتســعمائة وســبعون ‪ 1970‬ريــال وكمبيوتــر محمــول (الب‬\n‫تــوب ) نــوع ‪ ...‬طــراز ‪ ...‬وقيمتــه مبلــغ ألــف وثمامنائــة وتســعون ريــال و‬\n‫كمبيوتــر محمــول الب تــوب نــوع ‪ ...‬طــراز ‪ ...‬وقيمتــه ألــف وثمامنائــة‬\n‫وخمســون ريــال و كمبيوتــر محمــول الب تــوب نــوع ‪ ...‬طــراز ‪ ...‬وقيمتــه‬\n‫ألــف وســبعمائة وخمســون ريــال و ثانيــا أجهــزة االتصــال جــواالت جهــاز‬\n‫جــوال نــوع ‪ ...‬طــراز ‪ ...‬وقيمتــه ألــف وثمامنائــة ريــال وجهــاز جــوال نــوع‬\n‫‪ ...‬طــراز ‪ ...‬وقيمتــه ألــف ومائــة ريــال مســتعمل و جهــاز جــوال نــوع ‪...‬‬\n‫طــراز ‪ ...‬وقيمتــه ألــف مائــة وخمســون ريــال و جهــاز جــوال نــوع ‪ ...‬طــراز‬\n‫‪ ...‬وقيمتــه ألــف ومائتــان وخمســون ريــال و جهــاز جــوال نــوع ‪ ...‬طــراز‬\n‫‪ ...‬وقيمتــه ســبعمائة وثمانــون ريــال و جهــاز نــوع ‪ ...‬طــراز ‪ ...‬وقيمتــه‬\n‫ثالثمائــة وخمســون ريــال و جهــاز نــوع ‪ ...‬طــراز ‪ ...‬وقيمتــه ثالثمائــة و‬\n‫خمســة وأربعــون ريــال وجهــاز جــوال نــوع ‪ ...‬طــراز ‪ ...‬وقيمتــه خمســمائة‬\n‫وســبعون ريــال وجهــاز جــوال نــوع ‪ ...‬طــراز ‪ ...‬وقيمتــه ثمامنائــة وخمســون‬\n‫ريــال وجهــاز جــوال نــوع ‪ ...‬طــراز ‪ ...‬وقيمتــه خمســمائة واربعــون ريــال‬\n‫وكذلــك مبلــغ نقــدي كان موجــود ًا يف درج احملــل وقــدره ســتمائة ‪600‬‬\n‫ريــال وكذلــك قــام املدعــى عليــه أثنــاء دخوله من النافــذة العلوية للمحل‬\n‫بكســر ســقف الديكــور وقطــع كابــات االنترنــت وأســاك اللوحــة‬\n‫اخلارجيــة مــع اإلضــاءة وســلك التلفــاز وخــط الهاتــف كمــا كســر طاولة‬\n‫املعــرض الزجاجيــة وكلهــا تقــدر مببلــغ ألــف و أربعمائــة‪ 1400‬ريــال و‬\n‫مجمــوع املبلــغ الــذي أطالــب املدعــى عليــه بدفعــه هــو ثالثــة وعشــرون‬\n\n\n                                                                                     ‫‪242‬‬\n\f      ‫ألــف ‪ 23.000‬ريــال هــذه دعــواي وبســؤال املدعــى عليــه عــن دعــوى‬\n      ‫املدعــي أجــاب قائــا بأننــي فعــا دخلــت احملــل يف املســاء مــن النافــذة‬\n      ‫العلويــة وقــد ســرقت مــن احملــل جهــازي البتــوب اثنــن فقــط وأمــا مــا‬\n      ‫ذكــره املدعــي مــن ســرقتي لعــدة أجهــزه وجــواالت فغيــر صحيــح وقــد‬\n      ‫مت احلكــم علــي يف احلــق العــام مــدة ســنتني مــع اجللــد وقــد خرجــت مــن‬\n      ‫الســجن قبــل انتهــاء املــدة بأربعــة أشــهر وأنــا ال أوافــق علــى دفــع مــا طلبــه‬\n      ‫املدعــي هكــذا أجــاب املدعــى عليــه ثــم جــرى ســؤال املدعــي هــل لديــك‬\n      ‫بينــه علــى أن املدعــى عليــه ســرق األجهــزة املذكــورة فقــال بأنــه ليــس‬\n      ‫لــدي شــهود علــى ذلــك وأنــا أكتفــي بإقــرار املدعــى عليــه بدخــول احملــل‬\n      ‫وســرقة اجلهازيــن ألنــه ليــس لــي أي مصلحــة أن أتهمــه بســرقة شــيء لــم‬\n      ‫يأخــذه وقــد حضــرت الشــرطة وشــاهدت احملــل بعــد ســرقته ومت احلكــم‬\n      ‫علــى املدعــى عليــه مــدة ســنتني مــن أجــل ســرقة األجهــزة املذكــورة‬\n      ‫وإلــى حــن دراســة هــذه القضيــة واالطــاع علــى الطــرد املرفــق بهــا جــرى‬\n      ‫رفــع اجللســة ويف يــوم االثنــن تاريــخ ‪1434/6/5‬ه ـ افتتحــت اجللســة يف‬\n      ‫متــام الســاعة التاســعة والنصــف صباحــا وفيهــا حضــر املدعــى وحضــر‬\n      ‫حلضــوره املدعــى عليــه وقــد ســبق منــي دراســة هــذه القضيــة ومــا ســبق‬\n      ‫ضبطــه فيهــا كمــا جــرى االطــاع علــى قــرار املدعــى عليه املصــدق على‬\n      ‫الصحيفــة رقــم (‪ )7‬مــن ملــف التحقيــق لفــه ( ‪ )2‬ونصــه ( أقــر أنــا احلــدث‬\n      ‫‪ 17‬ســنة ســعودي اجلنســية وأنــا بكامــل قــواي العقليــة املعتبــرة شــرعا‬\n      ‫ال مجبــر وال مكــره مــن أحــد أنــه مــن حوالــي أربعــة أشــهر تقريبــا ويف‬\n      ‫حوالــي الســاعة الثالثــة فجــرا ذهبــت إلــى محــل ‪ ...‬لالتصــاالت الواقــع‬\n      ‫بحــي ‪ ...‬الشــارع العــام وقمــت بتســلق بــاب احملــل حتــى وصلــت إلــى فتحــة‬\n      ‫تهويــة باحملــل وقمــت بالدخــول مــن تلــك الفتحــة إلــى الســطح بعــد ذلــك‬\n\n\n‫‪243‬‬\n\f‫قمــت بفتــح ديكــور الســطح ونزلــت داخــل احملــل وقمــت بســرقة عــدد‬\n‫(‪ )2‬أجهــزة الب تــوب وطلعــت مــن نفــس املــكان الــذي دخلــت منــه وقمت‬\n‫بوضــع األجهــزة بغرفتــي باملنــزل هــذا مــا حــدث وعليــه أوقــع وبعرضــه‬\n‫علــى املدعــى عليــه قــال فعــا أنــا ســرقت جهــازي البتــوب فقــط ولــم‬\n‫أســرق أكثــر مــن ذلــك ثــم جــرى االطــاع علــى فذلكــه التحقيــق لفــه‬\n‫(‪ )25-24‬وتتضمــن بــاغ املدعــي بســرقة أجهــزة كمبيوتــر وجــوالت‬\n‫ومبلــغ مــن املــال وأن املســروقات تقــدر مببلــغ عشــرين الــف‪ 20000‬ريــال‬\n‫وقــد أديــن املدعــى عليــه حتقيقــا بســرقة األجهــزة املذكــورة وبعــرض‬\n‫ذلــك علــى املدعــي قــال بأننــي ذكــرت هــذا املبلــغ للمحقــق يف أول‬\n‫وقــت الســرقة ولكــن بعــد ذلــك قمــت بجــرد املســروقات وتبــن لــي‬\n‫أن املبلــغ هــو مــا ادعيــت بــه علمــا أننــي لــم أضــف مبلــغ إتــاف احملــل‬\n‫والديكــور والزجــاج املكســور واكتفيــت مبــا تأكــدت مــن ســرقته‬\n‫يقينــا لكــي ال أحمــل ذمتــي أي شــيء مشــكوك فيــه ثــم جــرى االطــاع‬\n‫علــى القــرار الصــادر مــن قضــاة احملكمــة العامــة بالدمــام برقــم ‪/9/22‬‬\n‫ج‪ 6‬يف ‪1432/3/9‬ه ـ واملتضمــن احلكــم بتعزيــر املدعــى عليــه بالســجن‬\n‫ســنتني مــع اجللــد مائتــي جلــده واملكتســب القطعيــة بتصديــق محكمــة‬\n‫االســتئناف فبنــاء علــى مــا تقــدم وحيــث طالــب املدعــي بإلــزام املدعــى‬\n‫عليــه بدفــع املبلــغ املدعــى بــه والــذي ميثــل قيمــة املســروقات املذكــورة‬\n‫وحيــث أقــر املدعــى عليــه بدخــول محــل املدعــي وســرقة جهازيــن فقــط‬\n‫وأنكــر الباقــي وحيــث أن املدعــى عليــه مــدان حتقيقــا بســرقة األجهــزة‬\n‫املذكــورة كمــا مت احلكــم عليــه للحــق العــام بالســجن املــدة املذكــورة‬\n‫بالقــرار املشــار إليــه لقــاء ســرقة األجهــزة وحيــث أن ذلــك يقــوي جانــب‬\n‫املدعــي فيمــا أدعــى بــه وحيــث أن أهــل العلــم رحمهــم اهلل ذكــروا بــأن‬\n\n\n                                                                                    ‫‪244‬‬\n\f      ‫اليمــن تكــون يف جانــب أقــوى املتداعيــن وهــو املدعــي هنــا لــذا فقــد‬\n      ‫ســألت املدعــي هــل أنــت مســتعد بــأداء اليمــن فقــال نعــم فجــرى إفهامــه‬\n      ‫بخطــورة اليمــن الكاذبــة فقــال بأننــي واثــق مــن ســرقة املدعــى عليــه‬\n      ‫ثــم أمرتــه أن يحلــف فحلــف قائــا واهلل العظيــم الــذي ال الــه إال هــو أن‬\n      ‫املدعــى عليــه هــذا احلاضــر ســرق مــن محلــي ســت أجهــزه كمبيوتــر‬\n      ‫محمــول وعشــرة جــواالت ومبلــغ نقــدي ســتمائة ريــال ومجمــوع قيمــة مــا‬\n      ‫ســرقه ثالثــة وعشــرون ألــف ‪ 23000‬ريــال واهلل شــاهد علــى مــا أقــول‬\n      ‫هكــذا حلــف املدعــي لذلــك كلــه فقــد ثبــت لــدي مــا أدعــاه املدعــي‬\n      ‫ضــد املدعــى عليــه وألزمــت املدعــى عليــه بدفــع مبلــغ ثالثــة وعشــرين‬\n      ‫ألــف ‪ 23000‬ريــال فــورا للمدعــي وبذلــك حكمــت وبعــرض احلكــم‬\n      ‫علــى املدعــى عليــه قــرر عــدم قناعتــه باحلكــم وطلــب االســتئناف بعــد‬\n      ‫تقــدمي الئحــة اعتــراض فأجبتــه لطلبــه وأفهمتــه مبراجعــة احملكمــة يــوم‬\n      ‫االثنــن تاريــخ ‪1434/6/12‬ه ـ الســتالم صــورة مــن القــرار الشــرعي‬\n      ‫ومــدة االعتــراض ثالثــون يومــا ففهــم ذلــك وصلــى اهلل علــى نبينــا محمــد‬\n                                ‫وعلــى الــه وصحبــه وســلم حــرر يف ‪1434/6/5‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد عــادت األوراق مــن محكمــة االســتئناف‬\n      ‫يف املنطقــة الشــرقية برقــم ‪ 341902688‬يف ‪1434/9/6‬ه ـ املقيــدة‬\n      ‫بهــذه احملكمــة برقــم ‪ 342163918‬يف ‪ 1434/9/10‬ه ـ املرفــق بهــا‬\n      ‫القــرار الصــادر مــن الدائــرة احلقوقيــة الثانيــة برقــم ‪ 34307355‬يف‬\n      ‫‪1434/8/28‬ه ـ املتضمــن املالحظــة علــى احلكــم ونــص املالحظــة مــا‬\n      ‫يلــي ( وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق‬\n      ‫املعاملــة لوحــظ أن صيغــة اليمــن التــي أداهــا املدعي حتتــاج إلى تصحيح‬\n      ‫بحيــث يحلــف بــاهلل العظيــم انــه فقــد مــن محلــه ســتة أجهــزة كمبيوتــر‬\n\n\n‫‪245‬‬\n\f‫محمــول وعشــرة جــواالت ومبلــغ نقــدي مقــداره ســتمائة ريــال وإنــه ال‬\n‫يتهــم إال املدعــى عليــه بســرقة مــا ذكــر وعلــى فضيلتــه مالحظــة مــا‬\n‫ذكــر وإجــراء الــازم بحضــور الطرفــن واهلل املوفــق وصلــى اهلل علــى‬\n‫نبينــا محمــد وعلــى الــه وصحبــه وســلم حــرر يف ‪1434/8/28‬ه ـ قاضــي‬\n‫اســتئناف قاضــي اســتئناف رئيــس الدائــرة وبــه ختــم وتوقيــع كل منهــم‬\n‫عليــه ويف يــوم اخلميــس تاريــخ ‪1434/10/29‬ه ـ افتتحــت اجللســة يف متــام‬\n‫الســاعة العاشــرة والنصــف وفيهــا حضــر املدعــي ولــم يحضــر املدعــى‬\n‫عليــه وبعــرض مــا جــاء يف قــرار محكمــة االســتئناف اســتعد املدعــي‬\n‫بــأداء اليمــن فجــرى إفهامــه بخطــورة اليمــن الكاذبــة ثــم أمرتــه أن‬\n‫يحلــف فحلــف قائــا واهلل العظيــم أننــي فقــدت مــن محلــي ســتة أجهــزة‬\n‫كمبيوتــر محمــول وعشــرة جــواالت ومبلــغ نقــدي مقــداره ســتمائة ‪600‬‬\n‫ريــال وإننــي ال أتهــم إال املدعــى عليــه بســرقتها هكــذا حلــف لــذا فقــد‬\n‫أمــرت بإحلــاق ذلــك بالقــرار وإعادتــه حملكمــة االســتئناف واهلل املوفــق‬\n‫وللبيــان حــرر يف ‪1434/12/4‬ه ـ وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                             ‫آلــه وصحبــه وســلم‪.‬‬\n‫احلمــد هلل وحــده أمــا بعــد فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة احلقوقيــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة‬\n‫املقيــدة لــدى احملكمــة برقــم ‪ 342879195‬وتاريــخ ‪1434/12/25‬ه ـ‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة باجلفــر مبحافظــة اإلحســاء‬\n‫الشــيخ‪ ............. /‬برقــم ‪ 342163918‬وتاريــخ ‪1434/12/19‬ه ـ املرفــق‬\n‫بهــا الصــك الصــادر مــن فضيلتــه املســجل برقــم ‪ 34236377‬وتاريــخ‬\n‫‪1434/6/11‬ه ـ بشــأن دعــوى‪ ...... /‬ضــد‪ ....... /‬يف قضيــة حقوقيــه‬\n‫وقــد تضمــن الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪.‬‬\n\n\n                                                                                      ‫‪246‬‬\n\f      ‫وحيــث ســبق دراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n      ‫وأوراق املعاملــة وباإلطــاع علــى مــا أجــاب بــه فضيلتــه علــى قرارنــا ذي‬\n      ‫الرقــم ‪/34307355‬ق‪/2‬ب والتاريخ‪1434/8/28‬ه ـ قررنــا باألكثريــة‬\n      ‫املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                       ‫وصحبــه وســلم حــرر يف ‪1435/1/16‬ه ـ ‪.‬‬\n\n\n\n\n‫‪247‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":240,"source_page_end":247,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0d1ead798c5bcf95daf63ad524c63d5c38d0feff68927f723d98108d530c9011","normalized_text_hash":"f29f485449349706e3c27693121d63bb7c3fa8d70677c41f3ed875132b691e53","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p240-34236377"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
